local PL3BootClock = os.clock or tick
local PL3BootStart = PL3BootClock()
local PL3BootT = PL3BootStart
-- [src] 00_boot.lua
-- aster for Prison Life (pl3): the pl modules (repo/pl, GitHub test/pl.lua) on the aster v2 library. Generated from repo/pl3/src by repo/_tools_pl3/bundle.js.
local BUILD = "pl3-1"
local FOLDER = "prison life"

local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local UserInputService = game:GetService("UserInputService")
local Workspace = game:GetService("Workspace")
local Lighting = game:GetService("Lighting")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local HttpService = game:GetService("HttpService")
local LocalPlayer = Players.LocalPlayer

local Aster, ThemeManager, SaveManager, loader, win
local Util, F, Pages, Shim
local fetch, bootMark, PL_init

local env = (type(getgenv) == "function" and getgenv()) or _G
local clock = os.clock or tick
local function ms(t0, t1) return math.floor(((t1 or clock()) - t0) * 1000 + 0.5) end
local Boot = { at = PL3BootStart or clock(), timings = {}, marks = {}, missing = {} }

-- a previous pl3 / pl2 copy, and the old Linoria builds (dev.lua TS_*, pl PL_*), would keep running beside this one
do
    local rerun = env.TS_Connections ~= nil or env.PL_Connections ~= nil
    for _, key in ipairs({ "AsterPL3", "AsterPL2" }) do
        local old = env[key]
        if type(old) == "table" and type(old.unload) == "function" then pcall(old.unload) end
    end
    for _, key in ipairs({ "TS_Connections", "PL_Connections" }) do
        for _, connection in ipairs(type(env[key]) == "table" and env[key] or {}) do pcall(function() connection:Disconnect() end) end
        env[key] = nil
    end
    for _, drawing in ipairs(type(env.TS_Drawings) == "table" and env.TS_Drawings or {}) do pcall(function() drawing:Remove() end) end
    env.TS_Drawings = nil
    local linoria = env.Library
    if rerun and type(linoria) == "table" and type(linoria.Unload) == "function" and not linoria.Unloaded then pcall(linoria.Unload, linoria) end
    if type(env.AsterLoader) == "table" and type(env.AsterLoader.destroy) == "function" then pcall(env.AsterLoader.destroy) end
end

-- the GitHub API first: raw.githubusercontent and Fastly are blocked on some networks (same chain as Example.lua)
do
    local API = "https://api.github.com/repos/WhyWKey/linoria/contents/ui-test/"
    local MIRRORS = {
        "https://gcore.jsdelivr.net/gh/WhyWKey/linoria@main/ui-test/",
        "https://testingcf.jsdelivr.net/gh/WhyWKey/linoria@main/ui-test/",
        "https://cdn.jsdelivr.net/gh/WhyWKey/linoria@main/ui-test/",
        "https://raw.githubusercontent.com/WhyWKey/linoria/main/ui-test/",
    }
    local compile = loadstring or load
    local B64 = {}
    for i = 1, 64 do B64[string.byte("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/", i)] = i - 1 end

    local function b64decode(s)
        s = string.gsub(s, "[^%w%+/]", "")
        local out, floor = {}, math.floor
        for i = 1, #s - 1, 4 do
            local a, b, c, d = string.byte(s, i, i + 3)
            local v = B64[a] * 262144 + B64[b] * 4096 + (c and B64[c] or 0) * 64 + (d and B64[d] or 0)
            local x, y, z = floor(v / 65536), floor(v / 256) % 256, v % 256
            out[#out + 1] = d and string.char(x, y, z) or c and string.char(x, y) or string.char(x)
        end
        return table.concat(out)
    end

    local function decode64(s)
        local c = crypt
        for _, f in ipairs({ c and c.base64decode, c and type(c.base64) == "table" and c.base64.decode, base64_decode, base64decode }) do
            local ok, out = pcall(f, s)
            if ok and type(out) == "string" and #out > 0 then return out end
        end
        return b64decode(s)
    end

    local function usable(body)
        if type(body) ~= "string" then return nil, "body " .. tostring(body) end
        if #body < 64 then return nil, #body .. " bytes: " .. string.sub(body, 1, 80) end
        if string.find(body, "^%s*[<{]") then return nil, "error page, " .. #body .. " bytes: " .. string.sub(body, 1, 80) end
        return body
    end

    local function httpGet(url)
        local ok, body = pcall(function() return game:HttpGet(url) end)
        if not ok then return nil, tostring(body) end
        return usable(body)
    end

    local function viaRequest(url, headers)
        local req = request or http_request or (syn and syn.request) or (fluxus and fluxus.request) or (http and http.request)
        if not req then return nil, "no request function" end
        local ok, reply = pcall(req, { Url = url, Method = "GET", Headers = headers })
        if not ok then return nil, tostring(reply) end
        if type(reply) ~= "table" then return nil, "reply " .. tostring(reply) end
        local code = tonumber(reply.StatusCode)
        if code and code >= 400 then return nil, "status " .. tostring(reply.StatusCode) end
        return usable(reply.Body)
    end

    local function viaApiJson(api)
        local ok, json = pcall(function() return game:HttpGet(api) end)
        if not ok then return nil, tostring(json) end
        local content = type(json) == "string" and string.match(json, '"content"%s*:%s*"(.-)"')
        if not content then return nil, "no content in the API reply" end
        local okDecode, src = pcall(decode64, (string.gsub(content, "\\n", "")))
        if not okDecode then return nil, "base64: " .. tostring(src) end
        return usable(src)
    end

    -- path under ui-test/; returns what the chunk returns
    function fetch(path)
        local api = API .. path
        local ways = {
            { "request " .. api, function() return viaRequest(api, { Accept = "application/vnd.github.raw", ["User-Agent"] = "aster" }) end },
            { "HttpGet " .. api, function() return viaApiJson(api) end },
        }
        for _, base in ipairs(MIRRORS) do
            local url = base .. path
            ways[#ways + 1] = { "HttpGet " .. url, function() return httpGet(url) end }
            ways[#ways + 1] = { "request " .. url, function() return viaRequest(url) end }
        end
        local tried, start = {}, clock()
        for _, way in ipairs(ways) do
            local t0 = clock()
            local body, why = way[2]()
            if body then
                local t1 = clock()
                local fn, err = compile(body, "=" .. path)
                if fn then
                    local t2 = clock()
                    print("[aster pl] " .. path .. " from " .. way[1] .. ", " .. #body .. " bytes")
                    local result = fn()
                    Boot.timings[path] = { download = ms(start, t1), compile = ms(t1, t2), run = ms(t2) }
                    return result, body
                end
                why = "compile failed: " .. tostring(err)
            end
            tried[#tried + 1] = "  " .. way[1] .. ": " .. tostring(why) .. " (" .. ms(t0) .. " ms)"
        end
        error("[aster pl] could not load " .. path .. ":\n" .. table.concat(tried, "\n"), 0)
    end
end

local function breathe()
    if task and task.wait then pcall(task.wait) end
end

Aster = fetch("library.lua")
loader = Aster:Loader({ title = "aster", game = "Prison Life", build = BUILD })
loader:Stage("loading addons", 0.15)
breathe()

do
    local function addon(path)
        local ok, mod = pcall(function()
            local m = fetch(path)
            m:SetLibrary(Aster)
            m:SetFolder(FOLDER)
            return m
        end)
        if ok then return mod end
        print(tostring(mod))
        Boot.missing[#Boot.missing + 1] = path
        return nil
    end
    local t0 = clock()
    ThemeManager = addon("addons/thememanager.lua")
    loader:Stage("loading save manager", 0.25)
    breathe()
    SaveManager = addon("addons/savemanager.lua")
    if SaveManager then SaveManager:IgnoreThemeSettings() end
    Boot.addons = ms(t0)
end

Util = { unloaded = false, cleanup = {}, connections = {}, warned = {} }
function F(flag) return Aster.Flags[flag] end
Util.F = F

function Util.track(connection)
    Util.connections[#Util.connections + 1] = connection
    return connection
end

function Util.onUnload(fn)
    Util.cleanup[#Util.cleanup + 1] = fn
end

function Util.note(key, ...)
    if Util.warned[key] then return end
    Util.warned[key] = true
    warn("[aster pl]", ...)
end

function Util.guard(label, fn, ...)
    local ok, result = pcall(fn, ...)
    if not ok then Util.note(label .. tostring(result), label .. ":", result) end
    return ok, result
end

function Util.notify(text, kind, duration)
    pcall(function() Aster:Notify("aster", tostring(text), kind or "info", duration) end)
end

function Util.stage(text, fraction)
    pcall(function() loader:Stage(text, fraction) end)
end

function Util.typing()
    return UserInputService:GetFocusedTextBox() ~= nil
end

function Util.changed(flags, fn)
    if type(flags) == "string" then flags = { flags } end
    local exact, prefixes = {}, {}
    for _, flag in ipairs(flags) do
        if string.sub(flag, -1) == "*" then prefixes[#prefixes + 1] = string.sub(flag, 1, -2) else exact[flag] = true end
    end
    return Util.track(Aster.Changed:Connect(function(flag, value)
        if type(flag) ~= "string" then return end
        local hit = exact[flag]
        if not hit then
            for _, prefix in ipairs(prefixes) do
                if string.sub(flag, 1, #prefix) == prefix then hit = true break end
            end
        end
        if hit then Util.guard("changed " .. flag, fn, flag, value) end
    end))
end

function Util.feature(flag, on, off)
    local active = false
    local function apply(value)
        if value and not active then
            active = true
            if on then Util.guard(flag .. " on", on) end
        elseif not value and active then
            active = false
            if off then Util.guard(flag .. " off", off) end
        end
    end
    Util.track(Aster:OnChanged(flag, function(value) if not Util.unloaded then apply(value) end end))
    Util.onUnload(function() apply(false) end)
    if F(flag) then apply(true) end
    return apply
end

function Util.hook(owner, key, build)
    if type(owner) ~= "table" then return false end
    local original = owner[key]
    if type(original) ~= "function" then return false end
    local ok = pcall(function() owner[key] = build(original) end)
    if not ok then return false end
    Util.onUnload(function() pcall(function() owner[key] = original end) end)
    return true
end

Aster:OnUnload(function()
    Util.unloaded = true
    for index = #Util.cleanup, 1, -1 do pcall(Util.cleanup[index]) end
    Util.cleanup = {}
    for _, connection in ipairs(Util.connections) do pcall(function() connection:Disconnect() end) end
    Util.connections = {}
    if env.AsterPL3 and env.AsterPL3.Util == Util then env.AsterPL3 = nil end
end)

-- called by the bundle after every part: timing plus loader progress
function bootMark(label, started, index, total)
    Boot.marks[#Boot.marks + 1] = { label, (clock() - started) * 1000 }
    if index < total then
        Util.stage("loaded " .. label, 0.3 + 0.55 * index / total)
        breathe()
    end
end

Pages = { tabs = {}, strips = {} }
Shim = {}
bootMark("boot", PL3BootT, 1, 5)

PL3BootT = PL3BootClock()
-- [src] 15_menu.lua
do
    Util.stage("building menu", 0.3)
    win = Aster:Window({
        title = "aster", folder = FOLDER, key = "insert", game = "Prison Life",
        user = { id = LocalPlayer and LocalPlayer.UserId or 0, display = LocalPlayer and LocalPlayer.DisplayName or "", name = LocalPlayer and LocalPlayer.Name or "" },
    })

    -- v2 tab, icon, then { pl "Tab/Sub" key, page name }. The pl Settings tab is the Builtins tab in v2: its Server section lives on misc / server.
    local MENU = {
        { "legit", "combat", { { "Legit/Aim", "aim" }, { "Legit/Silent", "silent" }, { "Legit/Trigger", "trigger" } } },
        { "rage", "kill", { { "Rage/Ragebot", "ragebot" }, { "Rage/Void", "void" }, { "Rage/Gun", "gun" }, { "Rage/Other", "other" } } },
        { "esp", "visuals", { { "ESP/Enemies", "enemies" }, { "ESP/Teammates", "teammates" }, { "ESP/Local", "local" } } },
        { "world", "atmosphere", {
            { "World/Environment", "environment" }, { "World/Sky", "sky" }, { "World/Weather", "weather" }, { "World/Post", "post" }, { "World/Camera", "camera" },
        } },
        { "effects", "shoot", { { "Effects/When I shoot", "shoot" }, { "Effects/When I hit", "hit" }, { "Effects/When I kill", "kill" }, { "Effects/Ambience", "ambience" } } },
        { "misc", "misc", {
            { "Misc/Movement", "movement" }, { "Misc/Character", "character" }, { "Misc/Combat", "combat" }, { "Misc/Vehicles", "vehicles" }, { "Misc/Avatar", "avatar" },
            { "Settings/Main", "server" },
        } },
        { "teleport", "target", { { "Teleport/Main", "teleport" } } },
        { "players", "players", { { "Players/Main", "players" } } },
    }

    -- pl sub-tabs without a page (Builtins does theme and config); sections of such a page, and the hidden ones below, are accepted and dropped
    local NO_PAGE = { "Settings/Theme", "Settings/Config" }
    local HIDDEN = { ["Settings/Main/Aster settings"] = true, ["Settings/Main/Layout"] = true, ["Settings/Main/Unload"] = true }

    -- pl has 3 columns, v2 cards sit on the left or right and the 3-column view balances them; "auto" takes the side with fewer sections on that page
    local COLUMN = { "left", "right", "auto" }

    Pages.pages, Pages.first, Pages.tabOf, Pages.hidden, Pages.column, Pages.side = {}, {}, {}, HIDDEN, COLUMN, {}
    for _, key in ipairs(NO_PAGE) do Pages.pages[key] = false end

    for _, spec in ipairs(MENU) do
        local tab = win:Tab({ name = spec[1], icon = spec[2] })
        Pages.tabs[spec[1]] = tab
        for _, entry in ipairs(spec[3]) do
            local key, name = entry[1], entry[2]
            local plTab = string.match(key, "^([^/]+)/")
            Pages.pages[key] = tab:Page({ name = name })
            Pages.tabOf[plTab] = Pages.tabOf[plTab] or tab
            Pages.first[plTab] = Pages.first[plTab] or { key = key, page = Pages.pages[key] }
        end
    end
end
bootMark("menu", PL3BootT, 2, 5)

PL3BootT = PL3BootClock()
-- [src] 45_shim.lua
-- The pl modules' Library / UI / Options / Toggles surface on aster v2 (CONTRACT.md section 3). Everything lives in this block and ends up in the table Shim,
-- which 99_tail hands to PL_init as `env`. Sections are v2 cards (routes: Pages.* from 15_menu), rows are v2 elements, popups are Settings gears.
do
    local Elements, Flags = Aster.Elements, Aster.Flags
    local MODES = { Hold = "hold", Toggle = "toggle", Always = "always" }
    local TYPES = { toggle = "Toggle", slider = "Slider", dropdown = "Dropdown", color = "ColorPicker", keybind = "KeyPicker", input = "Input", label = "Label" }
    local WHITE = Color3.new(1, 1, 1)
    local stats = { pages = 0, subs = 0, sections = 0, hidden = 0, dropped = 0, rows = 0, failed = 0 }

    local function noop() end

    -- v2 callbacks also get the element; pl callbacks take the value only (a button none)
    local function unary(fn)
        if type(fn) ~= "function" then return nil end
        return function(value) fn(value) end
    end
    local function niladic(fn)
        if type(fn) ~= "function" then return nil end
        return function() fn() end
    end

    -- Decimals is the step (0.05, 0.5), 1 or more means whole numbers. pl's old toRounding turned 0.05 into 0.1 steps and 0.5 into 1, which v2 would anchor at Min (6 became 6.5)
    local function stepOf(decimals)
        if type(decimals) == "number" and decimals > 0 and decimals < 1 then return decimals end
        return 1
    end

    -- keys: pl names mouse buttons MB1..MB3, v2 m1..m3; v2 stores keys lower case
    local keyNames
    local function keyText(key)
        if key == nil or key == "" then return "None" end
        local mouse = string.match(key, "^m(%d)$")
        if mouse then return "MB" .. mouse end
        if not keyNames then
            keyNames = {}
            pcall(function()
                for _, item in ipairs(Enum.KeyCode:GetEnumItems()) do keyNames[string.lower(item.Name)] = item.Name end
            end)
        end
        return keyNames[key] or (#key == 1 and string.upper(key)) or key
    end
    local function keyFix(name)
        if typeof(name) == "EnumItem" then return name.Name end
        local mouse = type(name) == "string" and string.match(string.upper(name), "^MB(%d)$")
        if mouse then return "m" .. mouse end
        return name
    end

    local function listOf(value)
        if type(value) == "string" then return { value } end
        local out = {}
        if type(value) ~= "table" then return out end
        if #value > 0 then
            for _, name in ipairs(value) do out[#out + 1] = tostring(name) end
        else
            for name, chosen in pairs(value) do
                if chosen then out[#out + 1] = tostring(name) end
            end
            table.sort(out)
        end
        return out
    end
    local function mapOf(list)
        local map = {}
        for _, name in ipairs(list) do map[name] = true end
        return map
    end

    -- keys made without Sync keep their own state: they do not follow the parent toggle (hold = key down, always = true); Sync keys flip the toggle
    local loose = setmetatable({}, { __mode = "k" })
    local synced = setmetatable({}, { __mode = "k" })
    local blocked = {}
    -- a single dropdown made without a Default reads nil until one is picked (Linoria); v2 would pick the first option on SetOptions
    local blank = setmetatable({}, { __mode = "k" })
    local blankFlags = {}

    local Option = {}
    local function valueOf(el)
        local value = el.Value
        if el.Kind == "dropdown" and el.Opts.multi then return mapOf(value) end
        if value == "" and blank[el] then return nil end
        if el.Kind == "keybind" then return keyText(value.key) end
        return value
    end
    function Option.__index(self, key)
        local method = rawget(Option, key)
        if method ~= nil then return method end
        local el = rawget(self, "_el")
        if key == "Value" then return valueOf(el) end
        if key == "Type" then return TYPES[el.Kind] end
        if key == "Transparency" then
            if el.Kind == "color" and not el.Opts.opaque then return 1 - el:Alpha() end
            return nil
        end
        if key == "Mode" and el.Kind == "keybind" then
            for name, mode in pairs(MODES) do
                if mode == el.Value.mode then return name end
            end
        end
        if key == "SyncToggleState" and el.Kind == "keybind" then return synced[el] == true end
        if key == "Values" and el.Kind == "dropdown" then return el:Options() end
        return nil
    end
    function Option:SetValue(value)
        local el = rawget(self, "_el")
        local reason = blocked[el.Flag]
        if reason then
            if value then Util.notify(reason.name .. ": " .. reason.why, "warn", 3) end
            value = false
        end
        if el.Kind == "dropdown" and el.Opts.multi then
            value = listOf(value)
        elseif value == nil and blank[el] then
            value = ""
        elseif el.Kind == "keybind" then
            if type(value) == "table" then value = { key = keyFix(value[1]), mode = MODES[value[2]] or el.Value.mode } else value = keyFix(value) end
        end
        el:Set(value)
    end
    function Option:SetValueRGB(color, transparency)
        local el = rawget(self, "_el")
        if el.Kind ~= "color" then return end
        el:Set(color)
        if type(transparency) == "number" and not el.Opts.opaque then el:SetAlpha(1 - transparency) end
    end
    -- Linoria kept selected names that left the list (players who left stay whitelisted); v2 SetOptions drops them
    function Option:SetValues(list)
        local el = rawget(self, "_el")
        if el.Kind ~= "dropdown" then return end
        if el.Opts.multi and type(list) == "table" then
            local merged, listed = {}, {}
            for _, name in ipairs(list) do
                merged[#merged + 1] = name
                listed[tostring(name)] = true
            end
            for _, name in ipairs(el.Value) do
                if not listed[name] then merged[#merged + 1] = name end
            end
            list = merged
        end
        el:SetOptions(list)
    end
    function Option:OnChanged(fn)
        local el = rawget(self, "_el")
        return el.Changed:Connect(function() fn(valueOf(el)) end)
    end
    function Option:OnClick(fn)
        local el = rawget(self, "_el")
        if el.Pressed then return el.Pressed:Connect(function() fn() end) end
        return nil
    end
    function Option:GetState()
        local el = rawget(self, "_el")
        if el.Kind == "keybind" then
            if loose[el] then
                local mode = el.Value.mode
                if mode == "hold" then return el.Value.key ~= "" and el._held == true end
                if mode == "always" then return true end
            end
            return el:Active()
        end
        if el.Kind == "toggle" then return el.Value == true end
        return true
    end

    -- Options / Toggles are plain tables (45_fx_menu iterates them), filled as rows are made; other flags (Builtins, addons) resolve through __index
    local objects = setmetatable({}, { __mode = "k" })
    local function wrap(el)
        local object = objects[el]
        if not object then
            object = setmetatable({ _el = el }, Option)
            objects[el] = object
        end
        return object
    end
    local Options, Toggles = {}, {}
    local function fallback(wantToggle)
        return function(_, flag)
            local el = type(flag) == "string" and Elements[flag] or nil
            if not el or (el.Kind == "toggle") ~= wantToggle then return nil end
            local object = wrap(el)
            rawset(wantToggle and Toggles or Options, flag, object)
            return object
        end
    end
    setmetatable(Options, { __index = fallback(false) })
    setmetatable(Toggles, { __index = fallback(true) })

    local function register(flag, el)
        if type(flag) ~= "string" then return end
        if el.Kind == "toggle" then Toggles[flag] = wrap(el) else Options[flag] = wrap(el) end
    end

    -- the flag() hot path: a direct Aster.Flags read; multi dropdowns come back as a name map and keys as their name, cached per stored value
    local converted = {}
    local function convert(name, value)
        local el = Elements[name]
        if not el then return value end
        local kind = el.Kind
        if kind == "dropdown" and not el.Opts.multi then return value end
        if kind ~= "dropdown" and kind ~= "keybind" then return value end
        local hit = converted[name]
        if hit and hit[1] == value then return hit[2] end
        local out
        if kind == "keybind" then out = keyText(value.key) else out = mapOf(value) end
        converted[name] = { value, out }
        return out
    end
    local function fastFlag(name, default)
        local value = Flags[name]
        if value == nil then return default end
        if type(value) == "table" then return convert(name, value) end
        if value == "" and blankFlags[name] then return default end
        return value
    end
    local function opacity(name)
        local el = Elements[name]
        if el and el.Kind == "color" then return el:Alpha() end
        return 1
    end
    local function alpha(name, default)
        local el = Elements[name]
        if el and el.Kind == "color" and not el.Opts.opaque then return 1 - el:Alpha() end
        return default or 0
    end

    -- Depends: { {flag, value | function(value)}, ... }, every condition must hold. A condition on a flag that does not exist yet is dropped (as the old box did)
    local function satisfied(conds)
        for _, cond in ipairs(conds) do
            local value, want = fastFlag(cond[1]), cond[2]
            if type(want) == "function" then
                local ok, result = pcall(want, value)
                if not (ok and result) then return false end
            elseif value ~= want then
                return false
            end
        end
        return true
    end
    local function depOf(conds)
        if #conds == 1 and type(conds[1][2]) ~= "function" then
            local el = Elements[conds[1][1]]
            if el and el.Kind ~= "keybind" and not (el.Kind == "dropdown" and el.Opts.multi) then return { conds[1][1], conds[1][2] } end
        end
        return function() return satisfied(conds) end
    end
    local function merge(parent, added)
        local out = {}
        for _, cond in ipairs(parent or {}) do out[#out + 1] = cond end
        for _, cond in ipairs(added) do
            if type(cond[1]) == "string" and Elements[cond[1]] ~= nil then out[#out + 1] = cond end
        end
        return out
    end

