        local State = Main:Toggle({ Name = "Status flags", Flag = key("state"), Tooltip = "Hostile, Trespassing, Tased and Forcefield next to the box" }):Settings("Status flags", 200)
        pickColor(State, "Flags", key("state_color"), Color3.fromRGB(255, 200, 80))

        local Skel = Main:Toggle({ Name = "Skeleton", Flag = key("skeleton") }):Settings("Skeleton", 200)
        pickColor(Skel, "Skeleton", key("skeleton_color"), WHITE)
