            Skel:Toggle({ Name = "Outline", Flag = "esp_skel_outline", Default = true })
            Skel:Toggle({ Name = "Joint dots", Flag = "esp_skel_joints" })
        end
        local Dot = Main:Toggle({ Name = "Head dot", Flag = key("dot") }):Settings("Head dot", 200)
