                box:Slider({ Name = "Ghost copies", Flag = "cham_ghost_count", Min = 1, Max = 8, Default = 5, Decimals = 1 })
                box:Slider({ Name = "Ghost spacing", Flag = "cham_ghost_spacing", Min = 0.3, Max = 4, Default = 1.2, Decimals = 0.1, Suffix = " studs" })
                box:Slider({ Name = "Ghost trail length", Flag = "cham_ghost_length", Min = 0.15, Max = 1.5, Default = 0.6, Decimals = 0.05, Suffix = " s" })
