    local function buildLocal(sub)
        local Body, Tool, Self = sub["Local character"], sub["Tool visuals"], sub["Self chams"]
        local Mat = Body:Toggle({ Name = "Character material", Flag = "self_body", Tooltip = "Restyles your own body parts; restored when turned off" }):Settings("Character material", 220)
