        Gun:Dropdown({ Name = "Material", Flag = "self_tool_material", Items = MATERIALS, Default = "Neon" })
        pickColor(Gun, "Colour", "self_tool_color", Color3.fromRGB(120, 200, 255), 0)
        local GunCham = Tool:Toggle({ Name = "Tool chams", Flag = "self_tool_chams" }):Settings("Tool chams", 200)
        pickColor(GunCham, "Fill", "self_tool_chams_fill", Color3.fromRGB(120, 80, 255), 0.4)
        pickColor(GunCham, "Outline", "self_tool_chams_outline", WHITE, 0)

        local Cham = Self:Toggle({ Name = "Self chams", Flag = "self_chams" }):Settings("Self chams", 220)
        pickColor(Cham, "Fill", "self_chams_fill", Color3.fromRGB(150, 110, 255), 0.5)
        pickColor(Cham, "Outline", "self_chams_outline", WHITE, 0)
        Cham:Dropdown({ Name = "Depth", Flag = "self_chams_depth", Items = { "Always on top", "Occluded" }, Default = "Always on top" })
        Cham:Dropdown({ Name = "Style", Flag = "self_chams_style", Items = { "Classic", "Pulse" }, Default = "Classic" })
        Cham:Slider({ Name = "Pulse speed", Flag = "self_chams_speed", Min = 0.1, Max = 4, Default = 1, Decimals = 0.1 })
    end

    local page = Pages and Pages.ESP
    if page then
        if page.Enemies then Util.guard("menu esp enemies", buildTeam, page.Enemies, "esp_enemy_", "Enemy", Color3.fromRGB(255, 70, 90), Color3.fromRGB(170, 60, 255), true) end
        if page.Teammates then Util.guard("menu esp team", buildTeam, page.Teammates, "esp_team_", "Teammate", Color3.fromRGB(90, 220, 130), Color3.fromRGB(60, 150, 255)) end
        if page.Local then Util.guard("menu esp local", buildLocal, page.Local) end
    end
end
