            { count = 12, props = { Lifetime = NumberRange.new(0.3, 0.6), Speed = NumberRange.new(6, 14), Drag = 4, Size = Tracers.curve(0, 0.3 * p, 1, 0), Color = ColorSequence.new(WHITE, ctx.colorAt(1)) } },
        })
        return finish
