            { count = 16, props = { Lifetime = NumberRange.new(0.3, 0.7), Speed = NumberRange.new(6, 14), Drag = 4, Size = Tracers.curve(0, 0.25 * p, 1, 0), Color = ColorSequence.new(WHITE, edge(ctx.colorAt(1))) } },
        })
