            RotSpeed = NumberRange.new(-40, 40), Size = Tracers.curve(0, 0.5 * s, 1, 2.4 * s), Transparency = Tracers.curve(0, math.max(0.35, ctx.alpha), 1, 1),
            Color = ColorSequence.new(blood, Util.lerpColor(blood, BLACK, 0.4)),
