    HitFx.build["Crit star"] = function(rec, ctx)
        local s = ctx.size
        local gold = Util.lerpColor(ctx.color, Color3.fromRGB(255, 215, 80), 0.5)
        for _, turn in ipairs({ 0, 45 }) do
