        Cham:Slider({ Name = "Reflectance", Flag = "chams_dead_refl", Min = 0, Max = 1, Default = 0, Decimals = 0.01 })
        Cham:Toggle({ Name = "Hide clothing/accessories", Flag = "chams_dead_hide", Tooltip = "Hides everything on the body except the body parts" })
        Cham:Slider({ Name = "Fade out time", Flag = "chams_dead_fade", Min = 0, Max = 10, Default = 0, Decimals = 0.1, Suffix = " s", Tooltip = "Fades the body out over this long after death; 0 is off" })
    end)

    local events = Game.events
    events.onOwnShot:Connect(function(origin, hitPos, part, behavior) Tracers.enqueue(origin, hitPos, part, behavior, true) end)
    events.onEnemyShot:Connect(function(shooter, origin, hitPos, behavior) Tracers.enqueue(origin, hitPos, nil, behavior, false, shooter) end)
    events.onHit:Connect(Feedback.hit)
    events.onKill:Connect(Feedback.kill)
    events.onLocalDied:Connect(Feedback.died)
    Game.tracerFilter = Tracers.filter
    Util.onUnload(function()
        if Game.tracerFilter == Tracers.filter then Game.tracerFilter = nil end
    end)

    local function center(cam)
        local size = cam.ViewportSize
        local point = Vector2.new(size.X / 2, size.Y / 2)
        if flag("hit_marker_mouse", true) then
            local ok, mouse = pcall(UserInputService.GetMouseLocation, UserInputService)
            if ok and typeof(mouse) == "Vector2" then point = mouse end
        end
        return point
    end

    local function step(dt, now)
        Util.guard("fx events", Feedback.drain)
        local cam = Game.camera()
        if cam then Util.guard("feedback", Feedback.step, cam, center(cam), now) end
        Util.guard("bulletfx", Tracers.drain, now)
        Util.guard("tracers", Tracers.step, now)
        Util.guard("impacts", Impacts.step, now)
        Util.guard("hitchams", HitCham.step, now)
        Util.guard("hitfx", HitFx.step, now)
        Util.guard("corpse", Corpse.step, now)
        Util.guard("killfx", KillFx.step, now)
        Util.guard("killcam", Killcam.step, now)
        Util.guard("streak", Streak.step, now)
    end

    Util.fx = { Tracers = Tracers, Impacts = Impacts, Feedback = Feedback, Killcam = Killcam, Streak = Streak, HitCham = HitCham, HitFx = HitFx, Corpse = Corpse, KillFx = KillFx, GunSounds = Feedback.GunSounds, step = step, sections = Sections, resetSection = Sections.reset }
    Util.systems = Util.systems or {}
    table.insert(Util.systems, { name = "fx", fn = step, priority = 120 })
end
-- pl 50_combat 1-3313

do
    local Combat = { wants = {}, hits = {} }
    Util.combat = Combat
    Util.systems = Util.systems or {}
    local rand = Random and Random.new() or nil
    local ZERO = Vector3.new(0, 0, 0)
    local clock = os.clock

    local function random(a, b)
        if rand then return rand:NextNumber(a or 0, b or 1) end
        return (a or 0) + math.random() * ((b or 1) - (a or 0))
    end
    Combat.random = random

    local function has(value, key)
        if type(value) ~= "table" then return value == key end
        if value[key] == true then return true end
        for _, selected in pairs(value) do
            if selected == key then return true end
        end
        return false
    end
    Combat.has = has

    function Combat.aimRef()
        local cam = Game.camera()
        local ok, locked = pcall(function() return UserInputService.MouseBehavior == Enum.MouseBehavior.LockCenter end)
        if ok and locked and cam then return cam.ViewportSize / 2 end
        return UserInputService:GetMouseLocation()
    end

    function Combat.localParts()
        local character = Game.localCharacter()
        if not character then return nil end
        return character, Game.humanoid(character), character:FindFirstChild("HumanoidRootPart"), character:FindFirstChild("Head")
    end

    function Combat.isGun(tool)
        if not tool then return false end
        local kind = tool:GetAttribute("ToolType")
        if kind ~= nil then return kind == "Gun" end
        return tool:FindFirstChild("Muzzle") ~= nil
    end

    function Combat.gun()
        local tool = Game.weapon()
        if Combat.isGun(tool) then return tool end
        return nil
    end

    function Combat.readyGun()
        local tool = Combat.gun()
        if not tool then return false end
        if tool:GetAttribute("Local_IsShooting") then return false end
        if (tool:GetAttribute("Local_ReloadSession") or 0) > 0 then return false end
        return (tool:GetAttribute("Local_CurrentAmmo") or tool:GetAttribute("CurrentAmmo") or 0) > 0
    end

    function Combat.gunState()
        local tool = Combat.gun()
        if not tool then return nil, true, false end
        local ammo = tool:GetAttribute("Local_CurrentAmmo")
        local reloading = (tool:GetAttribute("Local_ReloadSession") or 0) > 0
        return tool, (ammo ~= nil and ammo <= 0) or reloading, reloading
    end

    function Combat.toolKey(name)
        return (string.gsub(string.lower(tostring(name or "")), "[^%w]", ""))
    end

    Combat.WEAPONS = { "AK-47", "M4A1", "MP5", "FAL", "Remington 870", "M700", "M9", "Revolver", "Taser" }
    local ALIASES = {
        ["AK-47"] = { "ak47" }, ["M4A1"] = { "m4a1", "m4" }, ["MP5"] = { "mp5" }, ["FAL"] = { "fal" },
        ["Remington 870"] = { "remington870", "r870", "remington" }, ["M700"] = { "m700" }, ["M9"] = { "m9" },
        ["Revolver"] = { "revolver" }, ["Taser"] = { "taser" },
    }

    function Combat.findWeapon(label)
        local aliases = ALIASES[label]
        if not aliases then return nil end
        local holders = { Game.localCharacter(), LocalPlayer:FindFirstChildOfClass("Backpack") }
        for _, holder in ipairs(holders) do
            if holder then
                for _, child in ipairs(holder:GetChildren()) do
                    if child:IsA("Tool") then
                        local key = Combat.toolKey(child.Name)
                        for _, alias in ipairs(aliases) do
                            if key == alias then return child end
                        end
                    end
                end
            end
        end
        return nil
    end

    function Combat.findPlayer(text)
        text = string.lower(tostring(text or ""))
        if text == "" then return nil end
        local partial, inside
        for _, player in ipairs(Players:GetPlayers()) do
            local name, display = string.lower(player.Name), string.lower(player.DisplayName or player.Name)
            if name == text or display == text then return player end
            if not partial and (string.sub(name, 1, #text) == text or string.sub(display, 1, #text) == text) then partial = player end
            if not inside and (string.find(name, text, 1, true) or string.find(display, text, 1, true)) then inside = player end
        end
        return partial or inside
    end

    function Combat.displayName(player)
        local display = player and player.DisplayName
        if type(display) == "string" and display ~= "" then return display end
        return player and player.Name or "?"
    end

    function Combat.peaceful(player)
        return Game.team(player) == "Inmates" and not Game.state(player).hostile
    end

    function Combat.down(record)
        local state = record.state or Game.state(record.player)
        return state.tased or (record.model and record.model:GetAttribute("Arrested") == true)
    end

    function Combat.style(fillFlag, lineFlag, tracerFlag)
        local style = {
            fill = flag(fillFlag, WHITE), fillT = Util.alpha(fillFlag, 0.6),
            line = flag(lineFlag, WHITE), lineT = Util.alpha(lineFlag, 0),
        }
        if tracerFlag then style.tracer, style.tracerT = flag(tracerFlag, WHITE), Util.alpha(tracerFlag, 0) end
        return style
    end

    local Gun = { shoot = nil, cast = nil, hooked = nil, original = nil, tries = 0, nextTry = 0, failed = false }
    Combat.Gun = Gun

    local function functionName(fn)
        local info = Compat.info
        if type(info) ~= "function" then return nil end
        local ok, name = pcall(info, fn, "n")
        return ok and name or nil
    end

    local function upvalue(fn, index)
        local get = Compat.getupvalue
        if type(get) ~= "function" then return nil end
        local ok, value = pcall(get, fn, index)
        return ok and value or nil
    end

    local function actionArea()
        local gui = LocalPlayer:FindFirstChild("PlayerGui")
        local home = gui and gui:FindFirstChild("Home")
        local hud = home and home:FindFirstChild("hud")
        return hud and hud:FindFirstChild("ActionArea")
    end

    local function castOf(shoot)
        for index = 1, 40 do
            local value = upvalue(shoot, index)
            if type(value) == "function" and functionName(value) == "castRay" then return value end
        end
        local fallback = upvalue(shoot, 16)
        if type(fallback) == "function" then return fallback end
        return nil
    end

    local function findByConnections()
        if type(Compat.getconnections) ~= "function" then return false end
        local area = actionArea()
        if not area then return false end
        local ok, list = pcall(Compat.getconnections, area.InputBegan)
        if not ok or type(list) ~= "table" then return false end
        for _, connection in ipairs(list) do
            local fn = connection.Function
            local shoot = fn and upvalue(fn, 2)
            if type(shoot) == "function" then
                local cast = castOf(shoot)
                if cast then
                    Gun.shoot, Gun.cast = shoot, cast
                    return true
                end
            end
        end
        return false
    end

    local function sourceOf(fn)
        local info = Compat.info
        if type(info) ~= "function" then return "" end
        local ok, source = pcall(info, fn, "s")
        return ok and tostring(source) or ""
    end

    local function findCastByGc()
        local function accept(fn)
            if type(fn) ~= "function" then return false end
            if Compat.isexecutorclosure and Compat.isexecutorclosure(fn) then return false end
            return functionName(fn) == "castRay" and string.find(sourceOf(fn), "GunController", 1, true) ~= nil
        end
        for _, getter in ipairs({ Compat.filtergc and function() return Compat.filtergc("function", { Name = "castRay" }) end or false, Compat.getgc or false }) do
            if type(getter) == "function" then
                local ok, list = pcall(getter)
                if ok and type(list) == "table" then
                    for _, fn in ipairs(list) do
                        if accept(fn) then return fn end
                    end
                end
            end
        end
        return nil
    end

    function Gun.find()
        if findByConnections() then return true end
        local cast = findCastByGc()
        if cast then
            Gun.cast = cast
            return true
        end
        return false
    end

    function Gun.info()
        return Game.weaponInfo(Combat.gun())
    end

    function Gun.range(info)
        info = info or Gun.info()
        local range = tonumber(info.Range)
        if range and range > 0 then return range end
        return nil
    end

    function Gun.fire()
        if Gun.shoot then
            local input = { UserInputState = Enum.UserInputState.Begin, UserInputType = Enum.UserInputType.MouseButton1, Position = ZERO }
            task.spawn(Gun.shoot, input)
            input.UserInputState = Enum.UserInputState.End
            return true
        end
        return pcall(function()
            local vim = game:GetService("VirtualInputManager")
            local mouse = UserInputService:GetMouseLocation()
            vim:SendMouseButtonEvent(mouse.X, mouse.Y, 0, true, game, 0)
            task.delay(0.03, function() vim:SendMouseButtonEvent(mouse.X, mouse.Y, 0, false, game, 0) end)
        end)
    end

    local HIT_GROUPS = {
        Head = { "Head" }, Torso = { "Torso", "UpperTorso" }, Root = { "HumanoidRootPart" },
        ["Left arm"] = { "Left Arm", "LeftUpperArm" }, ["Right arm"] = { "Right Arm", "RightUpperArm" },
        ["Left leg"] = { "Left Leg", "LeftUpperLeg" }, ["Right leg"] = { "Right Leg", "RightUpperLeg" },
    }
    Combat.HIT_POINTS = { "Head", "Torso", "Root", "Left arm", "Right arm", "Left leg", "Right leg" }
    local MP_OFFSETS = { Vector3.new(1, 0, 0), Vector3.new(-1, 0, 0), Vector3.new(0, 1, 0), Vector3.new(0, -1, 0), Vector3.new(0, 0, 1), Vector3.new(0, 0, -1) }
    local sight = Game.newParams()

    function Combat.visibleFrom(from, model, at)
        if not sight then return true end
        local list = { Game.camera() }
        local own = Game.localCharacter()
        if own then list[#list + 1] = own end
        if model then list[#list + 1] = model end
        pcall(function() sight.FilterDescendantsInstances = list end)
        return Game.cast(from, at - from, sight) == nil
    end

    local function hitParts(record, prefix)
        local value = flag(prefix .. "_points", { "Head" })
        local list, any = {}, false
        for _, group in ipairs(Combat.HIT_POINTS) do
            if has(value, group) then
                any = true
                for _, name in ipairs(HIT_GROUPS[group]) do
                    local part = record.parts and record.parts[name] or record.model:FindFirstChild(name)
                    if part and part:IsA("BasePart") then list[#list + 1] = part break end
                end
            end
        end
        if not any and record.head then list[1] = record.head end
        return list
    end

    local function partPoints(part, multipoint, scale)
        if not multipoint then return { part.Position } end
        local half = part.Size * 0.5 * scale
        local list = { part.Position }
        for _, offset in ipairs(MP_OFFSETS) do
            list[#list + 1] = part.CFrame:PointToWorldSpace(Vector3.new(half.X * offset.X, half.Y * offset.Y, half.Z * offset.Z))
        end
        return list
    end

    function Combat.allowed(record, prefix, opts)
        local player = record.player
        local relation = Game.relations[player.UserId]
        if relation == "Friendly" then return false end
        if flag(prefix .. "_team", true) and not record.enemy and relation ~= "Priority" then return false end
        if flag(prefix .. "_ff", false) and record.state and record.state.forcefield then return false end
        if flag(prefix .. "_hostile", false) and Combat.peaceful(player) then return false end
        if (opts.ignoreDown or flag(prefix .. "_ignore_down", false)) and Combat.down(record) then return false end
        return true
    end

    Combat.dyn = {}
    function Combat.select(prefix, ref, from, opts)
        opts = opts or {}
        local cam = Game.camera()
        if not cam or not from then return nil end
        local baseFov = opts.fov or flag(prefix .. "_fov", 120)
        local dynamic = flag(prefix .. "_dynamic", false)
        local amount = flag(prefix .. "_dynamic_amount", 50) / 100
        local dynMode = flag(prefix .. "_dynamic_mode", "Distance")
        local nearD, farD = flag(prefix .. "_dyn_near", 25), flag(prefix .. "_dyn_far", 300)
        local targetMode = flag(prefix .. "_target", "Crosshair")
        local sticky = flag(prefix .. "_sticky", 30) / 100
        local maxDist = math.min(flag(prefix .. "_max_dist", 1000), opts.limit or math.huge)
        local priority = flag(prefix .. "_priority", "Closest")
        local multipoint = flag(prefix .. "_multipoint", false)
        local mpScale = flag(prefix .. "_mp_scale", 70) / 100
        local wall = flag(prefix .. "_wall", false) and not opts.skipWall
        local best = { score = nil }
        for _, record in ipairs(Entities.update()) do
            if (not opts.only or record.player == opts.only) and record.root and Combat.allowed(record, prefix, opts) then
                local distance = (record.root.Position - from).Magnitude
                if distance <= maxDist then
                    local radius = baseFov
                    if dynamic and dynMode ~= "Cursor" then
                        local t = math.clamp((distance - nearD) / math.max(farD - nearD, 1), 0, 1)
                        radius = baseFov * ((1 + amount) * (1 - t) + (1 - amount * 0.75) * t)
                    end
                    for _, part in ipairs(hitParts(record, prefix)) do
                        for _, point in ipairs(partPoints(part, multipoint, mpScale)) do
                            local screen, onScreen = Draw.project(cam, point)
                            if onScreen then
                                local d = (screen - ref).Magnitude
                                local partRadius = radius
                                if dynamic and dynMode ~= "Distance" and (opts.current == record.player or d <= baseFov * 0.45) then partRadius = radius * (1 + amount) end
                                if (opts.ignoreFov or d <= partRadius) and (not wall or Combat.visibleFrom(from, record.model, point)) then
                                    local score = d
                                    if targetMode == "Distance" then score = distance + d * 0.001
                                    elseif targetMode == "Lowest health" then score = record.health * 10 + d * 0.05 end
                                    if opts.current == record.player then score = score * (1 - sticky * 0.6) end
                                    if priority == "Head" and part ~= record.head then score = score + 1000 end
                                    if priority == "Body" and part == record.head then score = score + 1000 end
                                    if Game.relations[record.player.UserId] == "Priority" then score = score - 100000 end
                                    if not best.score or score < best.score then
                                        best = { score = score, record = record, part = part, d = d, radius = partRadius, point = point }
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end
        Combat.dyn[prefix] = best.radius
        return best.record, best.part, best.d, best.point
    end

    local Predict = { tracks = {}, boost = 0 }
    Combat.predict = Predict
    local TRACK_AGE = 0.45

    function Predict.wanted()
        return flag("silent_pred", false) or flag("rb_pred", false) or flag("aim_pred", false) or (Combat.rage and Combat.rage.tune.force)
    end

    function Predict.step(_, now, records)
        if not Predict.wanted() then
            if next(Predict.tracks) then Predict.tracks = {} end
            return
        end
        local seen = {}
        for _, record in ipairs(records) do
            if record.root then
                seen[record.player] = true
                local list = Predict.tracks[record.player] or {}
                Predict.tracks[record.player] = list
                list[#list + 1] = { now, record.root.Position }
                while #list > 0 and now - list[1][1] > TRACK_AGE do table.remove(list, 1) end
            end
        end
        for player in pairs(Predict.tracks) do
            if not seen[player] then Predict.tracks[player] = nil end
        end
    end

    function Predict.velocity(player, root)
        local list = Predict.tracks[player]
        local assembly = root and root.AssemblyLinearVelocity or ZERO
        if not list or #list < 3 then return assembly, 0 end
        local first, last = list[1], list[#list]
        local span = last[1] - first[1]
        if span < 0.08 then return assembly, 0 end
        local velocity = (last[2] - first[2]) / span
        local mid = list[math.ceil(#list / 2)]
        local change = 0
        if mid[1] - first[1] > 0.03 and last[1] - mid[1] > 0.03 then
            local a = (mid[2] - first[2]) / (mid[1] - first[1])
            local b = (last[2] - mid[2]) / (last[1] - mid[1])
            change = (b - a).Magnitude
        end
        if assembly.Magnitude > velocity.Magnitude * 1.6 and assembly.Magnitude < 400 then velocity = assembly end
        return velocity, change
    end

    function Predict.ping()
        local ms
        pcall(function() ms = game:GetService("Stats").Network.ServerStatsItem["Data Ping"]:GetValue() end)
        if type(ms) ~= "number" or ms ~= ms or ms <= 0 then
            local ok, one = pcall(function() return LocalPlayer:GetNetworkPing() end)
            ms = ok and type(one) == "number" and one * 2000 or 100
        end
        return math.clamp(ms, 0, 800) / 1000
    end

    function Predict.lead(prefix)
        local lead
        if flag(prefix .. "_pred_auto", true) then
            lead = Predict.ping() * 0.75 + flag(prefix .. "_pred_extra", 0.02)
        else
            lead = flag(prefix .. "_pred_base", 0.07)
        end
        return math.clamp(lead * (flag(prefix .. "_pred_mult", 1) + (prefix == "rb" and Predict.boost or 0)), 0, 1)
    end

    function Predict.point(record, part, origin, prefix)
        local position = part.Position
        if not record or not record.root then return position, "no track", false end
        local velocity, change = Predict.velocity(record.player, record.root)
        if velocity.Magnitude < 1.5 then return position, "standing", true end
        local floor = record.humanoid and record.humanoid.FloorMaterial
        if floor ~= nil and floor ~= Enum.Material.Air and math.abs(velocity.Y) < 14 then velocity = Vector3.new(velocity.X, 0, velocity.Z) end
        local check = flag(prefix .. "_pred_check", true)
        local offset = velocity * Predict.lead(prefix)
        local note = string.format("%d st/s", math.floor(velocity.Magnitude))
        if check and change > flag(prefix .. "_pred_erratic", 45) then
            offset = offset * 0.4
            note = note .. ", erratic"
        end
        local cap = flag(prefix .. "_pred_cap", 25)
        if offset.Magnitude > cap then offset = offset.Unit * cap end
        local goal = position + offset
        if not check then return goal, note, true end
        local WB = Combat.wb
        WB.refresh(true)
        local wall = WB.params and offset.Magnitude > 0.01 and Workspace:Raycast(position, offset, WB.params)
        if wall then
            goal = wall.Position - offset.Unit * 0.6
            note = note .. ", wall clamp"
        end
        if typeof(origin) == "Vector3" then
            local range = Gun.range()
            if range and (goal - origin).Magnitude > range then return position, note .. ", out of range", false end
            if WB.params and not Workspace:Raycast(origin, position - origin, WB.params) and Workspace:Raycast(origin, goal - origin, WB.params) then
                return position, note .. ", no line", false
            end
        end
        return goal, note, true
    end

    local WB = { cache = {}, history = {}, moved = 0, lastTick = 0, warned = false }
    Combat.wb = WB
    WB.params = Game.newParams()
    pcall(function() WB.params.CollisionGroup = "ClientBullet" end)
    pcall(function()
        WB.overlap = OverlapParams.new()
        WB.overlap.FilterType = Enum.RaycastFilterType.Exclude
        WB.overlap.CollisionGroup = "ClientBullet"
    end)
    WB.METHODS = { "Aster Reach", "Aster Origin", "Aster Precise", "Vape V4" }
    local FLAT = Vector3.new(1, 0, 1)
    local UP = Vector3.new(0, 1, 0)
    local NORMALS = { Vector3.new(1, 0, 0), Vector3.new(-1, 0, 0), UP, Vector3.new(0, -1, 0), Vector3.new(0, 0, 1), Vector3.new(0, 0, -1) }
    local OFFSETS_NEAR, OFFSETS_HIGH = {}, {}
    for _, row in ipairs({
        { 0, 1, 0 }, { 1, 0, 0 }, { 0.7, -0.5, -0.5 }, { -0.1, -0.8, -0.8 }, { -0.8, -0.5, -0.5 }, { -1, 0, 0 },
        { -0.8, 0.4, 0.4 }, { 0, 0.7, 0.7 }, { 0.7, 0.5, 0.5 }, { 0.7, 0, -0.8 }, { -0.1, 0, -1 }, { -0.8, 0, -0.8 },
        { -0.8, 0, 0.7 }, { 0, 0, 1 }, { 0.7, 0, 0.7 }, { 0.7, 0.4, -0.5 }, { -0.1, 0.7, -0.8 }, { -0.8, 0.4, -0.5 },
        { -1, -0.1, 0 }, { -0.8, -0.5, 0.4 }, { 0, -0.8, 0.7 }, { 0.7, -0.6, 0.5 }, { 0, -1, 0 },
    }) do OFFSETS_NEAR[#OFFSETS_NEAR + 1] = Vector3.new(row[1], row[2], row[3]) end
    for _, height in ipairs({ 3, 5, 7, 10, 15 }) do
        for _, row in ipairs({ { 0, 0 }, { 1, 0 }, { -1, 0 }, { 0, 1 }, { 0, -1 }, { 0.7, 0.7 }, { -0.7, 0.7 }, { 0.7, -0.7 }, { -0.7, -0.7 } }) do
            OFFSETS_HIGH[#OFFSETS_HIGH + 1] = Vector3.new(row[1], height, row[2])
        end
    end

    function WB.refresh(force)
        local now = clock()
        if not force and now - WB.lastTick <= 0.15 then return end
        if force and now - WB.lastTick <= 0.05 then return end
        WB.lastTick = now
        WB.cache = {}
        local list = { Game.camera() }
        for _, player in ipairs(Players:GetPlayers()) do
            if player.Character then list[#list + 1] = player.Character end
        end
        local cars = Workspace:FindFirstChild("CarContainer")
        if cars and flag("gun_vehicle_wallbang", false) then list[#list + 1] = cars end
        pcall(function() WB.params.FilterDescendantsInstances = list end)
        if WB.overlap then pcall(function() WB.overlap.FilterDescendantsInstances = list end) end
    end

    local function ray(from, to)
        if not WB.params then return nil end
        return Workspace:Raycast(from, to - from, WB.params)
    end

    local function freeSpace(position)
        if not WB.overlap then return true end
        local ok, parts = pcall(function() return Workspace:GetPartBoundsInRadius(position, 0, WB.overlap) end)
        if not ok or type(parts) ~= "table" then return true end
        for _, part in ipairs(parts) do
            if part.CanCollide and (part:GetClosestPointOnSurface(position) - position).Magnitude <= 0.0001 then return false end
        end
        return true
    end

    local function radius() return math.clamp(flag("wb_radius", 6), 1, 10) end

    local function lookFlat(shooter, target)
        local delta = (target - shooter) * FLAT
        if delta.Magnitude > 0.001 then return delta.Unit end
        return Vector3.new(0, 0, -1)
    end

    local function pointsAround(center, look, scales)
        local list = {}
        for _, normal in ipairs(NORMALS) do
            if (normal * FLAT):Dot(-look) > -0.5 then
                for _, scale in ipairs(scales) do
                    local position = center + normal * scale
                    if freeSpace(position) then list[#list + 1] = position end
                end
            end
        end
        return list
    end

    local function originsAround(center, look, scales, sets)
        local list = {}
        for _, scale in ipairs(scales) do
            for _, set in ipairs(sets) do
                for _, offset in ipairs(set) do
                    if (offset * FLAT):Dot(look) > -0.5 then list[#list + 1] = center + offset * scale end
                end
            end
        end
        return list
    end

    local function byDistance(list, from)
        local ranked = {}
        for index, position in ipairs(list) do ranked[index] = { position, (position - from).Magnitude, index } end
        table.sort(ranked, function(a, b)
            if a[2] ~= b[2] then return a[2] < b[2] end
            return a[3] < b[3]
        end)
        for index, entry in ipairs(ranked) do list[index] = entry[1] end
        return list
    end

    local function append(into, list)
        for _, item in ipairs(list) do into[#into + 1] = item end
        return into
    end

    function WB.accept(origin, target)
        local limit = WB.filter
        if not limit then return true end
        if (origin - limit.shooter).Magnitude > limit.spot then return false end
        if (target - limit.center).Magnitude > limit.spot then return false end
        if limit.range and (target - origin).Magnitude > limit.range then return false end
        return true
    end

    local function firstClear(targets, origins)
        for _, target in ipairs(targets) do
            for _, origin in ipairs(origins) do
                if WB.accept(origin, target) and not ray(target, origin) and freeSpace(origin) then return origin, target end
            end
        end
        return nil
    end

    local SCANS = {}
    SCANS["Vape V4"] = function(shooter, target, surface, center, hitbox)
        local reach = radius() - math.min(WB.moved, 1)
        local look = lookFlat(shooter, target)
        local targets = {}
        if freeSpace(target) then
            if surface and (shooter - surface).Magnitude < 7.5 and WB.accept(surface, target) then return surface, target end
            targets[1] = target
        end
        if hitbox then append(targets, pointsAround(center, look, { 7.4 })) end
        local origins = { shooter }
        for _, position in ipairs(originsAround(shooter, look, { reach }, { OFFSETS_NEAR })) do
            if freeSpace(position) then origins[#origins + 1] = position end
        end
        return firstClear(targets, origins)
    end
    SCANS["Aster Origin"] = function(shooter, target, surface, center, hitbox)
        local reach = radius() - math.min(WB.moved, 1)
        local look = lookFlat(shooter, target)
        local origins = originsAround(shooter, look, { reach }, { OFFSETS_NEAR, OFFSETS_HIGH })
        origins[#origins + 1] = shooter
        byDistance(origins, shooter)
        if surface and (surface - shooter).Magnitude <= reach + 1.5 then table.insert(origins, 1, surface) end
        local targets = { target }
        if hitbox then append(targets, pointsAround(center, look, { radius() })) end
        return firstClear(targets, origins)
    end
    SCANS["Aster Reach"] = function(shooter, target, surface, center, hitbox)
        local reach = radius()
        local look = lookFlat(shooter, target)
        local origins = originsAround(shooter, look, { reach, reach * 2 }, { OFFSETS_NEAR, OFFSETS_HIGH })
        if surface then table.insert(origins, 1, surface) end
        local targets = { target }
        if hitbox then append(targets, pointsAround(center, look, { reach, reach * 2 })) end
        return firstClear(targets, origins)
    end
    SCANS["Aster Precise"] = function(shooter, target, surface, center, hitbox)
        local reach = radius()
        local look = lookFlat(shooter, target)
        local targets = { target }
        if hitbox then append(targets, pointsAround(center, look, { reach })) end
        local near, far = {}, {}
        local function add(position)
            if #near + #far >= 100 then return end
            local distance = (position - shooter).Magnitude
            if distance <= reach then near[#near + 1] = position elseif distance <= reach * 2 then far[#far + 1] = position end
        end
        add(shooter)
        if surface then add(surface) end
        local back = shooter - target
        local side = back.Magnitude > 0.001 and back.Unit:Cross(UP) or Vector3.new(1, 0, 0)
        side = side.Magnitude > 0.01 and side.Unit or Vector3.new(1, 0, 0)
        local from = target
        for _ = 1, 6 do
            local hit = Workspace:Raycast(from, shooter - from, WB.params)
            if not hit then break end
            local front = hit.Position + hit.Normal * 0.05
            add(front)
            for _, shift in ipairs({ -3, -1.5, 1.5, 3 }) do add(front + side * shift) end
            from = hit.Position + (shooter - from).Unit * 0.05
        end
        local line = shooter - target
        if line.Magnitude > 0.001 then
            local unit = (target - shooter).Unit
            for step = 1, math.floor(math.min(reach * 2, line.Magnitude)) do add(shooter + unit * step) end
        end
        for _, position in ipairs(originsAround(shooter, look, { reach * 0.5, reach }, { OFFSETS_NEAR })) do add(position) end
        byDistance(near, shooter)
        byDistance(far, shooter)
        return firstClear(targets, append(near, far))
    end

    local ALT_PARTS = { "Head", "Torso", "HumanoidRootPart", "Left Arm", "Right Arm", "Left Leg", "Right Leg" }
    function WB.altParts(model, except)
        local list = {}
        for _, name in ipairs(ALT_PARTS) do
            local part = model:FindFirstChild(name)
            if part and part ~= except and part:IsA("BasePart") then list[#list + 1] = part end
        end
        return list
    end

    function WB.plan(origin, part, override)
        local position = part.Position
        local cached = not override and WB.cache[part] or nil
        if cached == false then return nil end
        if cached then return "moved", cached[1], cached[2] end
        local blocked = ray(position, origin)
        if not blocked and not ray(origin, position) then return "clear" end
        local shooter = override or Combat.sp.shooter()
        if not shooter then return nil end
        local anchor = part.Parent and part.Parent:FindFirstChild("HumanoidRootPart")
        local center = anchor and anchor.Position or position
        local method = flag("wb_method", "Aster Reach")
        local scan = SCANS[method] or SCANS["Aster Reach"]
        WB.filter = flag("wb_damage", true) and { shooter = shooter, center = center, spot = flag("wb_spot", 7.5), range = Gun.range() } or nil
        local newOrigin, newTarget = scan(shooter, position, blocked and (blocked.Position + blocked.Normal * 0.01) or nil, center, flag("wb_hitbox", true))
        if not newOrigin and (method == "Aster Reach" or method == "Aster Precise") then
            local delta = position - shooter
            if delta.Magnitude > 0.5 then
                local unit = delta.Unit
                for step = 2, math.min(delta.Magnitude, 160), 2 do
                    local ground = Workspace:Raycast(shooter + unit * step, Vector3.new(0, -50, 0), WB.params)
                    local at = ground and ground.Position + ground.Normal * 0.5
                    if at and WB.accept(at, position) and not ray(at, position) and freeSpace(at) then
                        newOrigin, newTarget = at, position
                        break
                    end
                end
            end
            if not newOrigin then
                for step = 3, 18, 3 do
                    local at = shooter + Vector3.new(0, step, 0)
                    if WB.accept(at, position) and not ray(at, position) and freeSpace(at) then
                        newOrigin, newTarget = at, position
                        break
                    end
                end
            end
        end
        WB.filter = nil
        if newOrigin then
            if not override then WB.cache[part] = { newOrigin, newTarget } end
            return "moved", newOrigin, newTarget
        end
        if not override then WB.cache[part] = false end
        return nil
    end

    function WB.status(origin, part, shooter)
        if not part or not part.Parent then return "blocked" end
        local plan = WB.plan(origin, part, shooter)
        if plan == "clear" then return "visible" end
        if plan == "moved" then return "wallbang" end
        return "blocked"
    end

    function WB.step(_, now)
        if not (flag("silent_wallbang", false) or flag("rb_enabled", false) or flag("wb_assist", false) or flag("wb_ind", false) or flag("tinfo_on", false)) then return end
        WB.refresh()
        local realPos = Combat.sp.realPos()
        if not realPos then return end
        local history = WB.history
        history[#history + 1] = { realPos, now }
        while #history > 1 and now - history[1][2] > 0.1 do table.remove(history, 1) end
        WB.moved = (history[#history][1] - history[1][1]).Magnitude
    end

    local SP = { requests = {}, order = { "rage", "voidhide", "assist", "orbit", "desync" }, pos = nil, active = nil, running = false, conns = {}, lastWarn = 0 }
    Combat.sp = SP
    local spApplied, spRealCF, spRealVel, spSpeed, spStyle = nil, nil, nil, 100, nil
    local SP_RESTORE, SP_GHOST = Util.randomName(), Util.randomName()
    local floorParams = Game.newParams()

    function SP.realPos()
        local root = Game.rootPart()
        if not root then return nil end
        if spApplied and spRealCF then return spRealCF.Position end
        return root.Position
    end

    function SP.shooter()
        if SP.active == "orbit" then return SP.realPos() end
        return SP.pos or SP.realPos()
    end

    function SP.floorAt(position, lowest)
        if not floorParams then return nil end
        local list = { Game.camera() }
        for _, player in ipairs(Players:GetPlayers()) do
            if player.Character then list[#list + 1] = player.Character end
        end
        pcall(function() floorParams.FilterDescendantsInstances = list end)
        local hit = Workspace:Raycast(position, Vector3.new(0, -600, 0), floorParams)
        if not hit then return nil end
        local floorY = hit.Position.Y
        if lowest then
            for _ = 1, 6 do
                local below = Workspace:Raycast(Vector3.new(position.X, floorY - 0.25, position.Z), Vector3.new(0, -600, 0), floorParams)
                if not below then break end
                floorY = below.Position.Y
            end
        end
        return floorY
    end

    function SP.voidY(fromY)
        local destroyAt = Workspace.FallenPartsDestroyHeight
        if type(destroyAt) ~= "number" or destroyAt ~= destroyAt or destroyAt < -1e5 or destroyAt > 1e4 then destroyAt = -500 end
        return math.min(math.max(destroyAt + 30, -2500), fromY - 10), destroyAt
    end

    local function follow(current, goal, speed, dt)
        local delta = goal - current
        local distance = delta.Magnitude
        local step = speed * dt
        if speed >= 4000 or distance <= step then return goal end
        return current + delta * (step / distance)
    end

    local ghost = { model = nil, highlight = nil, parts = {}, char = nil, count = 0, checked = 0, line = nil }

    local function destroyGhost()
        if ghost.model then pcall(function() ghost.model:Destroy() end) end
        ghost.model, ghost.highlight, ghost.char, ghost.parts = nil, nil, nil, {}
        if ghost.line then ghost.line.Visible = false end
    end

    local function buildGhost(character)
        destroyGhost()
        local model = Instance.new("Model")
        model.Name = Util.randomName()
        local descendants = character:GetDescendants()
        for _, part in ipairs(descendants) do
            if part:IsA("BasePart") and part.Name ~= "HumanoidRootPart" and part.Transparency < 0.95 then
                local ok, copy = pcall(function() return part:Clone() end)
                if ok and copy then
                    for _, child in ipairs(copy:GetChildren()) do
                        if not child:IsA("SpecialMesh") then child:Destroy() end
                    end
                    copy.Anchored, copy.CanCollide, copy.CanTouch, copy.CanQuery, copy.CastShadow = true, false, false, false, false
                    copy.Transparency = 0
                    copy.Material = Enum.Material.SmoothPlastic
                    copy.Parent = model
                    ghost.parts[#ghost.parts + 1] = { part, copy }
                end
            end
        end
        local highlight = Instance.new("Highlight")
        highlight.Adornee = model
        pcall(function() highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop end)
        highlight.Parent = model
        ghost.model, ghost.highlight, ghost.char = model, highlight, character
        ghost.count, ghost.checked = #descendants, clock()
    end

    local function updateGhost()
        local style = spStyle
        local character, _, root = Combat.localParts()
        local cam = Game.camera()
        if not SP.pos or not style or not root or not cam then
            if ghost.model then ghost.model.Parent = nil end
            if ghost.line then ghost.line.Visible = false end
            return
        end
        local now = clock()
        if ghost.char ~= character or not ghost.model then
            buildGhost(character)
        elseif now - ghost.checked > 0.5 then
            ghost.checked = now
            if #character:GetDescendants() ~= ghost.count then buildGhost(character) end
        end
        if ghost.model.Parent ~= cam then ghost.model.Parent = cam end
        local shift = SP.pos - root.Position
        for _, pair in ipairs(ghost.parts) do
            if pair[1].Parent then
                pair[2].CFrame = pair[1].CFrame + shift
                pair[2].Color = style.fill
            end
        end
        local highlight = ghost.highlight
        highlight.FillColor, highlight.FillTransparency = style.fill, style.fillT
        highlight.OutlineColor, highlight.OutlineTransparency = style.line, style.lineT
        if style.tracer then
            ghost.line = ghost.line or Draw.new("Line", { Thickness = 1, ZIndex = 4 })
            local a, aIn = Draw.project(cam, root.Position)
            local b, bIn = Draw.project(cam, SP.pos)
            ghost.line.From, ghost.line.To = a, b
            ghost.line.Color, ghost.line.Transparency = style.tracer, 1 - style.tracerT
            ghost.line.Visible = aIn and bIn
        elseif ghost.line then
            ghost.line.Visible = false
        end
    end

    local function onHeartbeat(dt)
        local root = Game.rootPart()
        if not root or (Util.player and Util.player.invisActive and Util.player.invisActive()) then
            SP.pos, spApplied, spRealCF = nil, nil, nil
            return
        end
        local real = root.CFrame
        local realPos = real.Position
        local goal, speed, style
        SP.active = nil
        for _, name in ipairs(SP.order) do
            local fn = SP.requests[name]
            if fn then
                local ok, g, s, v = pcall(fn, root, realPos)
                if ok and g then
                    goal, speed, style = g, s or 100, v
                    SP.active = name
                    break
                end
            end
        end
        if goal then
            spSpeed, spStyle = speed, style
            SP.pos = follow(SP.pos or realPos, goal, speed, dt)
        elseif SP.pos then
            SP.pos = follow(SP.pos, realPos, spSpeed, dt)
            if (SP.pos - realPos).Magnitude < 0.05 then SP.pos = nil end
        end
        if SP.pos then
            spRealCF, spRealVel = real, root.AssemblyLinearVelocity
            spApplied = CFrame.new(SP.pos) * (real - realPos)
            root.CFrame = spApplied
        else
            spApplied, spRealCF = nil, nil
            if next(SP.requests) == nil then SP.stop() end
        end
    end
    SP.heartbeat = onHeartbeat

    local function onRestore()
        if not spApplied then return end
        local root = Game.rootPart()
        if root and spRealCF then
            local drift = root.Position - spApplied.Position
            if drift.Magnitude < 0.5 then
                root.CFrame = spRealCF
            else
                root.CFrame = spRealCF + (drift.Magnitude < 40 and drift or ZERO)
            end
            if spRealVel and (spApplied.Position - spRealCF.Position).Magnitude > 20 then root.AssemblyLinearVelocity = spRealVel end
        end
        spApplied = nil
    end
    SP.restore = onRestore

    local function spWarn(label, problem)
        if clock() - SP.lastWarn > 5 then
            SP.lastWarn = clock()
            Util.note("sp" .. tostring(problem), label, problem)
        end
    end

    function SP.start()
        if SP.running then return end
        SP.running = true
        SP.conns[#SP.conns + 1] = Util.track(RunService.Heartbeat:Connect(function(dt)
            local ok, problem = pcall(onHeartbeat, dt)
            if not ok then spWarn("server position:", problem) end
        end))
        pcall(function() RunService:BindToRenderStep(SP_RESTORE, Enum.RenderPriority.First.Value, function() pcall(onRestore) end) end)
        pcall(function() SP.conns[#SP.conns + 1] = Util.track(RunService.Stepped:Connect(function() pcall(onRestore) end)) end)
        pcall(function()
            RunService:BindToRenderStep(SP_GHOST, Enum.RenderPriority.Last.Value, function()
                local ok, problem = pcall(updateGhost)
                if not ok then spWarn("server position ghost:", problem) end
            end)
        end)
    end

    function SP.stop()
        if not SP.running then return end
        SP.running = false
        for _, connection in ipairs(SP.conns) do pcall(function() connection:Disconnect() end) end
        SP.conns = {}
        pcall(function() RunService:UnbindFromRenderStep(SP_RESTORE) end)
        pcall(function() RunService:UnbindFromRenderStep(SP_GHOST) end)
        destroyGhost()
    end

    function SP.enable(name, fn)
        SP.requests[name] = fn
        SP.start()
    end

    function SP.disable(name)
        SP.requests[name] = nil
    end

    function SP.set(name, on, fn)
        if on and SP.requests[name] ~= fn then SP.enable(name, fn) elseif not on and SP.requests[name] then SP.disable(name) end
    end

    Util.onUnload(function()
        SP.requests = {}
        local root = Game.rootPart()
        if spApplied and spRealCF and root then pcall(function() root.CFrame = spRealCF end) end
        spApplied, spRealCF, SP.pos = nil, nil, nil
        SP.stop()
        if ghost.line then Draw.remove(ghost.line) ghost.line = nil end
    end)

    local function desyncRequest(_, realPos)
        local goal
        if flag("misc_desync_style", "Offset") == "Void" then
            goal = Vector3.new(realPos.X, (SP.voidY(realPos.Y)), realPos.Z)
        else
            goal = realPos + Vector3.new(0, flag("misc_desync_y", -2.5), 0)
            if flag("misc_desync_under", false) then
                local floorY = SP.floorAt(realPos, flag("misc_desync_filter", false))
                if floorY then goal = Vector3.new(goal.X, math.min(goal.Y, floorY - 3), goal.Z) end
            end
        end
        local style
        if flag("misc_desync_visual", false) then
            style = Combat.style("misc_desync_fill", "misc_desync_line", flag("misc_desync_tracer", false) and "misc_desync_tracer_color" or nil)
        end
        return goal, flag("misc_desync_speed", 30), style
    end
    SP.desyncRequest = desyncRequest

    local Aim = { locked = nil, last = nil, acquiredAt = 0, accX = 0, accY = 0, pauseUntil = 0, humanFor = nil, bend = 0, over = 0, startLen = 1, missRoll = 0, missOff = ZERO, warned = false }
    Combat.aim = Aim

    local function aimReset()
        Aim.locked, Aim.last, Aim.accX, Aim.accY = nil, nil, 0, 0
    end

    function Aim.wanted()
        local on = flag("aim_on", false) and Util.keyActive("aim_key")
        local magnet = flag("trigger_on", false) and flag("trigger_magnet", false) and Util.keyActive("trigger_key")
        return on, magnet
    end

    function Aim.step(dt)
        local on, magnet = Aim.wanted()
        local cam = Game.camera()
        local _, _, root, eye = Combat.localParts()
        if not (on or magnet) or not cam or not root or Util.typing() then return aimReset() end
        local ref = Combat.aimRef()
        if flag("aim_only_shoot", false) then
            local tool = Combat.gun()
            local shooting = UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1) or (tool ~= nil and tool:GetAttribute("Local_IsShooting") == true)
            if not shooting then return end
        end
        local human = flag("aim_human", false)
        local now = clock()
        if human and flag("aim_method", "Camera") == "Camera" then
            local limit = flag("aim_flick", 80)
            local okDelta, delta = pcall(function() return UserInputService:GetMouseDelta() end)
            if limit > 0 and okDelta and delta and delta.Magnitude > limit then Aim.pauseUntil = now + 0.18 end
            if now < Aim.pauseUntil then return end
        end
        local opts = { current = Aim.last }
        if not on then
            local magnetFov = flag("trigger_magnet_fov", 0)
            if magnetFov > 0 then opts.fov = magnetFov end
        end
        local lockedRecord = Aim.locked and Entities.byPlayer[Aim.locked]
        if flag("aim_lock", false) and lockedRecord and Entities.live(lockedRecord) then
            opts.only, opts.ignoreFov = Aim.locked, true
        end
        local from = eye and eye.Position or root.Position
        local record, part, _, picked = Combat.select("aim", ref, from, opts)
        if not record then return aimReset() end
        if Aim.last ~= record.player then
            Aim.last, Aim.acquiredAt = record.player, now
        end
        if flag("aim_lock", false) then Aim.locked = record.player end
        local held = now - Aim.acquiredAt
        if held < flag("aim_reaction", 0) / 1000 then return end
        local alpha = 1
        if flag("aim_smooth", true) then
            local first, last, inc = flag("aim_smooth_start", 85), flag("aim_smooth_end", 20), flag("aim_smooth_inc", 50)
            local smoothing = first > last and math.max(last, first - inc * held) or math.min(last, first + inc * held)
            smoothing = math.clamp(smoothing + random(-1, 1) * flag("aim_smooth_rand", 5), 0, 99)
            alpha = 1 - (smoothing / 100) ^ (math.min(dt, 0.1) * 60)
        end
        if not on then alpha = alpha * flag("trigger_magnet_str", 100) / 100 end
        local goal = picked or part.Position
        if flag("aim_pred", false) then
            local ok, predicted = pcall(Predict.point, record, part, from, "aim")
            if ok and typeof(predicted) == "Vector3" then goal = goal + (predicted - part.Position) end
        end
        local missChance = flag("aim_miss", 0)
        if missChance > 0 then
            if now >= Aim.missRoll then
                Aim.missRoll = now + 0.7
                local offset = Vector3.new(random(-1, 1), random(-1, 1), random(-1, 1))
                Aim.missOff = (random(0, 100) < missChance and offset.Magnitude > 0.01) and offset.Unit * flag("aim_miss_size", 2.5) or ZERO
            end
            goal = goal + Aim.missOff
        end
        local method = flag("aim_method", "Camera")
        if method == "Mouse" and type(Compat.mousemoverel) ~= "function" then
            if not Aim.warned then
                Aim.warned = true
                Util.notify({ Title = "Aim assist", Text = "mousemoverel is not available, using the camera instead" })
            end
            method = "Camera"
        end
        local goalScreen = Draw.project(cam, goal)
        if human then
            local delta = goalScreen - ref
            local len = delta.Magnitude
            if len > 1 then
                if Aim.acquiredAt ~= Aim.humanFor then
                    Aim.humanFor = Aim.acquiredAt
                    Aim.bend = random(0.5, 1) * (random() < 0.5 and -1 or 1)
                    Aim.over, Aim.startLen = random(), len
                end
                local dir = delta / len
                local perp = Vector2.new(-dir.Y, dir.X)
                local fade = math.clamp(len / math.max(Aim.startLen, 1), 0, 1)
                local shifted = delta + perp * (len * Aim.bend * flag("aim_curve", 20) / 100 * fade)
                shifted = shifted + dir * (Aim.startLen * Aim.over * flag("aim_over", 15) / 100 * math.max(0, 1 - held / 0.3))
                shifted = shifted + Vector2.new(random(-1, 1), random(-1, 1)) * flag("aim_jitter", 1.5)
                alpha = alpha * (0.55 + 0.45 * math.clamp(len / math.max(flag("aim_fov", 120), 1), 0, 1))
                goalScreen = ref + shifted
                if method ~= "Mouse" then
                    local unit = cam:ViewportPointToRay(goalScreen.X, goalScreen.Y)
                    goal = unit.Origin + unit.Direction * (goal - cam.CFrame.Position).Magnitude
                end
            end
        end
        if method == "Mouse" then
            Aim.accX = Aim.accX + (goalScreen.X - ref.X) * alpha
            Aim.accY = Aim.accY + (goalScreen.Y - ref.Y) * alpha
            local ix = Aim.accX >= 0 and math.floor(Aim.accX) or math.ceil(Aim.accX)
            local iy = Aim.accY >= 0 and math.floor(Aim.accY) or math.ceil(Aim.accY)
            Aim.accX, Aim.accY = Aim.accX - ix, Aim.accY - iy
            if ix ~= 0 or iy ~= 0 then pcall(Compat.mousemoverel, ix, iy) end
        else
            cam.CFrame = cam.CFrame:Lerp(CFrame.lookAt(cam.CFrame.Position, goal), alpha)
        end
    end

    local Circles = { objects = {}, radius = {} }
    Combat.circles = Circles
    local CIRCLE_ON = { aim = "aim_on", silent = "silent_on" }

    function Circles.step()
        local cam = Game.camera()
        local ref = cam and Combat.aimRef()
        for prefix, toggle in pairs(CIRCLE_ON) do
            local circle = Circles.objects[prefix]
            if flag(toggle, false) and flag(prefix .. "_fov_show", false) and ref then
                if not circle then
                    circle = Draw.new("Circle", { NumSides = 64, ZIndex = 6, Visible = false })
                    Circles.objects[prefix] = circle
                end
                local want = flag(prefix .. "_fov", 120)
                if flag(prefix .. "_dynamic", false) and Combat.dyn[prefix] then want = Combat.dyn[prefix] end
                local current = Circles.radius[prefix] or want
                current = current + (want - current) * 0.2
                Circles.radius[prefix] = current
                circle.Position, circle.Radius = ref, current
                circle.Color, circle.Transparency = flag(prefix .. "_fov_color", WHITE), Util.opacity(prefix .. "_fov_color")
                circle.Thickness, circle.Filled = flag(prefix .. "_fov_thick", 1), flag(prefix .. "_fov_filled", false)
                circle.Visible = true
            elseif circle then
                circle.Visible = false
            end
        end
    end

    local Trigger = { seenSince = nil, nextShot = 0, burstUntil = 0, burstShots = 0 }
    Combat.trigger = Trigger
    local triggerParams = Game.newParams(nil, true)
    pcall(function() triggerParams.CollisionGroup = "ClientBullet" end)
    local TORSO = { Torso = true, UpperTorso = true, LowerTorso = true, HumanoidRootPart = true }

    function Trigger.target(cam, from)
        local ref = Combat.aimRef()
        local unit = cam:ViewportPointToRay(ref.X, ref.Y)
        local list = {}
        for _, other in ipairs(Players:GetPlayers()) do
            if other ~= LocalPlayer and other.Character then list[#list + 1] = other.Character end
        end
        if #list == 0 or not triggerParams then return nil end
        pcall(function() triggerParams.FilterDescendantsInstances = list end)
        local result = Workspace:Raycast(unit.Origin, unit.Direction * 1500, triggerParams)
        local player = result and Game.playerFromPart(result.Instance)
        local record = player and Entities.byPlayer[player]
        if not record or not Entities.live(record) then return nil end
        if Game.relations[player.UserId] == "Friendly" then return nil end
        if flag("trigger_team", true) and not record.enemy then return nil end
        if flag("trigger_ff", false) and record.state.forcefield then return nil end
        if flag("trigger_hostile", false) and Combat.peaceful(player) then return nil end
        local mode = flag("trigger_part", "Head")
        if mode == "Head" and result.Instance.Name ~= "Head" then return nil end
        if mode == "Torso" and not TORSO[result.Instance.Name] then return nil end
        if (result.Position - from).Magnitude > (Gun.range() or 1000) then return nil end
        if not Combat.visibleFrom(from, record.model, result.Instance.Position) then return nil end
        return record, result
    end

    function Trigger.step(_, now)
        local cam = Game.camera()
        local _, _, root, eye = Combat.localParts()
        if not flag("trigger_on", false) or not cam or not root or not eye or Util.typing() or not Util.keyActive("trigger_key") or not Combat.readyGun() then
            Trigger.seenSince = nil
            return
        end
        if not Trigger.target(cam, eye.Position) then
            Trigger.seenSince = nil
            return
        end
        Trigger.seenSince = Trigger.seenSince or now
        if now - Trigger.seenSince >= flag("trigger_reaction", 0) / 1000 and now >= Trigger.nextShot and now >= Trigger.burstUntil then
            Trigger.nextShot = now + flag("trigger_delay", 40) / 1000
            Gun.fire()
            Trigger.fired = (Trigger.fired or 0) + 1
            local burst = flag("trigger_burst", 0)
            if burst > 0 then
                Trigger.burstShots = Trigger.burstShots + 1
                if Trigger.burstShots >= burst then
                    Trigger.burstShots = 0
                    Trigger.burstUntil = now + flag("trigger_burst_pause", 250) / 1000
                end
            end
        end
    end

    local Silent = { autoNext = 0, switchNext = 0, lastOrigin = nil, lastNew = nil, warnedStack = false, redirected = 0 }
    Combat.silent = Silent

    function Silent.active()
        return flag("silent_on", false) and Util.keyActive("silent_key")
    end

    function Silent.wanted()
        return flag("silent_on", false) or flag("rb_enabled", false) or flag("wb_assist", false) or Combat.wants.auto == true
    end

    local function original(...)
        return Gun.original(...)
    end

    local function redirect(...)
        local origin = ...
        local force = Gun.force
        if force then
            Gun.force = nil
            if clock() < force.expires and force.part.Parent then
                local part = force.part
                if typeof(origin) == "Vector3" and flag("rb_wallbang", true) then
                    WB.refresh(true)
                    local status, moved, moveHit = WB.plan(origin, part)
                    if not status and part.Parent then
                        for _, alt in ipairs(WB.altParts(part.Parent
, part)) do
                            status, moved, moveHit = WB.plan(origin, alt)
                            if status then part = alt break end
                        end
                    end
                    if status == "moved" then
                        Silent.lastOrigin, Silent.lastNew = origin, moved
                        return part, moveHit or part.Position
                    end
                end
                return part, force.pos
            end
        end
        if typeof(origin) ~= "Vector3" then return original(...) end
        local silentOn = flag("silent_on", false) and Silent.active()
        local assist = Combat.assist
        local assisted = not silentOn and assist ~= nil and assist.part ~= nil and assist.part.Parent ~= nil and clock() < (assist.partUntil or 0)
        if not silentOn and not assisted then return original(...) end
        if silentOn and random(0, 100) > flag("silent_hitchance", 100) then return original(...) end
        local info = Gun.info()
        local taser = info.Behavior == "Taser"
        local wallbang = flag("silent_wallbang", false)
        local record, part, picked
        if assisted then
            record, part, wallbang = { model = assist.part.Parent }, assist.part, true
        else
            record, part, _, picked = Combat.select("silent", Combat.aimRef(), origin, { limit = Gun.range(info) or 1000, ignoreDown = taser, skipWall = wallbang })
        end
        if not record then return original(...) end
        local args = table.pack(...)
        local usePart, newOrigin, hit = part, nil, nil
        if wallbang then
            WB.refresh(true)
            local status, moved, moveHit = WB.plan(origin, part)
            if not status then
                for _, alt in ipairs(WB.altParts(record.model, part)) do
                    status, moved, moveHit = WB.plan(origin, alt)
                    if status then usePart = alt break end
                end
            end
            if status == "moved" then
                newOrigin, hit = moved, moveHit
            elseif not status and flag("silent_wall", false) then
                return original(...)
            end
        end
        local aimPos = usePart.Position
        if picked and usePart == part then aimPos = picked end
        if silentOn and not assisted and flag("silent_pred", false) and record.root then
            local ok, predicted, note = pcall(Predict.point, record, usePart, newOrigin or origin, "silent")
            if ok and typeof(predicted) == "Vector3" then
                aimPos = aimPos + (predicted - usePart.Position)
                Predict.note = note
            end
        end
        Silent.redirected = Silent.redirected + 1
        Silent.lastTarget = record.player
        if newOrigin then
            Silent.lastOrigin, Silent.lastNew = origin, newOrigin
            return usePart, hit and (hit + (aimPos - usePart.Position)) or aimPos
        end
        args[2] = aimPos
        return original(table.unpack(args, 1, args.n))
    end

    local function rewriteStack(hookFn)
        local fromPos, toPos = Silent.lastOrigin, Silent.lastNew
        if not (fromPos and toPos) then return end
        local getstack, setstack, info = Compat.getstack, Compat.setstack, Compat.info
        if type(getstack) ~= "function" or type(setstack) ~= "function" or type(info) ~= "function" then return end
        local replaced = 0
        local function sweep(strict)
            pcall(function()
                local scanner = info(1, "f")
                for level = 2, 14 do
                    local fn = info(level, "f")
                    local match
                    if strict then match = Gun.shoot ~= nil and fn == Gun.shoot else match = level >= 3 and type(fn) == "function" and fn ~= hookFn and fn ~= scanner end
                    if match then
                        for index, value in pairs(getstack(level)) do
                            if value == fromPos then
                                setstack(level, index, toPos)
                                replaced = replaced + 1
                            end
                        end
                    end
                end
            end)
        end
        sweep(true)
        if replaced == 0 then sweep(false) end
        if replaced == 0 and not Silent.warnedStack then
            Silent.warnedStack = true
            Util.note("wb stack", "wallbang: the shot origin could not be rewritten (needs debug.getstack and debug.setstack)")
        end
    end

    local hookFn
    hookFn = function(...)
        Silent.lastOrigin, Silent.lastNew = nil, nil
        local packed = table.pack(pcall(redirect, ...))
        local results
        if packed[1] then
            results = table.pack(table.unpack(packed, 2, packed.n))
        else
            Util.note("silent" .. tostring(packed[2]), "silent aim:", packed[2])
            results = table.pack(original(...))
        end
        rewriteStack(hookFn)
        if typeof(results[2]) == "Vector3" then pcall(Game.reportCast, results[1], results[2]) end
        return table.unpack(results, 1, results.n)
    end
    Silent.hookFn = hookFn

    function Gun.unhook()
        if Gun.hooked and Gun.original then
            local target, old = Gun.hooked, Gun.original
            pcall(function()
                if Compat.restorefunction then Compat.restorefunction(target) else Compat.hookfunction(target, old) end
            end)
        end
        Gun.hooked, Gun.original = nil, nil
    end

    function Gun.install()
        if not Gun.find() then return false end
        if Gun.hooked == Gun.cast then return true end
        Gun.unhook()
        if type(Compat.hookfunction) ~= "function" then return false end
        local ok, old = pcall(Compat.hookfunction, Gun.cast, hookFn)
        if not ok or type(old) ~= "function" then return false end
        Gun.hooked, Gun.original = Gun.cast, old
        return true
    end

    function Gun.step(_, now)
        if not Silent.wanted() then
            if Gun.hooked then Gun.unhook() end
            Gun.tries, Gun.failed = 0, false
            return
        end
        if Gun.failed or now < Gun.nextTry then return end
        if Gun.install() then
            Gun.tries = 0
            Gun.nextTry = now + 2
            return
        end
        Gun.tries = Gun.tries + 1
        Gun.nextTry = now + 1
        if Gun.tries > 20 then
            Gun.failed = true
            Util.notify({ Title = "Silent aim", Text = "The gun could not be hooked (needs getconnections or filtergc, debug.getupvalue and hookfunction)" })
        end
    end

    function Combat.fireAt(part, position)
        if not part or not part.Parent then return false end
        if not Gun.hooked and not Gun.install() then return false end
        Gun.force = { part = part, pos = position or part.Position, expires = clock() + 0.6 }
        Gun.fire()
        return true
    end

    function Silent.autoSwitch(now, from)
        if now < Silent.switchNext then return end
        local chosen = flag("silent_switch_weapons", {})
        local available = {}
        for _, label in ipairs(Combat.WEAPONS) do
            if has(chosen, label) then
                local tool = Combat.findWeapon(label)
                if tool then available[#available + 1] = tool end
            end
        end
        if #available == 0 then return false end
        if not Combat.select("silent", Combat.aimRef(), from, { limit = 1000, skipWall = flag("silent_wallbang", false) }) then return false end
        local delay = math.max(flag("silent_switch_delay", 0.3), 0.03)
        Silent.switchNext = (now - Silent.switchNext < delay) and Silent.switchNext + delay or now + delay
        local _, humanoid = Combat.localParts()
        if not humanoid then return false end
        local current = Game.weapon()
        local index = 0
        for position, tool in ipairs(available) do
            if tool == current then index = position break end
        end
        for step = 1, #available do
            local candidate = available[(index + step - 1) % #available + 1]
            local ammo = candidate:GetAttribute("Local_CurrentAmmo")
            if candidate ~= current and (ammo == nil or ammo > 0) then
                humanoid:EquipTool(candidate)
                Silent.switches = (Silent.switches or 0) + 1
                return true
            end
        end
        return false
    end

    function Silent.step(_, now)
        if not (flag("silent_autofire", false) and Silent.active()) or Util.typing() then return end
        local _, _, root, eye = Combat.localParts()
        if not root or not eye or not Game.camera() then return end
        if flag("silent_switch", false) then
            local ok, switched = pcall(Silent.autoSwitch, now, eye.Position)
            if not ok then Util.note("silent switch" .. tostring(switched), "silent switch:", switched) end
            if ok and switched then
                Silent.autoNext = math.min(Silent.autoNext, now)
                return
            end
        end
        if now < Silent.autoNext then return end
        Silent.autoNext = now + 1 / math.max(flag("silent_autofire_rate", 15), 1)
        if not Combat.readyGun() then return end
        local info = Gun.info()
        local record, part = Combat.select("silent", Combat.aimRef(), eye.Position, { limit = Gun.range(info) or 1000, ignoreDown = info.Behavior == "Taser", skipWall = flag("silent_wallbang", false) })
        if record and part and flag("silent_wallbang", false) and flag("silent_autofire_check", true) then
            WB.refresh()
            if WB.status(eye.Position, part) == "blocked" then record = nil end
        end
        if record then
            Silent.lastAuto = clock()
            Gun.fire()
        end
    end

    Util.onUnload(function()
        Gun.unhook()
        Gun.force = nil
    end)

    local R = {
        target = nil, record = nil, center = nil, vel = ZERO, live = true, phase = "peek", lastPhase = "", phaseEnd = 0, peekAt = 0,
        nextShot = 0, voidPos = nil, voidRoll = 0, skip = {}, safe = false, status = "off", lastHealth = 0, lastDamage = 0,
        equipAt = 0, reloadAt = 0, getAt = 0, getUntil = 0, viewing = false, shownText = "", randAngle = 0, goal = nil, goalAt = 0, goalFor = nil,
        smart = { state = "waiting", t = nil, timer = 0, health = nil, dropped = false }, peekMem = {}, peekCount = 0, deathZones = {},
        stat = { shots = 0, hits = 0, misses = 0, missRun = 0, hitRun = 0, why = "", pending = {} },
        tune = { out = 0, delay = 0, boost = 0, force = false, steps = 0 }, hist = {}, nextHouse = 0, killParts = {}, killAt = -1e9,
    }
    Combat.rage = R
    local HEAD_OFFSET = Vector3.new(0, 1.5, 0)
    local atan2 = math.atan2 or math.atan
    local RAGE_WEAPONS = { "AK-47", "M4A1", "MP5", "FAL", "Remington 870", "M700", "M9", "Revolver" }
    local AUTOGET = { "AK-47", "Remington 870", "MP5", "M700", "M4A1", "FAL" }
    Combat.RAGE_WEAPONS, Combat.AUTOGET = RAGE_WEAPONS, AUTOGET

    local function inBounds(position)
        return math.abs(position.X) < 8000 and math.abs(position.Z) < 8000 and position.Y > -400 and position.Y < 4000
    end

    local function centerOf(record, now)
        local position = record.root.Position
        if inBounds(position) then
            R.hist[record.player] = { pos = position, t = now }
            return position, record.root.AssemblyLinearVelocity, true
        end
        if flag("rb_res", false) then
            local last = R.hist[record.player]
            if last and now - last.t <= 2 then return last.pos, ZERO, false end
        end
        return nil
    end

    function R.usable(record, now)
        local player = record.player
        if Game.relations[player.UserId] == "Friendly" then return false end
        if has(flag("rb_white", {}), player.Name) then return false end
        local until_ = R.skip[player]
        if until_ and until_ > now then return false end
        if flag("rb_team", true) and not record.enemy then return false end
        if flag("rb_ff", false) and record.state.forcefield then return false end
        if flag("rb_hostile", false) and Combat.peaceful(player) then return false end
        if flag("rb_down", false) and Combat.down(record) then return false end
        return true
    end

    function R.pick(realPos, now)
        local mode = flag("rb_tmode", "Target list")
        local list = flag("rb_targets", {})
        local range = flag("rb_range", 2000)
        local selected = mode == "Players tab" and Combat.selectedPlayer and Combat.selectedPlayer() or nil
        local cam = Game.camera()
        local mouse = UserInputService:GetMouseLocation()
        local best
        for _, record in ipairs(Entities.update()) do
            if record.root and R.usable(record, now) then
                local position, velocity, live = centerOf(record, now)
                if position then
                    local distance = (position - realPos).Magnitude
                    local want = true
                    if mode == "Target list" then want = has(list, record.player.Name) elseif mode == "Players tab" then want = selected == record.player end
                    if want and distance <= range then
                        local score = distance
                        if mode == "Closest to cursor" and cam then
                            local screen, onScreen = Draw.project(cam, position)
                            score = onScreen and (screen - mouse).Magnitude or (1e6 + distance)
                        end
                        if Game.relations[record.player.UserId] == "Priority" then score = score - 1e7 end
                        if R.target == record.player then score = score - 12 end
                        if not best or score < best.score then best = { score = score, record = record, pos = position, vel = velocity, live = live } end
                    end
                end
            end
        end
        if not best then return nil end
        return best.record, best.pos, best.vel, best.live
    end

    function R.scanKill(now)
        if R.killBusy or now - R.killAt < 60 then return end
        R.killBusy, R.killAt = true, now
        task.spawn(function()
            local words = {}
            for word in string.gmatch(string.lower(tostring(flag("rb_void_safe_names", "kill,lava,death,deadly,acid,hurt,damage,toxic,spike,laser"))), "[^,%s]+") do words[#words + 1] = word end
            local found = {}
            local function named(text)
                text = string.lower(text)
                for _, word in ipairs(words) do
                    if string.find(text, word, 1, true) then return true end
                end
                return false
            end
            pcall(function()
                if #words == 0 then return end
                for count, part in ipairs(Workspace:GetDescendants()) do
                    if part:IsA("BasePart") and part.Size.Magnitude < 5000 and (named(part.Name) or (part.Parent and part.Parent ~= Workspace and named(part.Parent.Name))) then
                        local model = part:FindFirstAncestorOfClass("Model")
                        if not (model and model:FindFirstChildOfClass("Humanoid")) then
                            found[#found + 1] = part
                            if #found >= 500 then break end
                        end
                    end
                    if count % 4000 == 0 then task.wait() end
                end
            end)
            R.killParts, R.killBusy = found, false
        end)
    end

    local function voidClear(point)
        for _, zone in ipairs(R.deathZones) do
            if (zone[1] - point).Magnitude < zone[2] then return false end
        end
        local margin = flag("rb_void_safe_margin", 12)
        for _, part in ipairs(R.killParts) do
            if part.Parent then
                local rel = part.CFrame:PointToObjectSpace(point)
                local half = part.Size / 2
                if math.abs(rel.X) <= half.X + margin and math.abs(rel.Y) <= half.Y + margin and math.abs(rel.Z) <= half.Z + margin then return false end
            end
        end
        return true
    end

    local function pickSafe(generate)
        if not flag("rb_void_safe", true) then return generate() end
        R.scanKill(clock())
        local last
        for _ = 1, 14 do
            last = generate()
            if voidClear(last) then return last end
        end
        return last
    end

    function R.mapBounds()
        local now = clock()
        if R.bounds and now - (R.boundsAt or 0) < 90 then return R.bounds end
        if R.boundsBusy then return R.bounds end
        R.boundsBusy = true
        task.spawn(function()
            local xs, zs = {}, {}
            local ok = pcall(function()
                for count, part in ipairs(Workspace:GetDescendants()) do
                    if part:IsA("BasePart") and part.Anchored and part.Size.Magnitude < 1500 then
                        local position = part.Position
                        if math.abs(position.X) < 20000 and math.abs(position.Z) < 20000 then
                            xs[#xs + 1], zs[#zs + 1] = position.X, position.Z
                        end
                    end
                    if count % 4000 == 0 then task.wait() end
                end
            end)
            if ok and #xs > 20 then
                table.sort(xs)
                table.sort(zs)
                local low, high = math.max(1, math.floor(#xs * 0.01)), math.min(#xs, math.ceil(#xs * 0.99))
                R.bounds = { minX = xs[low], maxX = xs[high], minZ = zs[low], maxZ = zs[high] }
            end
            R.boundsAt, R.boundsBusy = clock(), false
        end)
        return R.bounds
    end

    local function edgePoint()
        local base = R.realPos or ZERO
        local bounds = R.mapBounds() or { minX = base.X - 500, maxX = base.X + 500, minZ = base.Z - 500, maxZ = base.Z + 500 }
        local margin = flag("rb_edge_margin", 25)
        local x0, x1, z0, z1 = bounds.minX - margin, bounds.maxX + margin, bounds.minZ - margin, bounds.maxZ + margin
        local w, h = math.max(x1 - x0, 10), math.max(z1 - z0, 10)
        local perimeter = 2 * (w + h)
        local jump = flag("rb_edge_jump", 0)
        if jump > 0 and R.edgeD then R.edgeD = (R.edgeD + jump) % perimeter else R.edgeD = math.random() * perimeter end
        local d = R.edgeD
        local px, pz
        if d < w then px, pz = x0 + d, z0
        elseif d < w + h then px, pz = x1, z0 + (d - w)
        elseif d < 2 * w + h then px, pz = x1 - (d - w - h), z1
        else px, pz = x0, z1 - (d - 2 * w - h) end
        local _, destroyAt = SP.voidY(base.Y)
        return Vector3.new(px, math.max(base.Y + flag("rb_edge_y", 0), destroyAt + 30), pz)
    end

    function R.voidPoint(now)
        local pattern = flag("rb_pattern", "Under map")
        if R.voidPattern ~= pattern then R.voidPattern, R.voidPos = pattern, nil end
        if R.voidPos and now - R.voidRoll < flag("rb_switch", 0.05) then return R.voidPos end
        R.voidRoll = now
        local depth = flag("rb_depth", 1)
        if pattern == "Map edge" then
            R.voidPos = pickSafe(edgePoint)
            return R.voidPos
        end
        if pattern == "Under map" then
            local base = R.realPos or ZERO
            local floorY = SP.voidY(base.Y)
            local span = math.min(math.max(base.Y - 10 - floorY, 0), 250)
            R.voidPos = pickSafe(function()
                local angle = math.random() * math.pi * 2
                local reach = flag("rb_under_radius", 250) * math.sqrt(math.random())
                return Vector3.new(base.X + math.cos(angle) * reach, floorY + math.random() * span, base.Z + math.sin(angle) * reach)
            end)
            return R.voidPos
        end
        local function choice(list) return list[math.random(1, #list)] end
        local main, a, b
        if pattern == "Far" then
            main = choice({ 2e6, 5e6, 1e7, 2e7, 5e7 }) * depth
            a = (choice({ 1e5, 2.5e5, 5e5, 1e6, 2e6 }) + math.random(1e4, 2e4)) * depth
            b = (choice({ 1e5, 2.5e5, 5e5, 1e6, 2e6 }) + math.random(1e4, 2e4)) * depth
        elseif pattern == "Extreme" then
            main, a, b = choice({ 1e8, 2.5e8, 5e8 }) * depth, choice({ 1e7, 2.5e7, 5e7 }) * depth, choice({ 1e7, 2.5e7, 5e7 }) * depth
        else
            main, a, b = math.random(150000, 250000) * depth, math.random(1000, 5000) * depth, math.random(1000, 5000) * depth
        end
        main, a, b = math.clamp(main, -5e8, 5e8), math.clamp(a, -5e8, 5e8), math.clamp(b, -5e8, 5e8)
        local dirs = {}
        for _, name in ipairs({ "+Y", "+X", "+Z" }) do
            if has(flag("rb_dir", { "+Y" }), name) then dirs[#dirs + 1] = name end
        end
        local direction = #dirs > 0 and dirs[math.random(1, #dirs)] or "+Y"
        if direction == "+X" then R.voidPos = Vector3.new(main, a, b)
        elseif direction == "+Z" then R.voidPos = Vector3.new(a, b, main)
        else R.voidPos = Vector3.new(a, main, b) end
        return R.voidPos
    end

    function R.voidCenter()
        local base = SP.realPos()
        if not base then return nil end
        if flag("rb_pattern", "Under map") == "Under map" then return Vector3.new(base.X, (SP.voidY(base.Y)), base.Z) end
        if not R.voidPos then R.voidPoint(clock()) end
        return R.voidPos
    end

    function R.localDied()
        if R.voidPos and clock() - (R.voidUsedAt or -100) < 1.5 and #R.deathZones < 30 then
            R.deathZones[#R.deathZones + 1] = { R.voidPos, flag("rb_void_safe_margin", 12) + 25 }
            Util.notify({ Title = "Void", Text = "You died in the void; that spot is avoided from now on" })
        end
    end
    Util.track(Game.events.onLocalDied:Connect(R.localDied))

    local function wantVoid(now)
        if not flag("rb_void", false) then return false end
        local when = flag("rb_void_when", "While targeting")
        R.voidWhy = when == "While reloading" and "reloading" or when == "Smart" and "smart timer" or "hiding between peeks"
        if when == "While reloading" then return false end
        if when ~= "Smart" then return true end
        local S = R.smart
        local health = R.record and R.record.health or 100
        local dt = S.t and (now - S.t) or 0
        S.t = now
        if S.health and health < S.health then S.dropped = true end
        S.health = health
        S.timer = S.timer + dt
        if S.state == "waiting" then
            if S.timer >= flag("rb_smart_wait", 8) then
                S.timer = 0
                if not S.dropped and health > 0 then S.state = "voiding" end
                S.dropped = false
            end
            return false
        end
        if S.timer >= flag("rb_smart_void", 5) then S.state, S.timer = "waiting", 0 end
        return true
    end

    local function choosePart(record)
        local mode = flag("rb_part", "Head")
        if mode == "Random" then mode = math.random(1, 2) == 1 and "Head" or "Torso" end
        if mode == "Torso" then return record.torso or record.root end
        return record.head or record.root
    end

    local function bucket(value) return math.floor((value % (math.pi * 2)) / (math.pi / 8)) end

    function R.peek(record, base, now)
        local mode = R.randomSpot and "Random" or flag("rb_peek_mode", "Behind")
        local distance, height = flag("rb_peek_dist", 6), flag("rb_peek_height", 2)
        local visibleOnly = flag("rb_los", "Off") == "Visible only"
        local function ring(angle, extra)
            return base + Vector3.new(math.cos(angle) * distance, height + (extra or 0), math.sin(angle) * distance)
        end
        local angle = 0
        if mode == "Above" then
            local goal = base + Vector3.new(0, math.max(height, 2), 0)
            if not visibleOnly or WB.status(goal + HEAD_OFFSET, record.head, goal) == "visible" then return goal end
        elseif mode == "Random" then
            angle = R.randAngle
        elseif mode == "Spiral" then
            angle = now * flag("rb_spiral_speed", 6)
        else
            local cf = record.root.CFrame
            local look = cf.LookVector
            local right = cf.RightVector or Vector3.new(-look.Z, 0, look.X)
            if mode == "Front" then angle = atan2(look.Z, look.X)
            elseif mode == "Left" then angle = atan2(-right.Z, -right.X)
            elseif mode == "Right" then angle = atan2(right.Z, right.X)
            elseif mode == "Side swap" then
                local sign = R.peekCount % 2 == 0 and 1 or -1
                angle = atan2(right.Z * sign, right.X * sign)
            elseif mode == "Swing" then angle = atan2(-look.Z, -look.X) + math.sin(now * flag("rb_spiral_speed", 6) * 0.5) * 1.2
            else angle = atan2(-look.Z, -look.X) end
        end
        R.usedAngle = nil
        if mode ~= "Above" then
            local mem = R.peekMem[record.player]
            if mem and flag("rb_peek_memory", true) then
                local function banned(value)
                    local entry = mem.bad[bucket(value)]
                    return entry ~= nil and entry[1] >= 2 and now - entry[2] < 12
                end
                if mem.good and now - mem.good[2] < 20 and (mode == "Random" or mode == "Spiral") and not banned(mem.good[1]) and math.random() < 0.5 then
                    angle = mem.good[1]
                else
                    for step = 0, 15 do
                        if not banned(angle + step * math.pi / 8) then angle = angle + step * math.pi / 8 break end
                    end
                end
            end
            R.usedAngle = angle
        end
        local goal = ring(angle)
        if not visibleOnly then return goal end
        WB.refresh()
        if WB.status(goal + HEAD_OFFSET, record.head, goal) == "visible" then return goal end
        for _, extra in ipairs({ 0, 4, 8 }) do
            for step = 1, 8 do
                local candidate = ring(angle + step * math.pi / 4, extra)
                if WB.status(candidate + HEAD_OFFSET, record.head, candidate) == "visible" then return candidate end
            end
        end
        return nil
    end

    local function tuneStep(up)
        local t = R.tune
        if up then
            t.out, t.delay, t.boost = math.min(t.out + 0.05, 0.4), math.min(t.delay + 0.01, 0.1), math.min(t.boost + 0.15, 0.6)
            t.force, t.steps = true, t.steps + 1
        else
            t.out, t.delay, t.boost = math.max(t.out - 0.05, 0), math.max(t.delay - 0.01, 0), math.max(t.boost - 0.15, 0)
            t.steps = math.max(t.steps - 1, 0)
            if t.steps == 0 then t.force = false end
        end
        Predict.boost = t.boost
    end

    function R.fire(part, aim)
        if not R.run or not Combat.readyGun() then return end
        if not Combat.fireAt(part, aim) then return end
        local record = R.record
        if record then
            local st = R.stat
            st.shots = st.shots + 1
            st.pending[#st.pending + 1] = { t = clock(), hp = record.health, player = record.player, angle = R.usedAngle, note = R.predNote }
            if #st.pending > 40 then table.remove(st.pending, 1) end
        end
    end

    local function memoryFor(player)
        local mem = R.peekMem[player]
        if not mem then
            mem = { bad = {} }
            R.peekMem[player] = mem
        end
        return mem
    end

    function R.evaluate(record, now)
        local st = R.stat
        local list = st.pending
        if #list == 0 then return end
        local humanoid = record and record.humanoid
        for index, shot in ipairs(list) do
            if shot and humanoid and shot.player == record.player and humanoid.Health < shot.hp - 0.01 and now - shot.t >= 0.03 then
                st.hits, st.hitRun, st.missRun = st.hits + 1, st.hitRun + 1, 0
                if shot.angle then
                    local mem = memoryFor(shot.player)
                    mem.good = { shot.angle, now }
                    mem.bad[bucket(shot.angle)] = nil
                end
                for _, other in ipairs(list) do
                    if other and other.player == shot.player then other.hp = humanoid.Health end
                end
                list[index] = false
                if st.hitRun >= 8 and flag("rb_autotune", false) then
                    st.hitRun = 0
                    tuneStep(false)
                end
                break
            end
        end
        local keep = {}
        for _, shot in ipairs(list) do
            if shot then
                if now - shot.t > 0.9 then
                    st.misses, st.missRun, st.hitRun = st.misses + 1, st.missRun + 1, 0
                    local note = shot.note or ""
                    local why = "no hit registered"
                    if string.find(note, "no line", 1, true) then why = "no line to predicted spot"
                    elseif string.find(note, "out of range", 1, true) then why = "out of range"
                    elseif shot.player.Character and shot.player.Character:FindFirstChildOfClass("ForceField") then why = "target forcefield" end
                    st.why = why
                    if shot.angle then
                        local mem = memoryFor(shot.player)
                        local key = bucket(shot.angle)
                        local entry = mem.bad[key]
                        mem.bad[key] = { (entry and entry[1] or 0) + 1, now }
                    end
                    if flag("rb_autotune", false) and st.missRun >= 5 then
                        st.missRun = 0
                        tuneStep(true)
                    end
                else
                    keep[#keep + 1] = shot
                end
            end
        end
        st.pending = keep
    end

    function R.request(_, realPos)
        if not R.run then return nil end
        local now = clock()
        R.realPos = realPos
        local _, humanoid = Combat.localParts()
        local tool, empty = Combat.gunState()
        if empty and R.altReady then empty = false end
        local voidOn = flag("rb_void", false)
        local when = flag("rb_void_when", "While targeting")
        local record = R.record
        local settings = flag("rb_settings", {})
        local style = has(settings, "Show server position") and Combat.style("misc_desync_fill", "misc_desync_line") or nil
        R.randomSpot = has(settings, "Random peek spot")
        local function inVoid(why)
            R.voidUsedAt = now
            R.status = "in void (" .. why .. ")"
            return R.voidPoint(now), 1e9, style
        end
        if Options.rb_void_key and Util.keyActive("rb_void_key") and not Util.typing() then return inVoid("void key") end
        if now < R.getUntil or (Combat.gettingWeapon and Combat.gettingWeapon()) then
            R.status = "getting weapon"
            return nil
        end
        if flag("rb_safe", false) and humanoid and humanoid.MaxHealth > 0 then
            local limit = flag("rb_safe_hp", 20) / 100
            local fraction = humanoid.Health / humanoid.MaxHealth
            if fraction <= limit then R.safe = true elseif fraction >= math.min(limit + 0.25, 1) then R.safe = false end
        else
            R.safe = false
        end
        if R.safe then
            R.status = "safe mode"
            if voidOn then return inVoid("safe mode, low health") end
            return nil
        end
        if not record or not R.center then
            local listed = flag("rb_targets", {})
            local listMode = flag("rb_tmode", "Target list") == "Target list"
            R.status = (listMode and next(listed) == nil) and "no targets selected" or "waiting for target"
            R.lastPhase = ""
            if voidOn and flag("rb_wait_void", false) and (not listMode or next(listed) ~= nil) then return inVoid("waiting for target") end
            if voidOn and when == "Always" then
                if now >= R.phaseEnd then
                    R.phase = R.phase == "void" and "peek" or "void"
                    R.phaseEnd = now + (R.phase == "void" and flag("rb_in_time", 0.35) or flag("rb_out_time", 0.2))
                end
                if R.phase == "void" then return inVoid("always mode, no target") end
            end
            return nil
        end
        if not tool then
            R.status = "no gun"
            return nil
        end
        if record.state.forcefield then
            R.status = "target has forcefield"
            R.lastPhase = ""
            if voidOn then return inVoid("waiting for " .. Combat.displayName(record.player) .. "'s forcefield to disappear") end
            return nil
        end
        if empty then
            R.status = flag("rb_reload", false) and "reloading" or "gun empty"
            R.lastPhase = ""
            if voidOn then return inVoid(flag("rb_reload", false) and "reloading" or "gun empty, no reload") end
            return nil
        end
        if wantVoid(now) then
            if now >= R.phaseEnd then
                if R.phase == "void" then
                    R.phase = "peek"
                    R.phaseEnd = now + flag("rb_out_time", 0.2) + R.tune.out
                    R.randAngle = math.random() * math.pi * 2
                else
                    R.phase = "void"
                    R.phaseEnd = now + flag("rb_in_time", 0.35)
                end
            end
        else
            R.phase, R.phaseEnd = "peek", 0
        end
        if R.phase == "void" then
            R.lastPhase = "void"
            return inVoid(R.voidWhy or "hiding between peeks")
        end
        if R.lastPhase ~= "peek" then
            R.lastPhase = "peek"
            R.peekCount = R.peekCount + 1
            R.peekAt = now
        end
        local lead, velocity = 0, R.vel
        local predOn = flag("rb_pred", false) or R.tune.force
        R.predNote = nil
        if predOn then
            lead = Predict.lead("rb")
            velocity = Predict.velocity(record.player, record.root)
        end
        local base = R.center + velocity * lead
        local goal
        if R.goal and R.goalFor == record.player and now - R.goalAt < 0.05 then
            goal = R.goal
        else
            goal = R.peek(record, base, now)
            R.goal, R.goalAt, R.goalFor = goal, now, record.player
        end
        if not goal then
            R.status = "no clear spot"
            if voidOn then return inVoid("no clear spot near target") end
            return nil
        end
        R.status = "killing " .. record.player.Name
        if now - R.peekAt >= flag("rb_shot_delay", 0.03) + R.tune.delay and now >= R.nextShot then
            R.nextShot = now + 1 / math.max(flag("rb_rate", 12), 1)
            if R.randomSpot then R.randAngle = math.random() * math.pi * 2 end
            local part = choosePart(record)
            local aim = part.Position
            if not R.live then aim = R.center + (part.Position - record.root.Position) end
            if predOn then
                local ok, predicted, note = pcall(Predict.point, record, part, goal, "rb")
                if ok and typeof(predicted) == "Vector3" then
                    aim = aim + (predicted - part.Position)
                    R.predNote = note
                end
            end
            task.defer(R.fire, part, aim)
        end
        return goal, 1e9, style
    end

    local function readyTool(tool)
        local ammo = tool:GetAttribute("Local_CurrentAmmo")
        return (ammo == nil or ammo > 0) and (tool:GetAttribute("Local_ReloadSession") or 0) <= 0
    end

    function R.weapons(record, humanoid, realPos, now)
        local chosen = flag("rb_weapons", {})
        local pool, poolName = {}, {}
        for _, name in ipairs(RAGE_WEAPONS) do
            if has(chosen, name) then
                local owned = Combat.findWeapon(name)
                if owned then
                    pool[#pool + 1] = owned
                    poolName[owned] = name
                end
            end
        end
        R.altReady = false
        if not record or not humanoid or #pool == 0 then return end
        local held = Game.weapon()
        if flag("rb_aw", false) and R.center then
            local distance = (R.center - realPos).Magnitude
            local want = distance <= flag("rb_aw_close", 45) and "close" or distance >= flag("rb_aw_far", 250) and "far" or "mid"
            local fitting = {}
            for _, tool in ipairs(pool) do
                local name = poolName[tool]
                local class = name == "Remington 870" and "close" or name == "M700" and "far" or "mid"
                if class == want and readyTool(tool) then fitting[#fitting + 1] = tool end
            end
            if #fitting > 0 then pool = fitting end
        end
        local heldIndex = 0
        for index, tool in ipairs(pool) do
            if tool == held then heldIndex = index end
        end
        for _, tool in ipairs(pool) do
            if tool ~= held and readyTool(tool) then R.altReady = true break end
        end
        local heldReady = heldIndex > 0 and readyTool(held)
        if heldReady and not (#pool > 1 and now >= R.equipAt) then return end
        local pick
        for step = 1, #pool do
            local tool = pool[(heldIndex + step - 1) % #pool + 1]
            if tool ~= held and readyTool(tool) then pick = tool break end
        end
        if heldIndex == 0 and not pick then pick = pool[1] end
        if pick then
            R.equipAt = now + math.max(flag("rb_switch_delay", 0.15), 0.05)
            pcall(function() humanoid:EquipTool(pick) end)
        end
    end

    function R.housekeeping(now)
        local _, humanoid, root = Combat.localParts()
        if not root then
            R.target, R.record, R.center = nil, nil, nil
            return
        end
        local realPos = SP.realPos()
        local record, position, velocity, live = R.pick(realPos, now)
        if record then
            if R.target ~= record.player then
                R.target, R.lastHealth, R.lastDamage, R.goal = record.player, record.health, now, nil
                R.smart = { state = "waiting", t = nil, timer = 0, health = nil, dropped = false }
            end
            if record.health < R.lastHealth then R.lastDamage = now end
            R.lastHealth = record.health
            if flag("rb_swap", false) and now - R.lastDamage > flag("rb_swap_time", 4) then
                R.skip[record.player] = now + flag("rb_swap_time", 4) * 2
                R.lastDamage = now
            end
        else
            R.target = nil
        end
        R.record, R.center, R.vel, R.live = record, position, velocity or ZERO, live ~= false
        Util.guard("rage shots", R.evaluate, record, now)
        R.weapons(record, humanoid, realPos, now)
        local cam = Game.camera()
        if record and has(flag("rb_settings", {}), "View target") and cam then
            if cam.CameraSubject ~= record.humanoid then cam.CameraSubject = record.humanoid end
            R.viewing = true
        elseif R.viewing then
            R.viewing = false
            if cam and humanoid then cam.CameraSubject = humanoid end
        end
        local wanted = flag("rb_autoget", {})
        if now >= R.getAt and humanoid and humanoid.Health > 0 and Combat.getWeapon and not (Combat.gettingWeapon and Combat.gettingWeapon()) then
            for _, name in ipairs(AUTOGET) do
                if has(wanted, name) and not Combat.findWeapon(name) then
                    R.getAt, R.getUntil = now + 3, now + 0.6
                    Combat.getWeapon(name)
                    break
                end
            end
        end
        local text = record and string.sub("Result: " .. Combat.displayName(record.player), 1, 28) or "Result: none"
        if text ~= R.shownText and R.resultLabel then
            R.shownText = text
            R.resultLabel:SetText(text)
        end
        local tool, empty, reloading = Combat.gunState()
        if tool and empty and not reloading and flag("rb_reload", false) and now >= R.reloadAt then
            R.reloadAt = now + 0.6
            Combat.reload()
        end
    end

    function Combat.reload()
        if not Gun.shoot then Gun.find() end
        local reload = Gun.shoot and upvalue(Gun.shoot, 2)
        if type(reload) == "function" then
            task.spawn(reload)
            return true
        end
        if Util.typing() then return false end
        return pcall(function()
            local vim = game:GetService("VirtualInputManager")
            vim:SendKeyEvent(true, Enum.KeyCode.R, false, game)
            task.delay(0.05, function() vim:SendKeyEvent(false, Enum.KeyCode.R, false, game) end)
        end)
    end

    local VoidHide = { low = false, status = "off" }
    Combat.voidHide = VoidHide

    function VoidHide.request(_, realPos)
        R.realPos = realPos
        local when = flag("vh_when", "Always")
        local _, humanoid = Combat.localParts()
        local why
        if when == "Always" then
            why = "always on"
        elseif when == "Keybind" then
            if Util.keyActive("vh_key") then why = "void key" end
        elseif when == "Low health" then
            if humanoid and humanoid.MaxHealth > 0 then
                local limit = flag("vh_hp", 35) / 100
                local fraction = humanoid.Health / humanoid.MaxHealth
                if fraction <= limit then VoidHide.low = true elseif fraction >= math.min(limit + 0.25, 1) then VoidHide.low = false end
                if VoidHide.low then why = string.format("low health, %d%%", math.floor(fraction * 100)) end
            end
        else
            local _, empty = Combat.gunState()
            if empty then why = "reloading" end
        end
        if not why then
            VoidHide.status = "visible (waiting for " .. string.lower(when) .. ")"
            return nil
        end
        VoidHide.status = "in void (" .. why .. ")"
        R.voidUsedAt = clock()
        return R.voidPoint(clock()), 1e9, nil
    end

    local rageText, voidMarker, voidLine, voidText

    local function hideMarker()
        if voidMarker then voidMarker.Parent = nil end
        if voidLine then voidLine.Visible = false end
        if voidText then voidText.Visible = false end
    end

    local function updateMarker()
        local cam = Game.camera()
        local root = Game.rootPart()
        if not (flag("rb_void_show", false) and flag("rb_void", false) and R.run) or not cam or not root then return hideMarker() end
        local at = R.voidCenter()
        if not at then return hideMarker() end
        local color = flag("rb_void_color", Color3.fromRGB(255, 80, 80))
        if not voidMarker then
            voidMarker = Instance.new("Part")
            voidMarker.Name = Util.randomName()
            pcall(function() voidMarker.Shape = Enum.PartType.Ball end)
            voidMarker.Size = Vector3.new(5, 5, 5)
            voidMarker.Anchored, voidMarker.CanCollide, voidMarker.CanQuery, voidMarker.CanTouch, voidMarker.CastShadow = true, false, false, false, false
            voidMarker.Material = Enum.Material.Neon
            voidMarker.Transparency = 0.25
        end
        voidMarker.Color, voidMarker.Position = color, at
        if voidMarker.Parent ~= cam then voidMarker.Parent = cam end
        voidLine = voidLine or Draw.new("Line", { Thickness = 1, ZIndex = 5 })
        voidText = voidText or Draw.text(14, 6)
        local view = cam.ViewportSize
        local screen, inFront = Draw.project(cam, at)
        local x, y = screen.X, screen.Y
        if not inFront then x, y = view.X - x, view.Y - y end
        x, y = math.clamp(x, 40, view.X - 40), math.clamp(y, 40, view.Y - 40)
        voidLine.From, voidLine.To, voidLine.Color, voidLine.Visible = Vector2.new(view.X / 2, view.Y), Vector2.new(x, y), color, true
        voidText.Text = string.format("void %d studs", math.floor((at - root.Position).Magnitude))
        voidText.Color, voidText.Position, voidText.Visible = color, Vector2.new(x, y - 20), true
    end

    function R.statusLine()
        if R.run then
            local line = "ragebot: " .. R.status
            if R.predNote and (flag("rb_pred", false) or R.tune.force) then line = line .. " | pred " .. R.predNote end
            if flag("rb_feedback", true) then
                local st = R.stat
                local total = st.hits + st.misses
                if total > 0 then
                    line = line .. string.format(" | hits %d/%d (%d%%)", st.hits, total, math.floor(st.hits / total * 100 + 0.5))
                    if st.why ~= "" and st.misses > 0 then line = line .. " | last miss: " .. st.why end
                end
                if R.tune.steps > 0 then line = line .. string.format(" | tuned +%.2fs", R.tune.out) end
            end
            local record = R.record
            if record then line = line .. string.format(" | %s %d hp", Combat.displayName(record.player), math.floor(record.health)) end
            return line
        end
        if flag("vh_enabled", false) then return "void hide: " .. tostring(VoidHide.status) end
        return nil
    end

    function R.step(_, now)
        local on = Util.bindOn("rb_enabled", "rb_key")
        if on ~= (R.run == true) then
            R.run = on
            if on then
                R.phase, R.lastPhase, R.phaseEnd, R.voidPos = "peek", "", 0, nil
                R.stat = { shots = 0, hits = 0, misses = 0, missRun = 0, hitRun = 0, why = "", pending = {} }
                R.tune = { out = 0, delay = 0, boost = 0, force = false, steps = 0 }
                Predict.boost = 0
            else
                R.target, R.record, R.center, R.goal, R.safe, R.status = nil, nil, nil, nil, false, "off"
                if R.viewing then
                    R.viewing = false
                    local cam, humanoid = Game.camera(), Game.humanoid(Game.localCharacter())
                    if cam and humanoid then cam.CameraSubject = humanoid end
                end
            end
        end
        SP.set("rage", on, R.request)
        SP.set("voidhide", flag("vh_enabled", false), VoidHide.request)
        SP.set("desync", Util.bindOn("misc_desync", "misc_desync_key"), SP.desyncRequest)
        if on and now >= R.nextHouse then
            R.nextHouse = now + 0.08
            Util.guard("ragebot", R.housekeeping, now)
        end
        Util.guard("void marker", updateMarker)
        local line = flag("rb_status", false) and R.statusLine()
        local cam = Game.camera()
        if line and cam then
            rageText = rageText or Draw.text(16, 7)
            rageText.Text, rageText.Color = line, WHITE
            rageText.Position = Vector2.new(cam.ViewportSize.X / 2, cam.ViewportSize.Y / 2 + flag("rb_status_y", 40))
            rageText.Visible = true
        elseif rageText then
            rageText.Visible = false
        end
    end

    Util.onUnload(function()
        R.run = false
        if voidMarker then pcall(function() voidMarker:Destroy() end) voidMarker = nil end
        if R.viewing then
            local cam, humanoid = Game.camera(), Game.humanoid(Game.localCharacter())
            if cam and humanoid then pcall(function() cam.CameraSubject = humanoid end) end
        end
    end)

    local Mods = { originals = setmetatable({}, { __mode = "k" }), applied = setmetatable({}, { __mode = "k" }), on = false }
    Combat.mods = Mods
    local MOD_KEYS = { "SpreadRadius", "FireRate", "AutoFire", "Range", "AccurateRange" }

    function Mods.tools()
        local list = {}
        for _, holder in ipairs({ Game.localCharacter(), LocalPlayer:FindFirstChildOfClass("Backpack") }) do
            if holder then
                for _, child in ipairs(holder:GetChildren()) do
                    if child:IsA("Tool") then list[#list + 1] = child end
                end
            end
        end
        return list
    end

    local function modSignature()
        return table.concat({ tostring(flag("gun_no_spread", false)), tostring(flag("gun_spread_pct", 100)), tostring(flag("gun_full_auto", false)),
            tostring(flag("gun_fire_rate", 100)), tostring(flag("gun_range_on", false)), tostring(flag("gun_range", 1000)) }, "|")
    end

    function Mods.apply(tool, restore)
        local saved = Mods.originals[tool]
        if tool:GetAttribute("FireRate") == nil and not saved then return false end
        if tool.Name == "Taser" or tool:GetAttribute("Behavior") == "Taser" then return false end
        if not saved then
            saved = {}
            for _, key in ipairs(MOD_KEYS) do saved[key] = tool:GetAttribute(key) end
            Mods.originals[tool] = saved
        end
        local function put(key, value)
            if tool:GetAttribute(key) ~= value then tool:SetAttribute(key, value) end
        end
        local spread = restore and 100 or flag("gun_spread_pct", 100)
        if saved.SpreadRadius ~= nil then put("SpreadRadius", (not restore and flag("gun_no_spread", false)) and 0 or saved.SpreadRadius * spread / 100) end
        if saved.FireRate ~= nil then put("FireRate", saved.FireRate * (restore and 100 or flag("gun_fire_rate", 100)) / 100) end
        local auto = not restore and flag("gun_full_auto", false)
        if saved.AutoFire ~= nil or auto then put("AutoFire", auto and true or saved.AutoFire) end
        local ranged = not restore and flag("gun_range_on", false)
        local range = flag("gun_range", 1000)
        if saved.Range ~= nil then put("Range", ranged and range or saved.Range) elseif ranged then put("Range", range) end
        if saved.AccurateRange ~= nil then put("AccurateRange", ranged and math.max(saved.AccurateRange, range) or saved.AccurateRange) end
        return true
    end

    local function reequip(tool)
        local character, humanoid = Combat.localParts()
        if not (character and humanoid) or tool.Parent ~= character then return end
        humanoid:UnequipTools()
        task.delay(0.2, function()
            local _, again = Combat.localParts()
            if again and tool.Parent == LocalPlayer:FindFirstChildOfClass("Backpack") then again:EquipTool(tool) end
        end)
    end

    function Mods.sweep(restore)
        local signature = restore and "restore" or modSignature()
        local character = Game.localCharacter()
        for _, tool in ipairs(Mods.tools()) do
            if Mods.applied[tool] ~= signature then
                if Mods.apply(tool, restore) then
                    Mods.applied[tool] = signature
                    if tool.Parent == character then reequip(tool) end
                end
            end
        end
    end

    function Mods.restoreAll()
        for tool in pairs(Mods.originals) do
            Mods.applied[tool] = nil
            if tool.Parent then pcall(Mods.apply, tool, true) end
        end
    end

    function Mods.step()
        local on = flag("gun_mods", false)
        if on then
            Mods.on = true
            Mods.sweep(false)
        elseif Mods.on then
            Mods.on = false
            Mods.restoreAll()
        end
    end
    Util.onUnload(Mods.restoreAll)

    local Utility = { nextTry = 0, cars = {}, carsAt = 0 }
    Combat.utility = Utility
    local SWAP_PRIORITY = { M4A1 = 1, ["AK-47"] = 1, MP5 = 1, FAL = 1, ["Remington 870"] = 2, M9 = 3, Revolver = 4 }

    function Utility.swapTarget(current)
        local pack = LocalPlayer:FindFirstChildOfClass("Backpack")
        if not pack then return nil end
        local best
        for _, tool in ipairs(pack:GetChildren()) do
            if tool ~= current and tool:IsA("Tool") and tool:GetAttribute("FireRate") ~= nil and (tool:GetAttribute("Local_ReloadSession") or 0) <= 0
                and tool.Name ~= "Taser" and tool.Name ~= "M700" then
                if not best or (SWAP_PRIORITY[tool.Name] or 100) < (SWAP_PRIORITY[best.Name] or 100) then best = tool end
            end
        end
        return best
    end

    function Utility.releaseCars()
        for part, query in pairs(Utility.cars) do
            if part.Parent then pcall(function() part.CanQuery = query end) end
        end
        Utility.cars = {}
    end

    function Utility.step(_, now)
        if flag("gun_auto_reload", false) and now >= Utility.nextTry then
            local tool = Combat.gun()
            local ammo = tool and tool:GetAttribute("Local_CurrentAmmo")
            if ammo ~= nil and ammo <= 0 and (tool:GetAttribute("Local_ReloadSession") or 0) == 0
                and not (tool:GetAttribute("Behavior") == "Sniper" and (tool:GetAttribute("StoredAmmo") or 1) <= 0) then
                Utility.nextTry = now + 0.6
                Combat.reload()
                if flag("gun_auto_swap", false) then
                    task.delay(0.15, function()
                        local _, humanoid = Combat.localParts()
                        local swap = Utility.swapTarget(tool)
                        if humanoid and swap then humanoid:EquipTool(swap) end
                    end)
                end
            end
        end
        if flag("gun_vehicle_wallbang", false) then
            if now >= Utility.carsAt then
                Utility.carsAt = now + 1
                local cars = Workspace:FindFirstChild("CarContainer")
                for _, part in ipairs(cars and cars:GetDescendants() or {}) do
                    if part:IsA("BasePart") and Utility.cars[part] == nil then
                        Utility.cars[part] = part.CanQuery
                        part.CanQuery = false
                    end
                end
            end
        elseif next(Utility.cars) then
            Utility.releaseCars()
        end
    end
    Util.onUnload(Utility.releaseCars)

    local Assist = { goal = nil, goalAt = 0, speed = 50, style = nil, part = nil, partUntil = 0, nextEval = 0, home = nil, holdUntil = 0, heading = ZERO, modified = {} }
    Combat.assist = Assist
    local assistParams = Game.newParams()
    pcall(function() assistParams.CollisionGroup = "ClientBullet" end)

    local function firing()
        if UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1) then return true end
        return clock() - (Silent.lastAuto or -10) < 0.4
    end

    function Assist.evaluate()
        local character, _, root, eye = Combat.localParts()
        local cam = Game.camera()
        if not character or not root or not cam or Util.typing() then return nil end
        if flag("wb_assist_fire", false) and not firing() then return nil end
        WB.refresh()
        local realPos = SP.realPos()
        local headOffset = eye and (eye.Position - root.Position) or HEAD_OFFSET
        local origin = realPos + headOffset
        local ref = Combat.aimRef()
        local fov, maxDist, reach = flag("wb_assist_fov", 250), flag("wb_assist_max", 200), flag("wb_assist_dist", 25)
        local candidates = {}
        for _, record in ipairs(Entities.update()) do
            if record.head and Game.relations[record.player.UserId] ~= "Friendly" and (record.root.Position - realPos).Magnitude <= maxDist then
                local screen, onScreen = Draw.project(cam, record.head.Position)
                local d = (screen - ref).Magnitude
                if onScreen and d <= fov then candidates[#candidates + 1] = { record = record, d = d } end
            end
        end
        table.sort(candidates, function(a, b) return a.d < b.d end)
        for index = 1, math.min(#candidates, 4) do
            local part = candidates[index].record.head
            local status = WB.status(origin, part, realPos)
            if status == "visible" then return nil end
            if status == "wallbang" then return nil, part end
            local delta = part.Position - realPos
            local distance = delta.Magnitude
            if distance >= 2 and assistParams then
                pcall(function() assistParams.FilterDescendantsInstances = WB.params.FilterDescendantsInstances end)
                local hit = Workspace:Raycast(realPos, delta, assistParams)
                if hit and (hit.Position - realPos).Magnitude <= reach then
                    local unit = delta / distance
                    local point = flag("wb_assist_inside", false) and (hit.Position + unit * 1.5) or (hit.Position - unit * 1.2)
                    local goal = Vector3.new(point.X, realPos.Y + math.clamp(point.Y - realPos.Y, -4, 4), point.Z)
                    if WB.status(goal + headOffset, part, goal) ~= "blocked" then return goal, part end
                end
            end
        end
        return nil
    end

    function Assist.request()
        if not Assist.goal or flag("wb_assist_method", "Server position") ~= "Server position" then return nil end
        return Assist.goal, Assist.speed, Assist.style
    end

    local function releaseMoved()
        for part in pairs(Assist.modified) do pcall(function() part.CanCollide = true end) end
        Assist.modified = {}
    end

    function Assist.move(dt, now)
        local root = Game.rootPart()
        if not root or flag("wb_assist_method", "Server position") ~= "Velocity" then
            if Assist.home or next(Assist.modified) then
                Assist.home = nil
                releaseMoved()
            end
            return
        end
        local wants = Assist.goal ~= nil and now - Assist.goalAt < 0.4
        if wants or (Assist.home and firing()) then Assist.holdUntil = now + 0.5 end
        local target
        if wants then
            Assist.home = Assist.home or root.Position
            target = Assist.goal
        elseif Assist.home and now < Assist.holdUntil then
            target = root.Position
        elseif Assist.home then
            target = Assist.home
            if (root.Position - Assist.home).Magnitude < 1.5 then
                Assist.home, Assist.heading = nil, ZERO
                releaseMoved()
                root.AssemblyLinearVelocity = ZERO
                return
            end
        else
            return
        end
        local delta = target - root.Position
        local speed = flag("wb_assist_mode", "Tween") == "Teleport" and 120 or flag("wb_assist_speed", 50)
        local velocity = ZERO
        if delta.Magnitude > 0.6 then velocity = delta.Unit * math.min(speed, delta.Magnitude / math.max(dt, 1 / 120)) end
        Assist.heading = velocity
        root.AssemblyLinearVelocity = velocity
        root.AssemblyAngularVelocity = ZERO
        if not Assist.overlap then
            pcall(function()
                Assist.overlap = OverlapParams.new()
                Assist.overlap.FilterType = Enum.RaycastFilterType.Exclude
            end)
        end
        if Assist.overlap then
            local list = { Game.camera(), Game.localCharacter() }
            for _, record in ipairs(Entities.list) do list[#list + 1] = record.model end
            local near = {}
            pcall(function()
                Assist.overlap.FilterDescendantsInstances = list
                for _, part in ipairs(Workspace:GetPartBoundsInBox(root.CFrame + Vector3.new(0, 1, 0) + velocity * 0.12, root.Size + Vector3.new(7, 2, 7), Assist.overlap)) do
                    near[part] = true
                    if part.CanCollide then
                        Assist.modified[part] = true
                        part.CanCollide = false
                    end
                end
            end)
            for part in pairs(Assist.modified) do
                if not near[part] then
                    Assist.modified[part] = nil
                    pcall(function() part.CanCollide = true end)
                end
            end
        end
    end

    function Assist.step(dt, now)
        local on = Util.bindOn("wb_assist", "wb_assist_key")
        SP.set("assist", on, Assist.request)
        if not on then
            if Assist.goal or Assist.home or next(Assist.modified) then
                Assist.goal, Assist.style, Assist.part, Assist.home = nil, nil, nil, nil
                releaseMoved()
            end
            return
        end
        if now >= Assist.nextEval then
            Assist.nextEval = now + 0.1
            local goal, part = Assist.evaluate()
            Assist.goal = goal
            if goal then
                Assist.goalAt = now
                Assist.speed = flag("wb_assist_mode", "Tween") == "Teleport" and 1e9 or flag("wb_assist_speed", 50)
                Assist.style = flag("wb_assist_visual", false) and Combat.style("wb_assist_fill", "wb_assist_line") or nil
            end
            if part then Assist.part, Assist.partUntil = part, now + 0.35 end
        end
        Assist.move(dt, now)
    end
    Util.onUnload(releaseMoved)

    local Orbit = { target = nil, angle = 0, last = nil, floorAt = 0, floorY = nil, floorFor = nil, nextPick = 0, ring = nil, ringParts = {} }
    Combat.orbit = Orbit

    local function destroyRing()
        if Orbit.ring then pcall(function() Orbit.ring:Destroy() end) end
        Orbit.ring, Orbit.ringParts = nil, {}
    end

    function Orbit.pickTarget()
        local _, _, _, eye = Combat.localParts()
        if not eye or not Game.camera() then return nil end
        local record = Combat.select("silent", Combat.aimRef(), eye.Position, { skipWall = true, limit = flag("orbit_max", 500) })
        return record and record.root or nil
    end

    local function orbitHeight(center)
        local _, destroyAt = SP.voidY(center.Y)
        local mode = flag("orbit_mode", "Under the map")
        local depth = flag("orbit_depth", 15)
        local y
        if mode == "Near void" then
            y = math.min(destroyAt + 30, center.Y - 10)
        elseif mode == "Below target" then
            y = center.Y - depth
        else
            local now = clock()
            if not Orbit.floorY or now - Orbit.floorAt > 0.25 or not Orbit.floorFor or (Orbit.floorFor - center).Magnitude > 4 then
                Orbit.floorAt, Orbit.floorFor = now, center
                Orbit.floorY = SP.floorAt(center, true)
            end
            y = (Orbit.floorY or (center.Y - 6)) - depth
        end
        return math.max(y, destroyAt + 12)
    end

    local function updateRing(center, y, radius)
        local count = 28
        if not Orbit.ring or Orbit.ring.Parent == nil then
            destroyRing()
            local folder = Instance.new("Folder")
            folder.Name = Util.randomName()
            for index = 1, count do
                local part = Instance.new("Part")
                part.Anchored, part.CanCollide, part.CanQuery, part.CanTouch, part.CastShadow = true, false, false, false, false
                part.Material = Enum.Material.Neon
                part.Parent = folder
                Orbit.ringParts[index] = part
            end
            folder.Parent = Game.camera()
            Orbit.ring = folder
        end
        local color, alpha = flag("orbit_ring_color", Color3.fromRGB(180, 120, 255)), Util.alpha("orbit_ring_color", 0.3)
        local step = (math.pi * 2) / count
        local length = math.max(radius * step * 1.05, 0.3)
        for index, part in ipairs(Orbit.ringParts) do
            local a1 = (index - 1) * step
            local p = Vector3.new(center.X + math.cos(a1) * radius, y, center.Z + math.sin(a1) * radius)
            local q = Vector3.new(center.X + math.cos(a1 + step) * radius, y, center.Z + math.sin(a1 + step) * radius)
            part.Size = Vector3.new(0.25, 0.25, length)
            part.CFrame = CFrame.lookAt((p + q) / 2, q)
            part.Color, part.Transparency = color, alpha
        end
    end

    function Orbit.request()
        if not Silent.active() then
            Orbit.last = nil
            destroyRing()
            return nil
        end
        local now = clock()
        local target = Orbit.target
        if not target or not target.Parent or now >= Orbit.nextPick then
            target = Orbit.pickTarget()
            Orbit.target, Orbit.nextPick = target, now + 0.1
        end
        if not target or not target.Parent then
            Orbit.last = nil
            destroyRing()
            return nil
        end
        local dt = Orbit.last and math.min(now - Orbit.last, 0.1) or 0
        Orbit.last = now
        local spin = math.rad(flag("orbit_spin", 180))
        if flag("orbit_dir", "Clockwise") ~= "Clockwise" then spin = -spin end
        Orbit.angle = (Orbit.angle + spin * dt) % (math.pi * 2)
        local center = target.Position
        local y = orbitHeight(center)
        local radius = flag("orbit_radius", 6)
        local goal = Vector3.new(center.X + math.cos(Orbit.angle) * radius, y, center.Z + math.sin(Orbit.angle) * radius)
        if flag("orbit_ring", false) then updateRing(center, y, radius) else destroyRing() end
        local style
        if flag("orbit_visual", false) then style = Combat.style("orbit_fill", "orbit_line", flag("orbit_tracer", false) and "orbit_tracer_color" or nil) end
        return goal, flag("orbit_speed", 150), style
    end

    function Orbit.step()
        local on = Util.bindOn("orbit_on", "orbit_key")
        SP.set("orbit", on, Orbit.request)
        if not on and (Orbit.ring or Orbit.target) then
            Orbit.target, Orbit.last = nil, nil
            destroyRing()
        end
    end
    Util.onUnload(destroyRing)

    local Ind = { pool = {}, states = {}, budget = 0 }
    Combat.indicators = Ind
    local IND_LABELS = { visible = "visible", wallbang = "wallbangable", blocked = "not wallbangable" }
    local RELOAD_FALLBACK = { ["AK-47"] = 2, FAL = 2, M4A1 = 2, M9 = 2, MP5 = 2, ["Remington 870"] = 3.5, Taser = 3.4, M700 = 3, Revolver = 3 }

    local function stateColor(state)
        if state == "visible" then return flag("wb_ind_c_vis", Color3.fromRGB(90, 255, 120)) end
        if state == "wallbang" then return flag("wb_ind_c_wb", Color3.fromRGB(255, 200, 60)) end
        return flag("wb_ind_c_block", Color3.fromRGB(255, 80, 80))
    end

    local function showText(text, content, position, size, color)
        text.Text, text.Size, text.Color, text.Position, text.Visible = content, size, color, position, true
    end

    local function hide(object)
        if object then object.Visible = false end
    end

    function Ind.stateOf(record, origin, now, force)
        local cached = Ind.states[record.player]
        if cached and now - cached.t < 0.15 then return cached.s end
        if not force and Ind.budget <= 0 and cached then return cached.s end
        Ind.budget = Ind.budget - 1
        local state = WB.status(origin, record.head)
        Ind.states[record.player] = { s = state, t = now }
        return state
    end

    function Ind.wallbang(now, records)
        local cam = Game.camera()
        local _, _, root, eye = Combat.localParts()
        if not flag("wb_ind", false) or not cam or not root then
            hide(Ind.cursor)
            for _, text in pairs(Ind.pool) do text.Visible = false end
            return
        end
        WB.refresh()
        local origin = eye and eye.Position or root.Position
        local size, range = flag("wb_ind_size", 14), flag("wb_ind_range", 1000)
        local everyone = flag("wb_ind_all", false)
        local ref = Combat.aimRef()
        Ind.budget = 3
        local used, best, bestD = {}, nil, nil
        for _, record in ipairs(records) do
            if record.head and Game.relations[record.player.UserId] ~= "Friendly" and (record.root.Position - root.Position).Magnitude <= range then
                local screen, onScreen = Draw.project(cam, record.head.Position)
                if onScreen then
                    local d = (screen - ref).Magnitude
                    if not bestD or d < bestD then best, bestD = record, d end
                    if everyone then
                        local state = Ind.stateOf(record, origin, now, false)
                        local text = Ind.pool[record.player] or Draw.text(size, 7)
                        Ind.pool[record.player] = text
                        showText(text, IND_LABELS[state], Vector2.new(screen.X, screen.Y - size * 2.2), size, stateColor(state))
                        used[record.player] = true
                    end
                end
            end
        end
        for player, text in pairs(Ind.pool) do
            if not used[player] then
                text.Visible = false
                if not player.Parent then
                    Draw.remove(text)
                    Ind.pool[player], Ind.states[player] = nil, nil
                end
            end
        end
        if not flag("wb_ind_cursor", true) then return hide(Ind.cursor) end
        Ind.cursor = Ind.cursor or Draw.new("Text", { Font = 2, Outline = true, OutlineColor = BLACK, ZIndex = 8, Visible = false })
        local at = Vector2.new(ref.X + 24, ref.Y + 14)
        if best and bestD <= 250 then
            local state = Ind.stateOf(best, origin, now, true)
            showText(Ind.cursor, IND_LABELS[state] .. "  " .. Combat.displayName(best.player), at, size, stateColor(state))
        elseif flag("wb_ind_always", false) then
            showText(Ind.cursor, "no target", at, size, Color3.fromRGB(180, 180, 180))
        else
            Ind.cursor.Visible = false
        end
    end

    function Ind.reload()
        local tool = Combat.gun()
        local session = tool and tool:GetAttribute("Local_ReloadSession")
        if not flag("reload_ind", false) or type(session) ~= "number" or session <= 0 then
            hide(Ind.back)
            hide(Ind.fill)
            hide(Ind.label)
            return
        end
        local info = Game.weaponInfo(tool)
        local duration = math.max(tonumber(info.ReloadTime) or RELOAD_FALLBACK[tool.Name] or 2.5, 0.1)
        local elapsed = (tick and tick() or os.time()) - session
        local progress = math.clamp(elapsed / duration, 0, 1)
        local width, height = flag("reload_ind_w", 120), flag("reload_ind_h", 6)
        local ref = Combat.aimRef()
        local x, y = ref.X - width / 2, ref.Y + flag("reload_ind_y", 40)
        Ind.back = Ind.back or Draw.new("Square", { Filled = true, ZIndex = 6 })
        Ind.fill = Ind.fill or Draw.new("Square", { Filled = true, ZIndex = 7 })
        Ind.back.Color, Ind.back.Transparency = flag("reload_ind_back", BLACK), Util.opacity("reload_ind_back")
        Ind.back.Position, Ind.back.Size, Ind.back.Visible = Vector2.new(x - 1, y - 1), Vector2.new(width + 2, height + 2), true
        local fillColor = flag("reload_ind_fill", WHITE)
        if flag("reload_ind_grad", true) then fillColor = Util.lerpColor(Color3.fromRGB(255, 90, 90), fillColor, progress) end
        Ind.fill.Color, Ind.fill.Transparency = fillColor, Util.opacity("reload_ind_fill")
        Ind.fill.Position, Ind.fill.Size, Ind.fill.Visible = Vector2.new(x, y), Vector2.new(math.max(width * progress, 0.01), height), true
        if flag("reload_ind_text", true) then
            Ind.label = Ind.label or Draw.text(13, 8)
            showText(Ind.label, string.format("reloading %.1fs", math.max(duration - elapsed, 0)), Vector2.new(ref.X, y + height + 3), 13, WHITE)
        else
            hide(Ind.label)
        end
    end

    function Ind.ammo()
        local tool = Combat.gun()
        local serverAmmo = tool and tool:GetAttribute("CurrentAmmo")
        if not flag("ammo_ind", false) or type(serverAmmo) ~= "number" then return hide(Ind.ammoLabel) end
        local localAmmo = tool:GetAttribute("Local_CurrentAmmo")
        local maxAmmo, stored = tool:GetAttribute("MaxAmmo"), tool:GetAttribute("StoredAmmo")
        local text = tostring(serverAmmo)
        if type(stored) == "number" then text = text .. " | " .. tostring(stored) elseif type(maxAmmo) == "number" then text = text .. "/" .. tostring(maxAmmo) end
        local mismatch = type(localAmmo) == "number" and localAmmo ~= serverAmmo
        if flag("ammo_ind_local", false) and type(localAmmo) == "number" then text = text .. "  (local " .. tostring(localAmmo) .. ")" end
        if flag("ammo_ind_name", true) then text = tool.Name .. "  " .. text end
        local color
        if serverAmmo <= 0 then color = flag("ammo_ind_c_empty", Color3.fromRGB(255, 80, 80))
        elseif mismatch then color = flag("ammo_ind_c_diff", Color3.fromRGB(255, 200, 60))
        elseif type(maxAmmo) == "number" and maxAmmo > 0 and serverAmmo / maxAmmo <= 0.25 then color = flag("ammo_ind_c_diff", Color3.fromRGB(255, 200, 60))
        else color = flag("ammo_ind_c_ok", WHITE) end
        Ind.ammoLabel = Ind.ammoLabel or Draw.text(16, 8)
        local ref = Combat.aimRef()
        showText(Ind.ammoLabel, text, Vector2.new(ref.X, ref.Y + flag("ammo_ind_y", 70)), flag("ammo_ind_size", 16), color)
    end

    function Ind.step(_, now, records)
        Util.guard("wallbang indicator", Ind.wallbang, now, records)
        Util.guard("reload indicator", Ind.reload)
        Util.guard("ammo indicator", Ind.ammo)
    end

    local Info = { card = nil, signature = "", nextPick = 0 }
    Combat.info = Info

    function Info.build()
        local rows = {}
        if flag("tinfo_health", true) then rows[#rows + 1] = "Health" end
        if flag("tinfo_status", true) then
            rows[#rows + 1] = "Distance"
            rows[#rows + 1] = "Sight"
        end
        if flag("tinfo_extra", true) then
            rows[#rows + 1] = "Team"
            rows[#rows + 1] = "Weapon"
            rows[#rows + 1] = "Status"
        end
        local signature = table.concat(rows, ",")
        if Info.card and Info.signature == signature then return Info.card end
        Info.destroy()
        if type(Library.CreateInfoCard) ~= "function" then return nil end
        local ok, card = pcall(Library.CreateInfoCard, Library, { Title = "Target", Key = "pl_target", Rows = rows, Image = true, Width = 220 })
        if not ok or type(card) ~= "table" then return nil end
        Info.card, Info.signature = card, signature
        return card
    end

    function Info.destroy()
        if Info.card then pcall(function() Info.card:Destroy() end) end
        Info.card = nil
    end

    function Info.pick()
        local _, _, _, eye = Combat.localParts()
        if not eye or not Game.camera() then return nil end
        if Silent.active() then
            local record, part = Combat.select("silent", Combat.aimRef(), eye.Position, { skipWall = true, limit = Gun.range() or 1000 })
            if record then return record, part end
        end
        if flag("aim_on", false) then
            local record, part = Combat.select("aim", Combat.aimRef(), eye.Position, { skipWall = true })
            if record then return record, part end
        end
        if R.run and R.record and Entities.live(R.record) then return R.record, R.record.head or R.record.root end
        return nil
    end

    function Info.step(_, now)
        if not flag("tinfo_on", false) then
            if Info.card then Info.destroy() end
            return
        end
        local card = Info.build()
        if not card then return end
        if now >= Info.nextPick then
            Info.nextPick = now + 0.1
            Info.record, Info.part = Info.pick()
        end
        local record = Info.record
        if not (record and Entities.live(record)) then
            card:SetVisible(Util.menuOpen() or not flag("tinfo_hide", true))
            if card.SetTitle then card:SetTitle("No target") end
            return
        end
        local _, _, _, eye = Combat.localParts()
        local distance = eye and (record.root.Position - eye.Position).Magnitude or 0
        local sight = "Blocked"
        if Info.part and Info.part.Parent and eye then
            WB.refresh()
            local status = WB.status(eye.Position, Info.part)
            if status == "visible" then sight = "Visible" elseif status == "wallbang" then sight = flag("silent_wallbang", false) and "Wallbang" or "Blocked" end
        end
        local flags = {}
        local state = record.state or {}
        if state.hostile then flags[#flags + 1] = "Hostile" end
        if state.trespassing then flags[#flags + 1] = "Trespassing" end
        if state.tased then flags[#flags + 1] = "Tased" end
        if state.forcefield then flags[#flags + 1] = "Forcefield" end
        if card.SetTitle then card:SetTitle(Game.relation(record.player)) end
        card:Update({
            Name = Combat.displayName(record.player), UserId = record.player.UserId,
            Health = record.health, MaxHealth = record.maxHealth, Distance = distance, Sight = sight,
            Team = record.team, TeamColor = record.teamColor, Weapon = record.weaponName or "none",
            Status = #flags > 0 and table.concat(flags, ", ") or "-",
        })
        card:SetVisible(true)
    end
    Util.onUnload(Info.destroy)

    local Killer = { shots = {}, last = nil }
    Combat.killer = Killer
    local KILL_WINDOW = 1.5

    Util.track(Game.events.onEnemyShot:Connect(function(shooter, origin, hitPos)
        if not flag("kd_on", false) then return end
        local root = Game.rootPart()
        if not root or not shooter then return end
        if (hitPos - root.Position).Magnitude > 6 then return end
        local shots = Killer.shots
        shots[#shots + 1] = { player = shooter, at = clock(), origin = origin, far = not inBounds(origin) or (origin - hitPos).Magnitude > 400 }
        while #shots > 30 do table.remove(shots, 1) end
    end))

    function Killer.verdict(now)
        local score, best = {}, nil
        for _, shot in ipairs(Killer.shots) do
            if now - shot.at <= KILL_WINDOW then
                local entry = score[shot.player] or { player = shot.player, hits = 0, odd = 0 }
                score[shot.player] = entry
                entry.hits = entry.hits + 1
                if shot.far then entry.odd = entry.odd + 1 end
                if not best or entry.hits + entry.odd * 2 > best.hits + best.odd * 2 then best = entry end
            end
        end
        return best
    end

    Util.track(Game.events.onLocalDied:Connect(function()
        if not flag("kd_on", false) then return end
        local verdict = Killer.verdict(clock())
        Killer.shots = {}
        if not verdict then
            Killer.last = nil
            if Killer.label then Killer.label:SetText("Last killer: unknown") end
            return
        end
        local rage = verdict.odd > 0 or verdict.hits >= 4
        Killer.last = { player = verdict.player, name = verdict.player.Name, rage = rage, hits = verdict.hits }
        local text = Combat.displayName(verdict.player) .. " (@" .. verdict.player.Name .. ")" .. (rage and ", likely ragebot" or "")
        if Killer.label then Killer.label:SetText("Last killer: " .. string.sub(text, 1, 40)) end
        if flag("kd_notify", true) then Util.notify({ Title = "Killed by", Text = text, Duration = 6 }) end
        if rage and flag("kd_priority", false) then Game.relations[verdict.player.UserId] = "Priority" end
    end))

    for _, entry in ipairs({
        { "combat_gun", Gun.step, 60 }, { "combat_predict", Predict.step, 61 }, { "combat_wallbang", WB.step, 62 },
        { "combat_aim", function(dt) Aim.step(dt) end, 70 }, { "combat_circles", Circles.step, 71 }, { "combat_trigger", Trigger.step, 72 },
        { "combat_silent", Silent.step, 73 }, { "combat_mods", Mods.step, 74 }, { "combat_utility", Utility.step, 75 },
        { "combat_rage", R.step, 76 }, { "combat_assist", Assist.step, 77 }, { "combat_orbit", Orbit.step, 78 },
        { "combat_indicators", Ind.step, 120 }, { "combat_info", Info.step, 121 },
    }) do
