    local function playerNames()
        local names = {}
        for _, player in ipairs(Players:GetPlayers()) do
            if player ~= LocalPlayer then names[#names + 1] = player.Name end
        end
        table.sort(names, function(a, b) return string.lower(a) < string.lower(b) end)
        return names
    end

    function Combat.refreshNames()
        local names = playerNames()
        for _, listFlag in ipairs({ "rb_targets", "rb_white" }) do
            local option = Options[listFlag]
            if option and type(option.SetValues) == "function" then pcall(function() option:SetValues(names) end) end
        end
    end
    Util.track(Players.PlayerAdded:Connect(function() task.defer(Combat.refreshNames) end))
    Util.track(Players.PlayerRemoving:Connect(function(player)
        R.hist[player], R.skip[player], R.peekMem[player] = nil, nil, nil
        Predict.tracks[player] = nil
        task.defer(Combat.refreshNames)
    end))

    function Combat.listAdd(listFlag, player)
        local option = Options[listFlag]
        if not option or type(option.SetValue) ~= "function" then return false end
        player = player or Combat.findPlayer(flag("rb_search", "")) or (Combat.selectedPlayer and Combat.selectedPlayer())
        if not player then
            Util.notify({ Title = "Ragebot", Text = "Type a name or select a player in the Players tab first" })
            return false
        end
        local value = {}
        for key, chosen in pairs(type(option.Value) == "table" and option.Value or {}) do value[key] = chosen end
        value[player.Name] = true
        pcall(function() option:SetValue(value) end)
        return true
    end

    function Combat.addAtCursor()
        if not flag("rb_add", false) or Util.typing() then return end
        local cam = Game.camera()
        if not cam then return end
        local mouse = UserInputService:GetMouseLocation()
        local best, bestD
        for _, record in ipairs(Entities.update()) do
            local screen, onScreen = Draw.project(cam, record.root.Position)
            local d = (screen - mouse).Magnitude
            if onScreen and d <= 600 and (not bestD or d < bestD) then best, bestD = record.player, d end
        end
        local option = Options.rb_targets
        if not best or not option then return end
        local value = {}
        for key, chosen in pairs(type(option.Value) == "table" and option.Value or {}) do value[key] = chosen end
        if value[best.Name] then value[best.Name] = nil else value[best.Name] = true end
        pcall(function() option:SetValue(value) end)
        Util.notify({ Title = "Ragebot", Text = best.Name .. (value[best.Name] and " added" or " removed"), Duration = 2 })
    end

