        local Main, Rules, List, Safety = sub.Ragebot, sub["Target rules"], sub["Target list"], sub["Status and safety"]
        Main:Toggle({ Name = "Enabled", Flag = "rb_enabled", Tooltip = "Hides in the void, peeks next to the target, shoots and goes back" }):Keybind({ Name = "Ragebot key", Flag = "rb_key", Sync = true })
