    local function buildTargetInfo(group)
        group:Toggle({ Name = "Target info panel", Flag = "tinfo_on", Tooltip = "Card with the current silent aim / aim assist / ragebot target; drag it while the menu is open" })
        group:Toggle({ Name = "Show health", Flag = "tinfo_health", Default = true })
        group:Toggle({ Name = "Show distance and line of sight", Flag = "tinfo_status", Default = true })
        group:Toggle({ Name = "Show team, weapon and status", Flag = "tinfo_extra", Default = true })
        group:Toggle({ Name = "Hide without target", Flag = "tinfo_hide", Default = true })
    end

    local legit, rage = Pages and Pages.Legit, Pages and Pages.Rage
    if legit then
        if legit.Aim then Util.guard("menu legit aim", buildAim, legit.Aim) end
        if legit.Silent then Util.guard("menu legit silent", buildSilent, legit.Silent) end
        if legit.Trigger then Util.guard("menu legit trigger", buildTrigger, legit.Trigger) end
    end
    if rage then
        if rage.Ragebot then Util.guard("menu rage main", buildRagebot, rage.Ragebot) end
        if rage.Void then Util.guard("menu rage void", buildVoid, rage.Void) end
        if rage.Gun then Util.guard("menu rage gun", buildGun, rage.Gun) end
        if rage.Other then Util.guard("menu rage other", buildOther, rage.Other) end
    end
    local players = Pages and Pages.Players and Pages.Players.Main
    if players and players["Target info"] then Util.guard("menu target info", buildTargetInfo, players["Target info"]) end
end
-- pl 60_player 1-901

do
    local Player = {
        saved = {}, tracks = {}, flagged = {}, cheats = {}, walls = {}, fences = { parts = {}, nextScan = 0 }, flying = false, jumpQueued = false, jumpAt = -math.huge, labelAt = 0, label = nil, spinAngle = 0, corpse = nil,
        antiJump = { humanoid = nil, disabled = {}, hooked = false, tries = 0, nextTry = 0 },
        invis = { on = false, character = nil, track = nil, startAt = nil, held = nil },
        fling = { container = nil, modified = {}, prompts = {}, connections = {}, queue = nil, index = 0 },
        animCheck = { on = false, acc = 0, cleared = 0, suppressed = {}, verdict = {} },
    }
    local ZERO = Vector3.new(0, 0, 0)
    local UP = Vector3.new(0, 1, 0)
    local LIFT = Vector3.new(0, 3, 0)
    local FLAT = Vector3.new(1, 0, 1)
    local NONE = {}
    local PHASE_GRACE = 0.4
    local FENCE_PART, FENCE_SCAN = "damagePart", 1
    local LONG_LIFT = 30
    local MIN_MOVE = 1
    local HOOK_TRIES = 20
    local INVIS_DELAY = 0.8
    local INVIS_R15, INVIS_R6 = "18665825805", "215384594"
    local PLANE_LOW, PLANE_HIGH = -10, 179.99
    local FLING_BATCH = 1000
    local atan2 = math.atan2 or math.atan
    local RESPAWN_FLAGS = { "move_walk", "move_jump", "char_nocooldown", "char_zoom", "char_gravity" }
    local MODIFIERS = { "LeftControl", "LeftAlt", "LeftShift", "RightControl" }
    local NO_ACCEL_SKIP = {}
    for _, name in ipairs({ "Climbing", "Swimming", "Seated", "Dead", "Physics", "Ragdoll", "FallingDown", "PlatformStanding" }) do
        NO_ACCEL_SKIP[Enum.HumanoidStateType[name]] = true
    end
    local known = {}
    for _, id in ipairs({
        "125750702", "128777973", "128853357", "129423030", "129423131", "129967390", "129967478",
        "178130996", "180426354", "180435571", "180435792", "180436148", "180436334", "182393478",
        "182435998", "182436842", "182436935", "182491037", "182491065", "182491248", "182491277",
        "182491368", "182491423", "279227693", "279229192", "287112271", "388723916", "388726667",
        "389472570", "405194080", "405212265", "481088553", "481089053", "484200742", "484926359",
        "83690472549256", "107176344504758", "111090572475133", "113267949064300", "131326339350805",
    }) do known[id] = true end
    local want = {}

    local KEYS = { misc_invis = "char_invis_key" }

    local function active(name)
        if not flag(name, false) then return false end
        local key = KEYS[name] or name .. "_key"
        local picker = Options[key]
        if not picker or picker.Value == nil or picker.Value == "None" then return true end
        return Util.keyActive(key)
    end

    function Player.invisActive()
        return active("misc_invis")
    end

    local function localParts()
        local character = Game.localCharacter()
        if not character then return nil end
        return character, Game.humanoid(character), character:FindFirstChild("HumanoidRootPart")
    end

    local function read(object, prop)
        local ok, value = pcall(function() return object[prop] end)
        if ok then return value end
        return nil
    end

    local function write(object, prop, value)
        pcall(function() object[prop] = value end)
    end

    local function hold(object, prop, value)
        if not object then return end
        local saved = Player.saved[object]
        if not saved then
            saved = {}
            Player.saved[object] = saved
        end
        if saved[prop] == nil then
            local current = read(object, prop)
            if current == nil then saved[prop] = NONE else saved[prop] = current end
        end
        want[object] = want[object] or {}
        want[object][prop] = true
        if read(object, prop) ~= value then write(object, prop, value) end
    end

    local function settle()
        for object, saved in pairs(Player.saved) do
            local keep = want[object]
            for prop, original in pairs(saved) do
                if not (keep and keep[prop]) then
                    if original ~= NONE then write(object, prop, original) end
                    saved[prop] = nil
                end
            end
            if next(saved) == nil then Player.saved[object] = nil end
        end
        want = {}
    end

    local function keyDown(name)
        if type(name) ~= "string" or name == "None" then return false end
        local ok, down = pcall(function() return UserInputService:IsKeyDown(Enum.KeyCode[name]) end)
        return ok and down == true
    end

    local function flat(vector)
        if typeof(vector) ~= "Vector3" then return ZERO end
        return Vector3.new(vector.X, 0, vector.Z)
    end

    local function stateOf(humanoid)
        local ok, state = pcall(function() return humanoid:GetState() end)
        if ok then return state end
        return nil
    end

    local function changeState(humanoid, name)
        pcall(function() humanoid:ChangeState(Enum.HumanoidStateType[name]) end)
    end

    local function sourceOf(connection)
        local ok, source = pcall(function() return connection.Function and Compat.info(connection.Function, "s") end)
        if ok and type(source) == "string" then return source end
        return ""
    end

    function Player.hookJump(humanoid)
        if type(Compat.getconnections) ~= "function" then return false end
        local ok, list = pcall(Compat.getconnections, humanoid:GetPropertyChangedSignal("Jump"))
        if not ok or type(list) ~= "table" then return false end
        local disabled, found = Player.antiJump.disabled, false
        for _, connection in ipairs(list) do
            if sourceOf(connection):find("AntiJump", 1, true) then
                pcall(function() connection:Disable() end)
                disabled[#disabled + 1] = connection
                found = true
            end
        end
        if not found and list[1] and list[1].Function then
            pcall(function() list[1]:Disable() end)
            disabled[#disabled + 1] = list[1]
            found = true
        end
        return found
    end

    function Player.releaseJump()
        for _, connection in ipairs(Player.antiJump.disabled) do pcall(function() connection:Enable() end) end
        Player.antiJump = { humanoid = nil, disabled = {}, hooked = false, tries = 0, nextTry = 0 }
    end

    function Player.noCooldown(now, humanoid)
        local state = Player.antiJump
        if state.humanoid ~= humanoid then
            Player.releaseJump()
            state = Player.antiJump
            state.humanoid = humanoid
        end
        if not state.hooked and state.tries < HOOK_TRIES and now >= state.nextTry then
            state.tries, state.nextTry = state.tries + 1, now + 0.25
            state.hooked = Player.hookJump(humanoid)
        end
        if state.hooked or Util.typing() or not keyDown("Space") then return end
        if read(humanoid, "FloorMaterial") == Enum.Material.Air then return end
        local current = stateOf(humanoid)
        if current == Enum.HumanoidStateType.Running or current == Enum.HumanoidStateType.Landed then changeState(humanoid, "Jumping") end
    end

    function Player.fly(dt, humanoid, root)
        hold(humanoid, "PlatformStand", true)
        local cam = Game.camera()
        local look = cam and cam.CFrame.LookVector or Vector3.new(0, 0, -1)
        local right = Vector3.new(-look.Z, 0, look.X)
        if right.Magnitude > 0 then right = right.Unit end
        local direction = ZERO
        if not Util.typing() then
            if keyDown("W") then direction = direction + look end
            if keyDown("S") then direction = direction - look end
            if keyDown("D") then direction = direction + right end
            if keyDown("A") then direction = direction - right end
            if keyDown("Space") then direction = direction + UP end
            if keyDown("LeftControl") then direction = direction - UP end
        end
        write(root, "AssemblyLinearVelocity", ZERO)
        if direction.Magnitude > 0 then
            root.CFrame = root.CFrame + direction.Unit * (flag("move_fly_speed", 60) * dt)
        end
    end

    function Player.speed(dt, humanoid, root)
        local speed, mode = flag("move_speed_value", 50), flag("move_speed_mode", "Velocity")
        if mode == "WalkSpeed" then return hold(humanoid, "WalkSpeed", speed) end
        if stateOf(humanoid) == Enum.HumanoidStateType.Climbing then return end
        local direction = read(humanoid, "MoveDirection") or ZERO
        if mode == "CFrame" then
            root.CFrame = root.CFrame + direction * FLAT * (speed * dt)
        else
            local velocity = read(root, "AssemblyLinearVelocity") or ZERO
            write(root, "AssemblyLinearVelocity", Vector3.new(direction.X * speed, velocity.Y, direction.Z * speed))
        end
    end

    function Player.noAccel(humanoid, root)
        local walk = read(humanoid, "WalkSpeed") or 0
        if walk <= 0.1 or read(humanoid, "SeatPart") or read(humanoid, "Sit") then return end
        if NO_ACCEL_SKIP[stateOf(humanoid)] or read(humanoid, "FloorMaterial") == Enum.Material.Air then return end
        local velocity = read(root, "AssemblyLinearVelocity") or ZERO
        if flat(velocity).Magnitude > math.max(walk * 1.6, 45) then return end
        local direction = read(humanoid, "MoveDirection") or ZERO
        if direction.Magnitude > 0.05 then
            write(root, "AssemblyLinearVelocity", Vector3.new(direction.X * walk, velocity.Y, direction.Z * walk))
        else
            write(root, "AssemblyLinearVelocity", Vector3.new(0, velocity.Y, 0))
        end
    end

    function Player.spider(character, humanoid, root)
        local move = flat(read(humanoid, "MoveDirection"))
        if move.Magnitude < 0.1 then return end
        local hit = Workspace:Raycast(root.Position, move.Unit * 2.5, Game.newParams({ character }))
        if not hit then return end
        local velocity = read(root, "AssemblyLinearVelocity") or ZERO
        write(root, "AssemblyLinearVelocity", Vector3.new(velocity.X, flag("move_spider_speed", 30), velocity.Z))
    end

    function Player.jump(humanoid, root)
        local high, long = active("move_hjump"), active("move_ljump")
        if not (high or long) then return end
        local velocity = read(root, "AssemblyLinearVelocity") or ZERO
        local x, y, z = velocity.X, velocity.Y, velocity.Z
        if high then y = math.max(y, flag("move_hjump_power", 120)) end
        if long then
            local direction = flat(read(humanoid, "MoveDirection"))
            if direction.Magnitude < 0.1 then direction = flat(root.CFrame.LookVector) end
            if direction.Magnitude > 0 then
                direction = direction.Unit * flag("move_ljump_force", 100)
                x, z, y = direction.X, direction.Z, math.max(y, LONG_LIFT)
            end
        end
        write(root, "AssemblyLinearVelocity", Vector3.new(x, y, z))
    end

    local function rootJoint(character)
        local root = character:FindFirstChild("HumanoidRootPart")
        local direct = root and root:FindFirstChild("RootJoint")
        if direct and direct:IsA("Motor6D") then return direct end
        local lower = character:FindFirstChild("LowerTorso")
        local joint = lower and lower:FindFirstChild("Root")
        if joint and joint:IsA("Motor6D") then return joint end
        return nil
    end

    function Player.spin(dt, character, humanoid)
        local joint = rootJoint(character)
        if not joint then return end
        local saved = Player.saved[joint]
        local base = saved and saved.C0
        if base == nil or base == NONE then base = read(joint, "C0") end
        if typeof(base) ~= "CFrame" then return end
        Player.spinAngle = (Player.spinAngle + flag("move_spin_speed", 10) * 16 * dt) % 360
        hold(humanoid, "AutoRotate", false)
        hold(joint, "C0", CFrame.Angles(0, math.rad(Player.spinAngle), 0) * base)
    end

    function Player.phase(character)
        for _, part in ipairs(character:GetDescendants()) do
            if part:IsA("BasePart") then hold(part, "CanCollide", false) end
        end
    end

    local function phaseable(part, character)
        if not part or not part:IsA("BasePart") or part:IsA("Terrain") or part:IsDescendantOf(character) then return false end
        local model = part:FindFirstAncestorOfClass("Model")
        return not (model and model:FindFirstChildOfClass("Humanoid"))
    end

    function Player.phaseParts(now, character, humanoid, root)
        local state = Player.walls
        local params = Game.newParams({ character })
        local position = root.Position
        local hip = read(humanoid, "HipHeight") or 0
        local half = (read(root, "Size") or Vector3.new(2, 2, 1)).Y / 2
        local feet = position.Y - half - (hip > 0.1 and hip or 2)
        local floor = Workspace:Raycast(position, Vector3.new(0, -(position.Y - feet + 2.5), 0), params)
        local floorPart = floor and floor.Instance
        local direction = flat(read(humanoid, "MoveDirection"))
        if direction.Magnitude < 0.1 then direction = flat(root.CFrame.LookVector) end
        if direction.Magnitude > 0 then
            direction = direction.Unit * flag("move_phase_reach", 2.5)
            for _, height in ipairs({ feet + 1.2, position.Y, position.Y + 1.4 }) do
                local hit = Workspace:Raycast(Vector3.new(position.X, height, position.Z), direction, params)
                if hit and (hit.Normal and hit.Normal.Y or 0) < 0.7 and hit.Instance ~= floorPart and phaseable(hit.Instance, character) then state[hit.Instance] = now + PHASE_GRACE end
            end
        end
        local okBox, touching = pcall(function()
            local overlap = OverlapParams.new()
            overlap.FilterType = Enum.RaycastFilterType.Exclude
            overlap.FilterDescendantsInstances = { character }
            local bottom, top = feet + 0.8, position.Y + half + 1.6
            return Workspace:GetPartBoundsInBox(CFrame.new(position.X, (bottom + top) / 2, position.Z), Vector3.new(2.6, top - bottom, 2.6), overlap)
        end)
        if okBox and type(touching) == "table" then
            for _, part in ipairs(touching) do
                if part ~= floorPart and phaseable(part, character) then state[part] = now + PHASE_GRACE end
            end
        end
        if floorPart then state[floorPart] = nil end
        for part, untilAt in pairs(state) do
            if untilAt < now or not part.Parent then
                state[part] = nil
            else
                hold(part, "CanCollide", false)
            end
        end
    end

    function Player.clickTo(position)
        local _, _, root = localParts()
        if not (root and typeof(position) == "Vector3") then return false end
        root.CFrame = root.CFrame + (position + LIFT - root.Position)
        write(root, "AssemblyLinearVelocity", ZERO)
        return true
    end

    local function stopInvisAnim()
        local track = Player.invis.track
        if not track then return end
        Player.invis.track = nil
        pcall(function() track:Stop(0) end)
        pcall(function() track:Destroy() end)
    end

    function Player.invisAnim(humanoid)
        stopInvisAnim()
        local animator = humanoid:FindFirstChildOfClass("Animator")
        if not animator then return false end
        local r15 = read(humanoid, "RigType") == Enum.HumanoidRigType.R15
        local animation = Instance.new("Animation")
        animation.AnimationId = "rbxassetid://" .. (r15 and INVIS_R15 or INVIS_R6)
        local ok, track = pcall(function() return animator:LoadAnimation(animation) end)
        animation:Destroy()
        if not (ok and track) then return false end
        pcall(function()
            track.Priority = Enum.AnimationPriority.Action4
            track:Play(0, 1, 0)
        end)
        Player.invis.track = track
        task.defer(function()
            if Player.invis.track ~= track then return end
            pcall(function()
                track.TimePosition = r15 and 1.95 or 0.4
                track:AdjustSpeed(0)
            end)
        end)
        return true
    end

    function Player.letGo(root)
        local held = Player.invis.held
        Player.invis.held = nil
        if not (root and held) then return end
        write(root, "AssemblyLinearVelocity", ZERO)
        write(root, "AssemblyAngularVelocity", ZERO)
        root.CFrame = CFrame.new(root.Position) * CFrame.Angles(0, held.yaw, 0)
    end

    function Player.invisStep(dt, now, character, humanoid, root)
        local state = Player.invis
        if state.character ~= character then
            stopInvisAnim()
            state.held, state.startAt = nil, state.character and now + INVIS_DELAY or now
            state.character, state.on = character, true
        end
        if state.startAt and now >= state.startAt then
            if Player.invisAnim(humanoid) or now - state.startAt > 2 then state.startAt = nil end
        end
        if not flag("char_invis_under", true) then
            if state.held then Player.letGo(root) end
            return
        end
        if not state.held then
            local _, yaw = root.CFrame:ToEulerAnglesYXZ()
            state.held = { position = root.Position, yaw = yaw }
        end
        hold(humanoid, "AutoRotate", false)
        hold(humanoid, "PlatformStand", true)
        for _, part in ipairs(character:GetChildren()) do
            if part:IsA("BasePart") then hold(part, "CanCollide", false) end
        end
        if flag("char_invis_move", false) then
            local direction = read(humanoid, "MoveDirection") or ZERO
            if direction.Magnitude > 0.1 then
                state.held.position = state.held.position + flat(direction).Unit * ((read(humanoid, "WalkSpeed") or 16) * dt)
                state.held.yaw = atan2(-direction.X, -direction.Z)
            end
        end
        write(root, "AssemblyLinearVelocity", ZERO)
        write(root, "AssemblyAngularVelocity", ZERO)
        root.CFrame = CFrame.new(state.held.position) * CFrame.fromEulerAnglesYXZ(math.rad(flag("char_invis_pitch", 90)), state.held.yaw, 0)
    end

    function Player.invisOff()
        stopInvisAnim()
        local character, _, root = localParts()
        Player.letGo(root)
        if character then
            for _, part in ipairs(character:GetDescendants()) do
                if part:IsA("BasePart") then write(part, "LocalTransparencyModifier", 0) end
            end
        end
        Player.invis = { on = false, character = nil, track = nil, startAt = nil, held = nil }
    end

    function Player.killPlane(root)
        local y = root.Position.Y
        local clamped = math.clamp(y, PLANE_LOW, PLANE_HIGH)
        if clamped == y then return end
        root.CFrame = root.CFrame + Vector3.new(0, clamped - y, 0)
        write(root, "AssemblyLinearVelocity", (read(root, "AssemblyLinearVelocity") or ZERO) * FLAT)
    end

    function Player.antiRiot(records)
        for _, record in ipairs(records or {}) do
            if record.player ~= LocalPlayer and record.model then
                local shield = record.model:FindFirstChild("RiotShieldPart")
                if shield and shield:IsA("BasePart") then hold(shield, "CanQuery", false) end
            end
        end
    end

    function Player.fenceSafe(now)
        local state = Player.fences
        local stale = false
        for _, part in ipairs(state.parts) do
            if not part.Parent then stale = true end
        end
        if stale or now >= state.nextScan then
            state.nextScan = now + FENCE_SCAN
            local parts = {}
            local folder = Workspace:FindFirstChild("Prison_Fences")
            if folder then
                for _, object in ipairs(folder:GetDescendants()) do
                    if object.Name == FENCE_PART and object:IsA("BasePart") then parts[#parts + 1] = object end
                end
            end
            state.parts = parts
        end
        for _, part in ipairs(state.parts) do
            if part.Parent then hold(part, "CanTouch", false) end
        end
    end

    function Player.sinkBody(now)
        local corpse = Player.corpse
        corpse.started = corpse.started or now
        local character = corpse.character
        if not (character and character.Parent) or now - corpse.started >= 4 or not flag("char_destroy_body", false) then
            Player.corpse = nil
            return
        end
        local void = (read(Workspace, "FallenPartsDestroyHeight") or -500) - 60
        for _, part in ipairs(character:GetDescendants()) do
            if part:IsA("BasePart") then
                local position = part.Position
                write(part, "Anchored", false)
                write(part, "AssemblyLinearVelocity", ZERO)
                write(part, "AssemblyAngularVelocity", ZERO)
                write(part, "CFrame", CFrame.new(position.X, void, position.Z))
            end
        end
    end

    local function flingModify(part)
        local fling = Player.fling
        if not part:IsA("BasePart") or read(part, "CollisionGroup") == "Wheels" or fling.modified[part] then return end
        fling.modified[part] = { read(part, "CanCollide"), read(part, "CanTouch") }
        if (part:IsA("Seat") or part:IsA("VehicleSeat")) and part.Name == part.ClassName then
            local prompt = Instance.new("ProximityPrompt")
            prompt.ActionText = "Enter"
            prompt.Enabled = not read(part, "Occupant")
            prompt.MaxActivationDistance = 8
            prompt.RequiresLineOfSight = false
            prompt.Parent = part
            fling.prompts[prompt] = part
            fling.connections[#fling.connections + 1] = prompt.Triggered:Connect(function()
                local _, humanoid = localParts()
                if humanoid then pcall(function() part:Sit(humanoid) end) end
            end)
        end
        write(part, "CanCollide", false)
        write(part, "CanTouch", false)
    end

    function Player.antiFling(humanoid)
        local fling = Player.fling
        if fling.container and not fling.container.Parent then Player.flingOff() fling = Player.fling end
        if not fling.container then
            local cars = Workspace:FindFirstChild("CarContainer")
            if not cars then return end
            fling.container, fling.queue, fling.index = cars, cars:GetDescendants(), 0
            fling.connections[#fling.connections + 1] = cars.DescendantAdded:Connect(function(part) pcall(flingModify, part) end)
        end
        if fling.queue then
            local last = math.min(fling.index + FLING_BATCH, #fling.queue)
            for index = fling.index + 1, last do pcall(flingModify, fling.queue[index]) end
            fling.index = last
            if last >= #fling.queue then fling.queue = nil end
        end
        local seated = humanoid ~= nil and read(humanoid, "SeatPart") ~= nil
        for prompt, seat in pairs(fling.prompts) do
            if prompt.Parent then
                local enabled = not seated and not read(seat, "Occupant")
                if read(prompt, "Enabled") ~= enabled then write(prompt, "Enabled", enabled) end
            end
        end
    end

    function Player.flingOff()
        local fling = Player.fling
        for _, connection in ipairs(fling.connections) do pcall(function() connection:Disconnect() end) end
        for part, values in pairs(fling.modified) do
            write(part, "CanCollide", values[1])
            write(part, "CanTouch", values[2])
        end
        for prompt in pairs(fling.prompts) do pcall(function() prompt:Destroy() end) end
        Player.fling = { container = nil, modified = {}, prompts = {}, connections = {}, queue = nil, index = 0 }
    end

    local function animId(value)
        return tostring(value):match("(%d+)")
    end

    local function learn(root)
        if not root then return end
        for _, item in ipairs(root:GetDescendants()) do
            if item:IsA("Animation") then
                local id = animId(read(item, "AnimationId"))
                if id then known[id] = true end
            end
        end
    end

    function Player.considerTrack(track, other)
        local check = Player.animCheck
        if check.suppressed[track] then return end
        local animation = read(track, "Animation")
        local id = animation and animId(read(animation, "AnimationId"))
        if not id or known[id] then return end
        local key = tostring(other.UserId) .. ":" .. id
        if check.verdict[key] == nil then
            learn(game:GetService("ReplicatedStorage"))
            learn(other.Character)
            learn(other:FindFirstChildOfClass("Backpack"))
            check.verdict[key] = known[id] == true
        end
        if check.verdict[key] then return end
        check.suppressed[track] = other
        Player.cheat(other, "invalid animation", 1)
    end

    function Player.antiInvis(dt)
        local check = Player.animCheck
        if not check.on then check.on, check.acc = true, 0.25 end
        check.acc, check.cleared = check.acc + dt, check.cleared + dt
        if check.cleared > 6 then check.cleared, check.verdict = 0, {} end
        if check.acc >= 0.25 then
            check.acc = 0
            for _, other in ipairs(Players:GetPlayers()) do
                local character = other ~= LocalPlayer and other.Character
                local humanoid = character and Game.humanoid(character)
                local animator = humanoid and humanoid:FindFirstChildOfClass("Animator")
                local ok, list = false, nil
                if animator then ok, list = pcall(function() return animator:GetPlayingAnimationTracks() end) end
                if ok and type(list) == "table" then
                    for _, track in ipairs(list) do Player.considerTrack(track, other) end
                end
            end
        end
        for track in pairs(check.suppressed) do
            local ok, playing = pcall(function() return track.IsPlaying end)
            if not ok or not playing then
                check.suppressed[track] = nil
            else
                pcall(function() track:AdjustWeight(0, 0) end)
            end
        end
    end

    function Player.antiInvisOff()
        for track in pairs(Player.animCheck.suppressed) do pcall(function() track:AdjustWeight(1, 0) end) end
        Player.animCheck = { on = false, acc = 0, cleared = 0, suppressed = {}, verdict = {} }
    end

    function Player.step(dt, now, records)
        now = now or os.clock()
        local character, humanoid, root = localParts()
        local alive = humanoid ~= nil and root ~= nil and (read(humanoid, "Health") or 0) > 0
        local flying = alive and active("move_fly")
        local invis = active("misc_invis")
        local noCooldown = active("char_nocooldown")
        if alive then
            if active("move_walk") then hold(humanoid, "WalkSpeed", flag("move_walk_speed", 32)) end
            if active("move_jump") then
                hold(humanoid, "UseJumpPower", true)
                hold(humanoid, "JumpPower", flag("move_jump_power", 75))
            end
            if noCooldown then Player.noCooldown(now, humanoid) end
            if flying then Player.fly(dt, humanoid, root) end
            if Player.flying and not flying then write(root, "AssemblyLinearVelocity", ZERO) end
            if not flying then
                if active("move_speed") then
                    Player.speed(dt, humanoid, root)
                elseif active("move_noaccel") and not invis then
                    Player.noAccel(humanoid, root)
                end
                if active("move_spider") then Player.spider(character, humanoid, root) end
                if Player.jumpQueued then Player.jump(humanoid, root) end
            end
            if active("move_spin") then Player.spin(dt, character, humanoid) end
            if active("move_phase") then
                if flag("move_phase_mode", "Character") == "Part" then
                    Player.phaseParts(now, character, humanoid, root)
                else
                    Player.phase(character)
                end
            end
            if not active("move_phase") or flag("move_phase_mode", "Character") ~= "Part" then Player.walls = {} end
            if invis then Player.invisStep(dt, now, character, humanoid, root) end
            if flag("char_anti_killplane", false) then Player.killPlane(root) end
        end
        if not noCooldown and Player.antiJump.humanoid then Player.releaseJump() end
        if not invis and Player.invis.on then Player.invisOff() end
        if flag("char_anti_fling", false) then
            Player.antiFling(humanoid)
        elseif Player.fling.container then
            Player.flingOff()
        end
        if flag("char_anti_riot", false) then Player.antiRiot(records) end
        if flag("char_fence_safe", false) then
            Player.fenceSafe(now)
        elseif #Player.fences.parts > 0 then
            Player.fences = { parts = {}, nextScan = 0 }
        end
        if Player.corpse then Player.sinkBody(now) end
        Player.flying, Player.jumpQueued = flying, false
        if flag("char_zoom", false) then hold(LocalPlayer, "CameraMaxZoomDistance", flag("char_zoom_dist", 400)) end
        if active("char_gravity") then hold(Workspace, "Gravity", flag("char_gravity_value", 196.2)) end
        settle()
    end

    function Player.restoreAll()
        local _, _, root = localParts()
        if Player.flying and root then write(root, "AssemblyLinearVelocity", ZERO) end
        Player.flying, Player.jumpQueued, Player.corpse = false, false, nil
        Player.releaseJump()
        Player.invisOff()
        Player.flingOff()
        Player.antiInvisOff()
        Player.walls, Player.fences = {}, { parts = {}, nextScan = 0 }
        want = {}
        settle()
    end

    function Player.list()
        local out = {}
        for _, entry in pairs(Player.flagged) do out[#out + 1] = entry end
        table.sort(out, function(a, b) return a.name < b.name end)
        return out
    end

    local function describe(entry)
        local parts = {}
        if entry.speed > 0 then parts[#parts + 1] = string.format("%d studs/s, %d studs", math.floor(entry.speed), math.floor(entry.distance)) end
        if entry.kind then parts[#parts + 1] = entry.kind end
        return string.format("%s: %s (x%d)", entry.name, table.concat(parts, ", "), entry.count)
    end

    function Player.refreshLabel()
        if not Player.label then return end
        local lines = {}
        for _, entry in ipairs(Player.list()) do lines[#lines + 1] = describe(entry) end
        Player.label:SetText(#lines > 0 and table.concat(lines, "\n") or "Nobody flagged")
    end

    function Player.report(other, speed, distance, kind)
        local entry = Player.flagged[other]
        if not entry then
            entry = { player = other, name = other.Name, count = 0, speed = 0, distance = 0, kind = kind }
            Player.flagged[other] = entry
            if flag("mon_notify", true) then
                local text = kind and string.format("%s may be cheating (%s)", other.Name, kind)
                    or string.format("%s moved %d studs (%d studs/s)", other.Name, math.floor(distance), math.floor(speed))
                Util.notify({ Title = "Player monitor", Text = text, Duration = 5, Id = "mon_" .. other.Name })
            end
        end
        entry.count = entry.count + 1
        entry.speed = math.max(entry.speed, speed)
        entry.distance = math.max(entry.distance, distance)
        entry.kind = entry.kind or kind
        Player.labelAt = 0
    end

    function Player.cheat(other, kind, limit)
        if not flag("mon_on", false) then return end
        local counts = Player.cheats[other]
        if not counts then
            counts = {}
            Player.cheats[other] = counts
        end
        counts[kind] = (counts[kind] or 0) + 1
        if counts[kind] > limit then Player.report(other, 0, 0, kind) end
    end

    function Player.clear()
        Player.flagged, Player.cheats = {}, {}
        Player.refreshLabel()
    end

    function Player.sample(other, now, dt, limit)
        local character = other.Character
        local humanoid = character and Game.humanoid(character)
        local root = character and character:FindFirstChild("HumanoidRootPart")
        if not (humanoid and root) or (read(humanoid, "Health") or 0) <= 0 or read(humanoid, "SeatPart") then
            Player.tracks[other] = nil
            return
        end
        local position, team = root.Position, other.Team
        local track = Player.tracks[other]
        if not track or track.root ~= root or track.team ~= team then
            Player.tracks[other] = { root = root, team = team, position = position, at = now }
            return
        end
        local distance = (position - track.position).Magnitude
        local elapsed = math.max(now - track.at, dt, 1 / 240)
        track.position, track.at = position, now
        if distance < MIN_MOVE then return end
        local speed = distance / elapsed
        if speed > limit then Player.report(other, speed, distance) end
    end

    function Player.monitorStep(dt, now)
        if flag("char_anti_invis", false) then
            Player.antiInvis(dt)
        elseif Player.animCheck.on then
            Player.antiInvisOff()
        end
        if not flag("mon_on", false) then
            if next(Player.tracks) then Player.tracks = {} end
            return
        end
        local limit = flag("mon_speed", 150)
        local seen = {}
        for _, other in ipairs(Players:GetPlayers()) do
            if other ~= LocalPlayer then
                seen[other] = true
                Player.sample(other, now, dt, limit)
            end
        end
        for other in pairs(Player.tracks) do
            if not seen[other] then Player.tracks[other] = nil end
        end
        if now - Player.labelAt >= 0.5 then
            Player.labelAt = now
            Player.refreshLabel()
        end
    end

    local okJump, jumpRequest = pcall(function() return UserInputService.JumpRequest end)
    if okJump and jumpRequest then
        Util.track(jumpRequest:Connect(function()
            if active("move_infjump") then
                local _, humanoid = localParts()
                if humanoid then changeState(humanoid, "Jumping") end
            end
            if not (active("move_hjump") or active("move_ljump")) then return end
            local now = os.clock()
            if now - Player.jumpAt < 0.3 then return end
            local _, humanoid = localParts()
            if not humanoid or read(humanoid, "FloorMaterial") == Enum.Material.Air then return end
            Player.jumpAt, Player.jumpQueued = now, true
        end))
    end

    local okStepped, stepped = pcall(function() return RunService.Stepped end)
    if okStepped and stepped then
        Util.track(stepped:Connect(function()
            if not active("move_phase") then return end
            for object, saved in pairs(Player.saved) do
                if saved.CanCollide ~= nil and read(object, "CanCollide") then write(object, "CanCollide", false) end
            end
        end))
    end

    Util.track(Game.events.onLocalDied:Connect(function()
        if not flag("char_destroy_body", false) then return end
        local character = Game.localCharacter()
        if character then Player.corpse = { character = character } end
    end))

    Util.track(UserInputService.InputBegan:Connect(function(input, processed)
        if processed or not flag("move_clicktp", false) or Util.typing() then return end
        if input.UserInputType ~= Enum.UserInputType.MouseButton1 then return end
        if not keyDown(flag("move_clicktp_mod", "LeftControl")) then return end
        local ok, hit = pcall(function() return LocalPlayer:GetMouse().Hit end)
        if ok and hit then Player.clickTo(hit.Position) end
    end))

    Util.track(LocalPlayer.CharacterAdded:Connect(function()
        Player.flying, Player.jumpQueued = false, false
        if flag("char_reapply", true) then return end
        for _, name in ipairs(RESPAWN_FLAGS) do
            local toggle = Toggles[name]
            if toggle and toggle.Value then pcall(toggle.SetValue, toggle, false) end
        end
    end))

    Util.track(Players.PlayerRemoving:Connect(function(other)
        Player.tracks[other], Player.cheats[other] = nil, nil
        if Player.flagged[other] then
            Player.flagged[other] = nil
            Player.labelAt = 0
        end
    end))

    local function buildMovement(page)
        local Fly, Speed, Walk, Spider, Jumps, Phase, JumpMult, Extras, ClickTp = page["Fly"], page["Speed"], page["Walk speed"], page["Spider"], page["High / long jump"], page["Phase"], page["Jump mult"], page["Movement extras"], page["Click TP"]
        Fly:Toggle({ Name = "Fly", Flag = "move_fly", Tooltip = "WASD follows the camera, Space up, Ctrl down" }):Keybind({ Name = "Fly key", Flag = "move_fly_key", Mode = "Toggle" })
        Fly:Slider({ Name = "Fly speed", Flag = "move_fly_speed", Min = 10, Max = 300, Default = 60, Decimals = 1, Suffix = " studs/s" })
        Speed:Toggle({ Name = "Speed", Flag = "move_speed" }):Keybind({ Name = "Speed key", Flag = "move_speed_key", Mode = "Hold" })
        Speed:Dropdown({ Name = "Mode", Flag = "move_speed_mode", Items = { "Velocity", "CFrame", "WalkSpeed" }, Default = "Velocity" })
        Speed:Slider({ Name = "Speed", Flag = "move_speed_value", Min = 1, Max = 150, Default = 50, Decimals = 1, Suffix = " studs/s" })
        Walk:Toggle({ Name = "Walk speed", Flag = "move_walk" }):Keybind({ Name = "Walk speed key", Flag = "move_walk_key", Mode = "Toggle" })
        Walk:Slider({ Name = "Speed", Flag = "move_walk_speed", Min = 0, Max = 250, Default = 32, Decimals = 1 })
        Spider:Toggle({ Name = "Wall climb", Flag = "move_spider", Tooltip = "Walk into a wall to climb it" }):Keybind({ Name = "Wall climb key", Flag = "move_spider_key", Mode = "Hold" })
        Spider:Slider({ Name = "Climb speed", Flag = "move_spider_speed", Min = 5, Max = 100, Default = 30, Decimals = 1, Suffix = " studs/s" })
        Jumps:Toggle({ Name = "High jump", Flag = "move_hjump" }):Keybind({ Name = "High jump key", Flag = "move_hjump_key", Mode = "Hold" })
        Jumps:Slider({ Name = "Jump velocity", Flag = "move_hjump_power", Min = 50, Max = 500, Default = 120, Decimals = 1 })
        Jumps:Toggle({ Name = "Long jump", Flag = "move_ljump" }):Keybind({ Name = "Long jump key", Flag = "move_ljump_key", Mode = "Hold" })
        Jumps:Slider({ Name = "Forward push", Flag = "move_ljump_force", Min = 20, Max = 300, Default = 100, Decimals = 1 })
        Phase:Toggle({ Name = "No collision", Flag = "move_phase", Tooltip = "Walk through walls; collisions come back exactly as they were when off" }):Keybind({ Name = "Phase key", Flag = "move_phase_key", Mode = "Toggle" })
        Phase:Dropdown({ Name = "Phase mode", Flag = "move_phase_mode", Items = { "Character", "Part" }, Default = "Character", Tooltip = "Character: your whole body stops colliding. Part: only walls you touch or walk toward stop colliding, on your screen; the floor under you stays solid" })
        Phase:Slider({ Name = "Wall reach", Flag = "move_phase_reach", Min = 1, Max = 8, Default = 2.5, Decimals = 0.1, Suffix = " studs", Tooltip = "Part mode: how far ahead walls are opened" })
        JumpMult:Toggle({ Name = "Jump power", Flag = "move_jump" }):Keybind({ Name = "Jump power key", Flag = "move_jump_key", Mode = "Toggle" })
        JumpMult:Slider({ Name = "Power", Flag = "move_jump_power", Min = 0, Max = 300, Default = 75, Decimals = 1 })
        Extras:Toggle({ Name = "Infinite jump", Flag = "move_infjump", Tooltip = "Jump again in mid air" }):Keybind({ Name = "Infinite jump key", Flag = "move_infjump_key", Mode = "Toggle" })
        Extras:Toggle({ Name = "No acceleration", Flag = "move_noaccel", Tooltip = "Start and stop at full speed instead of speeding up and sliding" }):Keybind({ Name = "No acceleration key", Flag = "move_noaccel_key", Mode = "Toggle" })
        Extras:Toggle({ Name = "Spinbot", Flag = "move_spin" }):Keybind({ Name = "Spinbot key", Flag = "move_spin_key", Mode = "Toggle" })
        Extras:Slider({ Name = "Spin speed", Flag = "move_spin_speed", Min = 1, Max = 40, Default = 10, Decimals = 1 })
        ClickTp:Toggle({ Name = "Click to move", Flag = "move_clicktp", Tooltip = "Hold the modifier and left click to move there" })
        ClickTp:Dropdown({ Name = "Modifier", Flag = "move_clicktp_mod", Items = MODIFIERS, Default = "LeftControl" })
    end

    local function buildCharacter(page)
        local Char, Invis, Protect = page["Character"], page["Invisibility"], page["Protection"]
        Char:Toggle({ Name = "No jump cooldown", Flag = "char_nocooldown", Tooltip = "Turns off the game's AntiJump script. Without getconnections, holding Space jumps again on landing" }):Keybind({ Name = "No jump cooldown key", Flag = "char_nocooldown_key", Mode = "Toggle" })
        Char:Toggle({ Name = "Max zoom", Flag = "char_zoom" })
        Char:Slider({ Name = "Zoom distance", Flag = "char_zoom_dist", Min = 10, Max = 2000, Default = 400, Decimals = 1, Suffix = " studs" })
        Char:Toggle({ Name = "Gravity", Flag = "char_gravity" }):Keybind({ Name = "Gravity key", Flag = "char_gravity_key", Mode = "Toggle" })
        Char:Slider({ Name = "Gravity value", Flag = "char_gravity_value", Min = 0, Max = 400, Default = 196.2, Decimals = 0.1 })
        Char:Toggle({ Name = "Keep after respawn", Flag = "char_reapply", Default = true, Tooltip = "On: walk speed, jump power, jump cooldown, zoom and gravity carry over to a new character. Off: they switch off when you respawn" })
        Invis:Toggle({ Name = "Invisibility", Flag = "misc_invis" }):Keybind({ Name = "Invisibility key", Flag = "char_invis_key", Mode = "Toggle" })
        Invis:Toggle({ Name = "Hide under the map (look up)", Flag = "char_invis_under", Default = true })
        Invis:Toggle({ Name = "Move while hidden", Flag = "char_invis_move" })
        Invis:Slider({ Name = "Look-up pitch", Flag = "char_invis_pitch", Min = -90, Max = 90, Default = 90, Decimals = 1, Suffix = " deg" })
        Protect:Toggle({ Name = "Anti fling", Flag = "char_anti_fling", Tooltip = "Cars stop colliding with you; car seats get an Enter prompt" })
        Protect:Toggle({ Name = "Destroy body on death", Flag = "char_destroy_body" })
        Protect:Toggle({ Name = "Anti riot shield", Flag = "char_anti_riot", Tooltip = "Shots pass through other players' riot shields" })
        Protect:Toggle({ Name = "Anti kill plane", Flag = "char_anti_killplane" })
        Protect:Toggle({ Name = "Fence protection", Flag = "char_fence_safe", Tooltip = "The electrified prison fences stop registering your touch, so they do not hurt you; restored when off" })
        Protect:Toggle({ Name = "Anti invisible", Flag = "char_anti_invis", Tooltip = "Mutes animations no game asset uses (invisibility exploits). With the movement monitor on, the player is also flagged" })
    end

    local function buildMonitor(box)
        box:Toggle({ Name = "Movement monitor", Flag = "mon_on", Tooltip = "Lists players whose root moves faster than the limit (teleports, speed)" })
        box:Slider({ Name = "Speed limit", Flag = "mon_speed", Min = 30, Max = 1000, Default = 150, Decimals = 1, Suffix = " studs/s" })
        box:Toggle({ Name = "Notify", Flag = "mon_notify", Default = true })
        Player.label = box:Label({ Name = "Nobody flagged yet; players moving too fast show up here" })
        box:Button({ Name = "Clear list", Callback = function() Player.clear() end })
    end

    local misc = Pages and Pages.Misc
    if misc and misc.Movement then Util.guard("menu movement", buildMovement, misc.Movement) end
    if misc and misc.Character then Util.guard("menu character", buildCharacter, misc.Character) end
    local players = Pages and Pages.Players and Pages.Players.Main
    local monitorBox = (players and players["Cheat detector"]) or (misc and misc.Character and misc.Character["Character"])
    if monitorBox then Util.guard("menu monitor", buildMonitor, monitorBox) end

    Util.player = Player

    Util.systems = Util.systems or {}
    table.insert(Util.systems, { name = "player_move", fn = Player.step, priority = 35 })
    table.insert(Util.systems, { name = "player_monitor", fn = Player.monitorStep, priority = 145 })

    Util.onUnload(function()
        Player.restoreAll()
        Player.tracks, Player.flagged, Player.cheats, Player.label = {}, {}, {}, nil
        if Util.player == Player then Util.player = nil end
    end)
end
-- pl 65_misc_combat 1-281

do
    local MC = { active = {}, acc = { melee = 0, arrest = 0, taze = 0 }, arrestUntil = 0, cooldown = 0, job = nil, warned = false, tasedUntil = 0, lastSpeed = 16, lastJump = 7.2 }
    local TASE_ANIMS = { ["279227693"] = true, ["279229192"] = true }

    local function localParts()
        local character = Game.localCharacter()
        if not character then return nil end
        local humanoid = Game.humanoid(character)
        local root = character:FindFirstChild("HumanoidRootPart")
        if humanoid and root and humanoid.Health > 0 then return character, humanoid, root end
        return nil
    end

    local function edge(name, on)
        local was = MC.active[name] == true
        MC.active[name] = on
        if on and not was then return "start" end
        if was and not on then return "stop" end
        return nil
    end

    local function usable(record)
        return record.player ~= LocalPlayer and record.head ~= nil and record.root ~= nil and record.humanoid ~= nil and record.humanoid.Health > 0
    end

    function MC.melee(dt, now, records)
        local on = flag("mc_melee", false)
        if edge("melee", on) == "start" then MC.acc.melee = 0 end
        if not on then return end
        MC.acc.melee = MC.acc.melee + dt
        if MC.acc.melee < flag("mc_melee_delay", 0.5) then return end
        MC.acc.melee = 0
        local melee = Game.remote("meleeEvent")
        if not melee then Util.note("mc_melee_remote", "meleeEvent not found") return end
        local _, _, root = localParts()
        if not root then return end
        local range = flag("mc_melee_range", 15)
        for _, record in ipairs(records or {}) do
            if usable(record) and (record.root.Position - root.Position).Magnitude < range
                and not (flag("mc_melee_friendly", true) and Game.relation(record.player) == "Friendly")
                and not (flag("mc_melee_ff", true) and record.model:FindFirstChildOfClass("ForceField")) then
                melee:FireServer(record.player, 1, 1)
            end
        end
    end

    function MC.arrestable(record)
        local model, state, team = record.model, Game.state(record.player), Game.team(record.player)
        if model:FindFirstChildOfClass("ForceField") or model:GetAttribute("Arrested") then return false end
        if team == "Criminals" then return flag("mc_arrest_criminals", true) end
        if team == "Inmates" then
            if not flag("mc_arrest_inmates", true) then return false end
            if state.hostile then return state.tased end
            return state.trespassing
        end
        return false
    end

    function MC.arrest(dt, now, records)
        local on = flag("mc_arrest", false)
        if edge("arrest", on) == "start" then MC.warned = false end
        if not on then return end
        MC.acc.arrest = MC.acc.arrest + dt
        if MC.acc.arrest < 0.05 or now < MC.arrestUntil then return end
        MC.acc.arrest = 0
        local arrest = Game.remote("Remotes.ArrestPlayer")
        if not arrest then Util.note("mc_arrest_remote", "ArrestPlayer remote not found") return end
        local character, humanoid, root = localParts()
        if not character or Game.team(LocalPlayer) ~= "Guards" then return end
        local range = math.min(flag("mc_arrest_range", 7.5), 7.5)
        local best, bestDist
        for _, record in ipairs(records or {}) do
            if usable(record) then
                local dist = (record.root.Position - root.Position).Magnitude
                if dist <= range and MC.arrestable(record) and (not bestDist or dist < bestDist) then
                    best, bestDist = record, dist
                end
            end
        end
        if not best then return end

        if not character:FindFirstChild("Handcuffs") and flag("mc_arrest_hand", true) then
            local pack = LocalPlayer:FindFirstChildOfClass("Backpack")
            local cuffs = pack and pack:FindFirstChild("Handcuffs")
            if cuffs then
                humanoid:EquipTool(cuffs)
                MC.arrestUntil = now + 0.4
            elseif not MC.warned then
                MC.warned = true
                Util.notify({ Text = "Auto arrest needs the Handcuffs tool", Duration = 4 })
            end
            return
        end

        local target = best.player
        MC.arrestUntil = now + 0.5
        task.spawn(function()
            local ok, result = pcall(function() return arrest:InvokeServer(target, 1) end)
            if ok and result then
                MC.arrestUntil = os.clock() + 7
                if flag("mc_arrest_notify", false) then Util.notify({ Text = "Arrested " .. target.Name, Duration = 4 }) end
            end
        end)
    end

    function MC.wanted(player, model)
        if LocalPlayer.TeamColor == player.TeamColor then return false end
        local state = Game.state(player)
        if state.tased or model:GetAttribute("Arrested") or model:FindFirstChildOfClass("ForceField") then return false end
        if Game.team(LocalPlayer) == "Guards" then
            local team = Game.team(player)
            if team == "Criminals" then return true end
            if team == "Inmates" then return state.hostile or state.trespassing end
            return false
        end
        return true
    end

    local function visible(from, record, character)
        return Workspace:Raycast(from, record.head.Position - from, Game.newParams({ character, record.model })) == nil
    end

    local function fireAt(part, position)
        local combat = Util.combat
        return combat ~= nil and type(combat.fireAt) == "function" and combat.fireAt(part, position) == true
    end

    local function finishJob(now)
        MC.job = nil
        MC.cooldown = now + 1.5
    end

    local function shootJob(job, now)
        finishJob(now)
        local character = LocalPlayer.Character
        if not character or job.taser.Parent ~= character then return end
        local head = character:FindFirstChild("Head")
        if not head then return end
        if fireAt(job.head, job.head.Position) then return end
        local shoot = Game.remote("GunRemotes.ShootEvent")
        if shoot then
            pcall(function() shoot:FireServer({ { head.Position, job.head.Position, job.head } }) end)
        end
    end

    function MC.runJob(now)
        local job = MC.job
        if now < job.nextPoll then return end
        job.nextPoll = now + 0.05
        local character = LocalPlayer.Character
        if not character or not job.head.Parent or not job.humanoid or job.humanoid.Health <= 0 then return finishJob(now) end
        if not flag("mc_taze", false) or not MC.wanted(job.player, job.model) then return finishJob(now) end
        if now >= job.deadline then return shootJob(job, now) end
        if job.taser.Parent == character then
            local reload = job.taser:GetAttribute("Local_ReloadSession") or 0
            local ammo = job.taser:GetAttribute("Local_CurrentAmmo") or 1
            if reload == 0 and ammo > 0 then return shootJob(job, now) end
            if reload == 0 and ammo <= 0 and not job.kicked then
                job.kicked = true
                fireAt(job.head, job.head.Position)
            end
        end
    end

    function MC.taze(dt, now, records)
        local on = flag("mc_taze", false)
        local change = edge("taze", on)
        local combat = Util.combat
        if change == "start" then
            MC.acc.taze = 0
            if combat and combat.wants then combat.wants.auto = true end
        elseif change == "stop" then
            if combat and combat.wants then combat.wants.auto = nil end
            if MC.job then finishJob(now) end
        end
        if not on then return end
        MC.acc.taze = MC.acc.taze + dt
        if MC.job then return MC.runJob(now) end
        if MC.acc.taze < 0.05 or now < MC.cooldown or (MC.arrestUntil - now) >= 3 then return end
        MC.acc.taze = 0
        local character, humanoid, root = localParts()
        if not character then return end
        local pack = LocalPlayer:FindFirstChildOfClass("Backpack")
        local taser = character:FindFirstChild("Taser") or (pack and pack:FindFirstChild("Taser"))
        if not taser then return end
        if flag("mc_taze_velocity", true) and root.AssemblyLinearVelocity.Magnitude >= 40 then return end
        local head = character:FindFirstChild("Head")
        if not head then return end
        local range = flag("mc_taze_range", 52)
        local best, bestDist
        for _, record in ipairs(records or {}) do
            if usable(record) then
                local dist = (record.head.Position - head.Position).Magnitude
                if dist <= range and MC.wanted(record.player, record.model) and visible(head.Position, record, character) and (not bestDist or dist < bestDist) then
                    best, bestDist = record, dist
                end
            end
        end
        if not best then return end
        if taser.Parent ~= character then humanoid:EquipTool(taser) end
        MC.job = { player = best.player, model = best.model, head = best.head, humanoid = best.humanoid, taser = taser, deadline = now + 5, nextPoll = now, kicked = false }
        MC.runJob(now)
    end

    function MC.onTased()
        if not flag("mc_antitaze", false) then return end
        MC.tasedUntil = os.clock() + 4
        task.delay(0.15, function()
            pcall(function() game:GetService("StarterGui"):SetCore("ResetButtonCallback", true) end)
        end)
    end

    function MC.antiTaze(dt, now)
        local on = flag("mc_antitaze", false)
        if edge("antitaze", on) == "stop" then MC.tasedUntil = 0 end
        if not on then return end
        local _, humanoid = localParts()
        if not humanoid then return end
        if now < MC.tasedUntil then
            if humanoid.WalkSpeed < MC.lastSpeed then humanoid.WalkSpeed = MC.lastSpeed end
            if humanoid.JumpHeight < MC.lastJump then humanoid.JumpHeight = MC.lastJump end
            if flag("mc_antitaze_anim", false) then
                pcall(function()
                    LocalPlayer:SetAttribute("BackpackEnabled", true)
                    local animator = humanoid:FindFirstChildOfClass("Animator")
                    if animator then
                        for _, track in ipairs(animator:GetPlayingAnimationTracks()) do
                            local id = track.Animation and tostring(track.Animation.AnimationId):match("%d+")
                            if id and TASE_ANIMS[id] then track:Stop(0) end
                        end
                    end
                end)
            end
        else
            if humanoid.WalkSpeed > 0 then MC.lastSpeed = humanoid.WalkSpeed end
            if humanoid.JumpHeight > 0 then MC.lastJump = humanoid.JumpHeight end
        end
    end

    MC.tasedConnection = Game.events.onTased:Connect(MC.onTased)

    local function build(page)
        local Melee, Arrest, Taze, Anti = page["Melee aura"], page["Auto arrest"], page["Auto taze"], page["Anti taze"]
        Melee:Toggle({ Name = "Melee aura", Flag = "mc_melee" })
        Melee:Slider({ Name = "Range", Flag = "mc_melee_range", Min = 1, Max = 15, Default = 15, Suffix = " studs", Decimals = 1 })
        Melee:Slider({ Name = "Delay", Flag = "mc_melee_delay", Min = 0.1, Max = 1, Default = 0.5, Suffix = "s", Decimals = 0.05 })
        Melee:Toggle({ Name = "Skip friendly players", Flag = "mc_melee_friendly", Default = true })
        Melee:Toggle({ Name = "Skip forcefield", Flag = "mc_melee_ff", Default = true })
        Arrest:Toggle({ Name = "Auto arrest", Flag = "mc_arrest" })
        Arrest:Slider({ Name = "Range", Flag = "mc_arrest_range", Min = 1, Max = 7.5, Default = 7.5, Suffix = " studs", Decimals = 0.1 })
        Arrest:Toggle({ Name = "Equip handcuffs", Flag = "mc_arrest_hand", Default = true })
        Arrest:Toggle({ Name = "Arrest inmates", Flag = "mc_arrest_inmates", Default = true })
        Arrest:Toggle({ Name = "Arrest criminals", Flag = "mc_arrest_criminals", Default = true })
        Arrest:Toggle({ Name = "Notify on arrest", Flag = "mc_arrest_notify" })
        Taze:Toggle({ Name = "Auto taze", Flag = "mc_taze" })
        Taze:Slider({ Name = "Range", Flag = "mc_taze_range", Min = 1, Max = 52, Default = 52, Suffix = " studs", Decimals = 1 })
        Taze:Toggle({ Name = "Velocity check", Flag = "mc_taze_velocity", Default = true })
        Anti:Toggle({ Name = "Anti taze", Flag = "mc_antitaze" })
        Anti:Toggle({ Name = "Anti taze: no animation", Flag = "mc_antitaze_anim", Tooltip = "Also stops the taze animation and keeps your backpack usable. It never touches the game's scripts, so it can not crash the game" })
    end

    local misc = Pages and Pages.Misc
    if misc and misc.Combat then Util.guard("menu misc combat", build, misc.Combat) end

    Util.miscCombat = MC

    Util.systems = Util.systems or {}
