    table.insert(Util.systems, { name = "mc_melee", fn = MC.melee, priority = 90 })
    table.insert(Util.systems, { name = "mc_arrest", fn = MC.arrest, priority = 91 })
    table.insert(Util.systems, { name = "mc_taze", fn = MC.taze, priority = 92 })

    Util.onUnload(function()
        if MC.tasedConnection then MC.tasedConnection:Disconnect() end
        local combat = Util.combat
        if combat and combat.wants then combat.wants.auto = nil end
        MC.job, MC.tasedConnection, MC.active, MC.tasedUntil = nil, nil, {}, 0
        if Util.miscCombat == MC then Util.miscCombat = nil end
    end)
end
