    }
    Map.PADS = {
        { "Prison garage", Vector3.new(606.5, 95.3, 2494.45) },
        { "City", Vector3.new(-191.61, 51.67, 1880.09) },
        { "Gas station", Vector3.new(-525.95, 51.68, 1774.2) },
        { "Criminal base", Vector3.new(-909.81, 92.23, 2164.27) },
    }

    local function say(text)
        Util.notify({ Title = "Map", Text = text, Duration = 3 })
    end

    local function localParts()
        local character = Game.localCharacter()
        if not character then return nil end
        return character, Game.humanoid(character), character:FindFirstChild("HumanoidRootPart")
    end

    local function assign(object, key, value)
        if object[key] ~= value then pcall(function() object[key] = value end) end
    end

    local function list(names)
        local out = {}
        for index, entry in ipairs(names) do out[index] = entry[1] end
        return out
    end

    local function anchorOf(entries, name)
        for _, entry in ipairs(entries) do
            if entry[1] == name then return entry[2] end
        end
        return nil
    end

    local function firstPart(model)
        if model:IsA("BasePart") then return model end
        for _, child in ipairs(model:GetChildren()) do
            if child:IsA("BasePart") then return child end
        end
        for _, child in ipairs(model:GetDescendants()) do
            if child:IsA("BasePart") then return child end
        end
        return nil
    end

    function Map.findTool(name)
        local pack = LocalPlayer:FindFirstChildOfClass("Backpack")
        local character = Game.localCharacter()
        return (pack and pack:FindFirstChild(name)) or (character and character:FindFirstChild(name)) or nil
    end

    function Map.scanGivers()
        local found = {}
        for _, object in ipairs(Workspace:GetDescendants()) do
            if object:IsA("Model") then
                local tool = object:GetAttribute("ToolName")
                if type(tool) == "string" then
                    found[tool] = found[tool] or {}
                    table.insert(found[tool], object)
                end
            end
        end
        Map.givers, Map.giversAt = found, clock()
        return found
    end

    function Map.giversFor(name)
        local cached = Map.givers[name]
        local stale = clock() - Map.giversAt > 15 or not cached
        if cached then
            for _, model in ipairs(cached) do
                if not model.Parent then stale = true end
            end
        end
        if stale then Map.scanGivers() end
        return Map.givers[name] or {}
    end

    function Map.sources(name)
        local out = {}
        for _, model in ipairs(Map.giversFor(name)) do
            local touch = model:FindFirstChild("TouchGiver")
            if touch then
                out[#out + 1] = { part = touch, kind = "touch", model = model }
            else
                local part = model:FindFirstChild("ITEMPICKUP") or firstPart(model)
                if part then out[#out + 1] = { part = part, kind = "interact", model = model } end
            end
        end
        local items = Workspace:FindFirstChild("Prison_ITEMS")
        local giver = items and items:FindFirstChild("giver")
        if giver then
            for _, model in ipairs(giver:GetChildren()) do
                if model.Name == name and not model:GetAttribute("ToolName") then
                    for _, part in ipairs(model:GetChildren()) do
                        if part.Name == "ITEMPICKUP" then out[#out + 1] = { part = part, kind = "interact", model = model } end
                    end
                end
            end
        end
        local root = Game.rootPart()
        local from = root and root.Position or ZERO
        table.sort(out, function(a, b)
            if a.kind ~= b.kind then return a.kind == "touch" end
            return (a.part.Position - from).Magnitude < (b.part.Position - from).Magnitude
        end)
        return out
    end

    function Map.interact(target)
        local remote = Game.remote("Remotes.InteractWithItem")
        if not remote then
            say("InteractWithItem remote not found")
            return false
        end
        task.spawn(function() pcall(function() remote:InvokeServer(target) end) end)
        return true
    end

    local function startSource(job, now)
        local source = job.sources[job.index]
        job.source, job.started, job.invokeAt, job.touchAt = source, now, now + 0.2, 0
        local lift = source.kind == "touch" and Vector3.new(0, 2.5, 0) or LIFT
        job.stand = CFrame.new(source.part.Position + lift)
    end

    function Map.begin(job)
        local _, humanoid, root = localParts()
        if not root or not humanoid or humanoid.Health <= 0 then
            say("You need to be alive")
            return false
        end
        job.index, job.home = 1, root.CFrame
        Map.job = job
        startSource(job, clock())
        return true
    end

    function Map.nextJob()
        while not Map.job and #Map.queue > 0 do
            local name = table.remove(Map.queue, 1)
            if Map.findTool(name) then
                say("Already have " .. name)
            else
                local sources = Map.sources(name)
                if #sources == 0 then
                    say(name .. " giver not found, it may be taken")
                elseif not Map.begin({ name = name, sources = sources, check = function() return Map.findTool(name) ~= nil end }) then
                    Map.queue = {}
                end
            end
        end
    end

    function Map.request(name)
        if Map.job and Map.job.name == name then return false end
        for _, queued in ipairs(Map.queue) do
            if queued == name then return false end
        end
        table.insert(Map.queue, name)
        Map.nextJob()
        return true
    end

    function Map.getWeapon(name)
        return Map.request(name)
    end

    function Map.gettingWeapon()
        return Map.job ~= nil or #Map.queue > 0
    end

    function Map.finish(ok, quiet)
        local job = Map.job
        Map.job = nil
        if not job then return end
        local _, _, root = localParts()
        local stay = ok and job.stay and job.stay()
        if root and job.home and not stay and flag("tp_return", true) then
            root.CFrame = job.home
            root.AssemblyLinearVelocity = ZERO
        end
        if job.done then Util.guard("map job", job.done, ok, job) end
        if not quiet then
            if ok then say("Got " .. job.name) else say(job.name .. " failed: wrong team, taken or out of reach") end
            Map.nextJob()
        end
    end

    function Map.jobStep(dt, now)
        local job = Map.job
        if not job then return end
        local _, humanoid, root = localParts()
        if not root or not humanoid or humanoid.Health <= 0 then return Map.finish(false) end
        if job.check() then return Map.finish(true) end
        local source = job.source
        if now - job.started > flag("tp_timeout", 3) or not source.part.Parent then
            if job.index < #job.sources then
                job.index = job.index + 1
                startSource(job, now)
                return
            end
            return Map.finish(false)
        end
        local remoteTouch = source.kind == "touch" and Compat.touch ~= nil and flag("tp_touch_remote", false)
        if not remoteTouch then
            if humanoid.SeatPart then humanoid.Sit = false end
            root.CFrame = job.stand
            root.AssemblyLinearVelocity = ZERO
        end
        if source.kind == "touch" then
            if Compat.touch and now >= job.touchAt then
                job.touchAt = now + 0.2
                pcall(Compat.touch, root, source.part, 0)
                pcall(Compat.touch, root, source.part, 1)
            end
        elseif now >= job.invokeAt then
            job.invokeAt = now + 0.75
            Map.interact(source.part)
        end
    end

    function Map.teleport(position)
        local _, humanoid, root = localParts()
        if not root then
            say("You need to be alive")
            return false
        end
        if humanoid and humanoid.SeatPart then humanoid.Sit = false end
        root.AssemblyLinearVelocity = ZERO
        root.CFrame = CFrame.new(position)
        return true
    end

    function Map.gotoPlace(name)
        local position = anchorOf(Map.PLACES, name)
        if position and Map.teleport(position) then say("Teleported to " .. name) end
    end

    function Map.switchTeam(name)
        local remote = Game.remote("Remotes.RequestTeamChange")
        local team
        local ok, teams = pcall(function() return game:GetService("Teams"):GetTeams() end)
        for _, candidate in ipairs(ok and teams or {}) do
            if candidate.Name == name then team = candidate end
        end
        if not remote or not team then
            say("Team switch unavailable: " .. (remote and "team not found" or "remote not found"))
            return false
        end
        task.spawn(function()
            local sent, result = pcall(function() return remote:InvokeServer(team, 1) end)
            if not sent or result == false then say("The server refused the switch to " .. name) end
        end)
        return true
    end

    local function carFolder()
        return Workspace:FindFirstChild("CarContainer")
    end

    local function carOf(part)
        local folder = carFolder()
        local node = part
        while folder and node and node.Parent and node.Parent ~= folder do node = node.Parent end
        if folder and node and node.Parent == folder then return node end
        return nil
    end

    local function seatOf(car)
        for _, object in ipairs(car:GetDescendants()) do
            if object:IsA("VehicleSeat") then return object end
        end
        return nil
    end

    local function getPivot(car, seat)
        local ok, pivot = pcall(function() return car:GetPivot() end)
        if ok and pivot then return pivot end
        return seat.CFrame
    end

    local function setPivot(car, seat, cf)
        if not pcall(function() car:PivotTo(cf) end) then seat.CFrame = cf end
    end

    local function owned(part)
        if not Compat.netowner then return true end
        local ok, result = pcall(Compat.netowner, part)
        return ok and result == true
    end

    function Map.pads()
        local items = Workspace:FindFirstChild("Prison_ITEMS")
        local buttons = items and items:FindFirstChild("buttons")
        local pads = {}
        for _, button in ipairs(buttons and buttons:GetChildren() or {}) do
            local pad = button.Name == "Car Spawner" and button:FindFirstChild("Car Spawner")
            if pad and pad:IsA("BasePart") then pads[#pads + 1] = pad end
        end
        return pads
    end

    function Map.pickPad(choice)
        local anchor = anchorOf(Map.PADS, choice)
        if not anchor then
            local root = Game.rootPart()
            anchor = root and root.Position
        end
        if not anchor then return nil end
        local best, bestDistance
        for _, pad in ipairs(Map.pads()) do
            local distance = (pad.Position - anchor).Magnitude
            if not bestDistance or distance < bestDistance then best, bestDistance = pad, distance end
        end
        return best
    end

    function Map.sitIn(car)
        local seat = car and seatOf(car)
        local _, humanoid, root = localParts()
        if not seat or not root then return false end
        root.CFrame = CFrame.new(seat.Position + LIFT)
        pcall(function() seat:Sit(humanoid) end)
        return true
    end

    function Map.spawnCar()
        if Map.job then return say("Busy, wait a moment") end
        local folder = carFolder()
        local pad = Map.pickPad(flag("car_pad", "Nearest"))
        if not pad or not folder then return say("Car spawner not found") end
        local before = {}
        for _, car in ipairs(folder:GetChildren()) do before[car] = true end
        local job = { name = "car", sources = { { part = pad, kind = "interact" } } }
        job.check = function()
            for _, car in ipairs(folder:GetChildren()) do
                if not before[car] and seatOf(car) then
                    job.car = car
                    return true
                end
            end
            return false
        end
        job.stay = function() return flag("car_sit", true) end
        job.done = function(ok) if ok and flag("car_sit", true) then Map.sitIn(job.car) end end
        return Map.begin(job)
    end

    local function restoreSeat(seat, saved)
        if not seat.Parent then return end
        for key, value in pairs(saved) do assign(seat, key, value) end
    end

    function Map.restoreSeats()
        for seat, saved in pairs(Map.seats) do restoreSeat(seat, saved) end
        Map.seats, Map.seatCache = {}, nil
    end

    function Map.carSeats(seat)
        local car = carOf(seat) or seat.Parent
        local cache = Map.seatCache
        if cache and cache.car == car and cache.seat == seat and clock() < cache.until_ then return cache.list end
        local list = { seat }
        for _, object in ipairs(car and car:GetDescendants() or {}) do
            if object ~= seat and object:IsA("VehicleSeat") then list[#list + 1] = object end
        end
        Map.seatCache = { car = car, seat = seat, list = list, until_ = clock() + 1 }
        return list
    end

    local function number(object, key)
        local ok, value = pcall(function() return object[key] end)
        return ok and tonumber(value) or nil
    end

    function Map.driveAssist(seat, dt, speedOn, controlOn)
        local throttle, steer = number(seat, "Throttle") or 0, number(seat, "Steer") or 0
        if throttle == 0 and steer == 0 then return end
        local ok, cf, velocity, spin = pcall(function() return seat.CFrame, seat.AssemblyLinearVelocity, seat.AssemblyAngularVelocity end)
        if not ok or not cf or not velocity or not spin then return end
        local look = cf.LookVector * Vector3.new(1, 0, 1)
        if look.Magnitude < 0.01 then return end
        look = look.Unit
        local forward = velocity:Dot(look)
        local step = math.min(dt or 0.016, 0.1)
        if speedOn and throttle ~= 0 then
            local target = flag("veh_speed_value", 120)
            local along = forward * throttle
            if along < target then
                local push = math.min(target - along, math.max(40, target * 0.75) * step)
                pcall(function() seat.AssemblyLinearVelocity = velocity + look * (push * throttle) end)
            end
        end
        if controlOn and steer ~= 0 and math.abs(forward) > 2 then
            local want = -steer * (forward >= 0 and 1 or -1) * 1.1 * flag("car_turn", 1.5)
            if math.abs(spin.Y) < math.abs(want) or spin.Y * want < 0 then
                local y = spin.Y + (want - spin.Y) * math.min(1, 6 * step)
                pcall(function() seat.AssemblyAngularVelocity = Vector3.new(spin.X, y, spin.Z) end)
            end
        end
    end

    function Map.vehicleStep(dt)
        local _, humanoid = localParts()
        local seat = humanoid and humanoid.SeatPart
        if seat and not seat:IsA("VehicleSeat") then seat = nil end
        local speedOn, controlOn = Util.bindOn("veh_speed", "veh_speed_key"), Util.bindOn("car_control", "car_control_key")
        local active = seat and (speedOn or controlOn)
        local wanted = {}
        if active then
            for _, other in ipairs(Map.carSeats(seat)) do wanted[other] = true end
        end
        for other, saved in pairs(Map.seats) do
            if not wanted[other] then
                restoreSeat(other, saved)
                Map.seats[other] = nil
            end
        end
        if not active then
            Map.seatCache = nil
            return
        end
        for other in pairs(wanted) do
            local saved = Map.seats[other]
            if not saved then
                saved = { MaxSpeed = number(other, "MaxSpeed"), Torque = number(other, "Torque"), TurnSpeed = number(other, "TurnSpeed") }
                Map.seats[other] = saved
            end
            if saved.MaxSpeed then assign(other, "MaxSpeed", speedOn and flag("veh_speed_value", 120) or saved.MaxSpeed) end
            if saved.Torque then assign(other, "Torque", controlOn and saved.Torque * flag("car_torque", 2) or saved.Torque) end
            if saved.TurnSpeed then assign(other, "TurnSpeed", controlOn and saved.TurnSpeed * flag("car_turn", 1.5) or saved.TurnSpeed) end
        end
        Map.driveAssist(seat, dt, speedOn, controlOn)
        if controlOn and flag("car_flip", true) then
            local cf = seat.CFrame
            local up = cf and cf.UpVector
            if up and up.Y < 0.1 then
                local car = carOf(seat) or seat
                local look = cf.LookVector * Vector3.new(1, 0, 1)
                if look.Magnitude < 0.01 then look = Vector3.new(0, 0, -1) end
                setPivot(car, seat, CFrame.new(cf.Position + LIFT, cf.Position + LIFT + look.Unit))
            end
        end
    end

    local function unghost(entry)
        for _, saved in ipairs(entry.ghost) do
            if saved.part.Parent then assign(saved.part, "CanCollide", saved.collide) end
        end
        entry.ghost = {}
    end

    function Map.orbitRestore()
        local orbit = Map.orbit
        for car, entry in pairs(orbit.cars) do
            if car.Parent then
                setPivot(car, entry.seat, entry.pivot)
                pcall(function()
                    entry.seat.AssemblyLinearVelocity = ZERO
                    entry.seat.AssemblyAngularVelocity = ZERO
                end)
                unghost(entry)
            end
        end
        orbit.cars, orbit.list, orbit.scanAt = {}, {}, 0
    end

    function Map.orbitCenter()
        if flag("car_orbit_center", "Me") == "Selected player" then
            local target = Map.selectedPlayer()
            local character = target and target.Character
            return character and character:FindFirstChild("HumanoidRootPart")
        end
        return Game.rootPart()
    end

    local function adoptCars()
        local orbit = Map.orbit
        local folder = carFolder()
        local _, humanoid = localParts()
        local mine = humanoid and humanoid.SeatPart and carOf(humanoid.SeatPart)
        local limit = math.floor(flag("car_orbit_max", 8))
        for car, entry in pairs(orbit.cars) do
            if not car.Parent or car == mine then
                if car.Parent then unghost(entry) end
                orbit.cars[car] = nil
            end
        end
        local count = 0
        for _ in pairs(orbit.cars) do count = count + 1 end
        for _, car in ipairs(folder and folder:GetChildren() or {}) do
            if count >= limit then break end
            local seat = not orbit.cars[car] and car ~= mine and seatOf(car)
            if seat and owned(seat) then
                local entry = { car = car, seat = seat, pivot = getPivot(car, seat), ghost = {} }
                if flag("car_orbit_ghost", true) then
                    for _, part in ipairs(car:GetDescendants()) do
                        if part:IsA("BasePart") and not part.Anchored then
                            entry.ghost[#entry.ghost + 1] = { part = part, collide = part.CanCollide }
                            assign(part, "CanCollide", false)
                        end
                    end
                end
                orbit.cars[car] = entry
                count = count + 1
            end
        end
        local ordered = {}
        for _, entry in pairs(orbit.cars) do ordered[#ordered + 1] = entry end
        table.sort(ordered, function(a, b) return a.car.Name .. tostring(a.car) < b.car.Name .. tostring(b.car) end)
        orbit.list = ordered
    end

    function Map.orbitStep(dt, now)
        local orbit = Map.orbit
        if not Util.bindOn("car_orbit", "car_orbit_key") then
            if next(orbit.cars) then Map.orbitRestore() end
            return
        end
        local center = Map.orbitCenter()
        if not center then return end
        if now >= orbit.scanAt then
            orbit.scanAt = now + 0.5
            adoptCars()
        end
        local count = #orbit.list
        if count == 0 then return end
        orbit.angle = (orbit.angle + dt * flag("car_orbit_speed", 0.5) * TAU) % TAU
        local alpha = 1 - math.exp(-dt * flag("car_orbit_smooth", 8))
        local radius, height = flag("car_orbit_radius", 15), flag("car_orbit_height", 4)
        local middle = center.Position
        for index, entry in ipairs(orbit.list) do
            if entry.car.Parent then
                local phase = orbit.angle + (index - 1) * TAU / count
                local goal = middle + Vector3.new(math.cos(phase) * radius, height, math.sin(phase) * radius)
                local current = entry.at or getPivot(entry.car, entry.seat).Position
                local position = current + (goal - current) * alpha
                entry.at = position
                local tangent = Vector3.new(-math.sin(phase), 0, math.cos(phase))
                setPivot(entry.car, entry.seat, CFrame.new(position, position + tangent))
                pcall(function()
                    entry.seat.AssemblyLinearVelocity = ZERO
                    entry.seat.AssemblyAngularVelocity = ZERO
                end)
            end
        end
    end

    local function tagOf(player)
        local tags = { Game.team(player) }
        local relation = Game.relations[player.UserId]
        if relation then tags[#tags + 1] = relation end
        return player.Name .. " (" .. table.concat(tags, ", ") .. ")"
    end

    function Map.selectedPlayer()
        local value = flag("pl_player", nil)
        local player = type(value) == "string" and Map.listed[value] or nil
        if player and player.Parent then return player end
        return nil
    end

    function Map.refreshList(force)
        local current = Map.selectedPlayer()
        local players = {}
        for _, player in ipairs(Players:GetPlayers()) do
            if player ~= LocalPlayer then players[#players + 1] = player end
        end
        table.sort(players, function(a, b) return string.lower(a.Name) < string.lower(b.Name) end)
        local values, listed = {}, {}
        for index, player in ipairs(players) do
            local text = tagOf(player)
            values[index], listed[text] = text, player
        end
        local signature = table.concat(values, "|")
        if signature == Map.listSig and not force then return end
        Map.listSig, Map.listed, Map.names = signature, listed, values
        local option = Options.pl_player
        if not option then return end
        Map.syncing = true
        pcall(function() option:SetValues(values) end)
        local want = current and tagOf(current)
        if want and listed[want] then
            if option.Value ~= want then pcall(function() option:SetValue(want) end) end
        elseif option.Value ~= nil and not listed[option.Value] then
            pcall(function() option:SetValue(nil) end)
        end
        Map.syncing = false
    end

    function Map.onSelect()
        if Map.syncing then return end
        local player = Map.selectedPlayer()
        local option = Options.pl_relation
        if not option then return end
        Map.syncing = true
        pcall(function() option:SetValue(player and Game.relations[player.UserId] or "None") end)
        Map.syncing = false
        Map.infoAt = 0
    end

    function Map.setRelation(value)
        if Map.syncing then return end
        local player = Map.selectedPlayer()
        if not player then return end
        if value == "Friendly" or value == "Priority" then Game.relations[player.UserId] = value else Game.relations[player.UserId] = nil end
        Map.refreshList(true)
    end

    function Map.gotoPlayer()
        local player = Map.selectedPlayer()
        local character = player and player.Character
        local target = character and character:FindFirstChild("HumanoidRootPart")
        if not target then return say("Select a player who is alive first") end
        local cf = target.CFrame
        local position = cf.Position - cf.LookVector * 4
        local _, humanoid, root = localParts()
        if not root then return say("You need to be alive") end
        if humanoid and humanoid.SeatPart then humanoid.Sit = false end
        root.AssemblyLinearVelocity = ZERO
        root.CFrame = CFrame.new(position, cf.Position)
        say("Teleported to " .. player.Name)
    end

    function Map.stopSpectate()
        if not Map.spectating then return end
        Map.spectating = false
        local cam = Game.camera()
        local own = Game.humanoid(Game.localCharacter())
        if cam and own then cam.CameraSubject = own end
    end

    function Map.playersStep(dt, now)
        if now >= Map.listAt then
            Map.listAt = now + 1
            Map.refreshList(false)
        end
        local cam = Game.camera()
        local target = Map.selectedPlayer()
        local targetHumanoid = target and Game.humanoid(target.Character)
        if flag("pl_spectate", false) and targetHumanoid and cam then
            Map.spectating = true
            if cam.CameraSubject ~= targetHumanoid then cam.CameraSubject = targetHumanoid end
        else
            Map.stopSpectate()
        end
        if Map.info and now >= Map.infoAt then
            Map.infoAt = now + 0.25
            local text = "No player selected"
            if target then
                local root = Game.rootPart()
                local theirs = target.Character and target.Character:FindFirstChild("HumanoidRootPart")
                local distance = root and theirs and math.floor((theirs.Position - root.Position).Magnitude) or nil
                text = string.format("%s | %s | %s hp | %s", target.Name, Game.team(target), targetHumanoid and math.floor(targetHumanoid.Health) or 0, distance and (distance .. " studs") or "no body")
            end
            if text ~= Map.infoText then
                Map.infoText = text
                Map.info:SetText(text)
            end
        end
    end

    local function httpGet(url)
        local send, problem = Compat.request, nil
        if send then
            local ok, reply = pcall(send, { Url = url, Method = "GET", Headers = { Accept = "application/json" } })
            if ok and type(reply) == "table" and type(reply.Body) == "string" then
                local code = tonumber(reply.StatusCode)
                if code == 200 or (code == nil and reply.Success ~= false) then return reply.Body end
                problem = "HTTP " .. tostring(reply.StatusCode)
            else
                problem = ok and "empty reply" or tostring(reply)
            end
        end
        local ok, body = pcall(function() return game:HttpGet(url) end)
        if ok and type(body) == "string" and body ~= "" then return body end
        return nil, problem or (ok and "empty reply" or tostring(body))
    end

    function Map.serverUrl(cursor)
        return "https://games.roblox.com/v1/games/" .. tostring(game.PlaceId) .. "/servers/Public?sortOrder=Asc&excludeFullGames=true&limit=100" .. (cursor and ("&cursor=" .. string.gsub(cursor, "[^%w%-_%.~]", function(c) return string.format("%%%02X", string.byte(c)) end)) or "")
    end

    function Map.servers()
        local found, cursor, problem = {}, nil, nil
        local minimum = flag("srv_hop_min", 0)
        local current = game.JobId
        for _ = 1, 5 do
            local body, why = httpGet(Map.serverUrl(cursor))
            if not body then
                problem = why
                break
            end
            local ok, data = pcall(function() return HttpService:JSONDecode(body) end)
            if not ok or type(data) ~= "table" or type(data.data) ~= "table" then
                problem = type(data) == "table" and type(data.errors) == "table" and type(data.errors[1]) == "table" and tostring(data.errors[1].message) or "bad server list"
                break
            end
            for _, server in ipairs(data.data) do
                if type(server) == "table" and type(server.id) == "string" and server.id ~= current then
                    local playing, most = tonumber(server.playing) or 0, tonumber(server.maxPlayers)
                    if most and playing < most and playing >= minimum then
                        found[#found + 1] = { id = server.id, playing = playing, maxPlayers = most }
                    end
                end
            end
            cursor = type(data.nextPageCursor) == "string" and data.nextPageCursor ~= "" and data.nextPageCursor or nil
            if not cursor then break end
        end
        return found, (#found == 0) and problem or nil
    end

    local function teleportService()
        local ok, service = pcall(function() return game:GetService("TeleportService") end)
        return ok and service or nil
    end

    Map.HOP_FETCHES, Map.HOP_TRIES, Map.HOP_WAIT, Map.HOP_SLOW = 3, 3, 12, 45

    function Map.hopOrder(servers)
        local mode = flag("srv_hop_mode", "Random")
        if mode == "Fewest players" then
            table.sort(servers, function(a, b) return a.playing < b.playing end)
        elseif mode == "Most players" then
            table.sort(servers, function(a, b) return a.playing > b.playing end)
        else
            for index = #servers, 2, -1 do
                local other = math.random(1, index)
                servers[index], servers[other] = servers[other], servers[index]
            end
        end
        return servers
    end

    function Map.hopEnd(text)
        Map.hopping, Map.hopState = false, nil
        if text then say(text) end
    end

    function Map.hopNext(state, reason)
        if Map.hopState ~= state then return end
        if reason then say("Teleport failed: " .. reason) end
        state.tries = state.tries + 1
        local pick = table.remove(state.servers, 1)
        if not pick or state.tries > Map.HOP_TRIES then return Map.hopEnd("Server hop gave up after " .. (state.tries - 1) .. " tries") end
        state.pick = pick
        say(string.format("Joining a server with %d/%d players", pick.playing, pick.maxPlayers))
        local ok, problem = pcall(function() state.service:TeleportToPlaceInstance(game.PlaceId, pick.id, LocalPlayer) end)
        if not ok then return Map.hopNext(state, tostring(problem)) end
        task.delay(Map.HOP_WAIT, function()
            if Map.hopState ~= state or state.pick ~= pick then return end
            if LocalPlayer.Parent == nil then return end
            say("Still teleporting...")
            task.delay(Map.HOP_SLOW - Map.HOP_WAIT, function()
                if Map.hopState == state and state.pick == pick and LocalPlayer.Parent ~= nil then Map.hopNext(state, "no response, trying another server") end
            end)
        end)
    end

    function Map.hopFetch(state)
        if Map.hopState ~= state then return end
        state.fetches = state.fetches + 1
        local servers, problem = Map.servers()
        if #servers > 0 then
            state.servers = Map.hopOrder(servers)
            return Map.hopNext(state)
        end
        if problem and state.fetches < Map.HOP_FETCHES then
            say("Server list failed (" .. problem .. "), retrying")
            task.delay(2 * state.fetches, function() task.spawn(Map.hopFetch, state) end)
            return
        end
        Map.hopEnd(problem and ("Server list failed: " .. problem) or "No other server found, try a lower minimum")
    end

    function Map.hop()
        if Map.hopping then return end
        local service = teleportService()
        if not service then return say("TeleportService unavailable") end
        Map.hopping = true
        local state = { service = service, fetches = 0, tries = 0 }
        Map.hopState = state
        say("Looking for a server...")
        task.spawn(Map.hopFetch, state)
    end

    function Map.rejoin()
        if Map.hopping then return end
        local service = teleportService()
        if not service then return say("TeleportService unavailable") end
        Map.hopping = true
        say("Rejoining...")
        local ok, problem = pcall(function()
            if #Players:GetPlayers() <= 1 then
                service:Teleport(game.PlaceId, LocalPlayer)
            else
                service:TeleportToPlaceInstance(game.PlaceId, game.JobId, LocalPlayer)
            end
        end)
        if not ok then
            Map.hopping = false
            say("Rejoin failed: " .. tostring(problem))
        end
    end

    do
        local service = teleportService()
        local failed = service and service.TeleportInitFailed
        if failed then
            pcall(function()
                Util.track(failed:Connect(function(player, result, message)
                    if player ~= nil and player ~= LocalPlayer then return end
                    local reason = tostring((message ~= nil and message ~= "") and message or result)
                    if Map.hopState then return Map.hopNext(Map.hopState, reason) end
                    Map.hopping = false
                    say("Teleport failed: " .. reason)
                end))
            end)
        end
    end

    Util.track(Players.PlayerAdded:Connect(function() task.defer(Map.refreshList, false) end))
    Util.track(Players.PlayerRemoving:Connect(function() task.defer(Map.refreshList, false) end))

    local function buildKeycard()
        local tools = ReplicatedStorage:FindFirstChild("Tools")
        local template = tools and tools:FindFirstChild(Map.KEYCARD)
        if template and template:IsA("Tool") then
            local ok, card = pcall(function() return template:Clone() end)
            if ok and card then return card end
        end
        local card = Instance.new("Tool")
        card.RequiresHandle = true
        card.CanBeDropped = false
        local handle = Instance.new("Part")
        handle.Name = "Handle"
        handle.Size = Vector3.new(0.2, 0.8, 1.2)
        handle.CanCollide = false
        handle.Massless = true
        handle.Parent = card
        return card
    end

    function Map.giveKeycard(quiet)
        local pack = LocalPlayer:FindFirstChildOfClass("Backpack")
        if not pack then
            if not quiet then say("Backpack not found, wait for your character") end
            return nil
        end
        if Map.findTool(Map.KEYCARD) then
            if not quiet then say("You already have a key card") end
            return nil
        end
        local card = buildKeycard()
        card.Name = Map.KEYCARD
        card.Parent = pack
        Map.cards[#Map.cards + 1] = card
        if not quiet then say("Key card added on your side only; hold it and walk into a door") end
        return card
    end

    function Map.dropKeycards()
        for _, card in ipairs(Map.cards) do pcall(function() card:Destroy() end) end
        Map.cards = {}
    end

    function Map.keyStep(now)
        if now < Map.keyAt or not flag("tp_key_keep", false) then return end
        Map.keyAt = now + 0.5
        local kept = {}
        for _, card in ipairs(Map.cards) do
            if card.Parent then kept[#kept + 1] = card end
        end
        Map.cards = kept
        local _, humanoid = localParts()
        if humanoid and humanoid.Health > 0 and not Map.findTool(Map.KEYCARD) then Map.giveKeycard(true) end
    end

    function Map.foodTool()
        local character = Game.localCharacter()
        local pack = LocalPlayer:FindFirstChildOfClass("Backpack")
        for _, holder in ipairs({ character or false, pack or false }) do
            for _, tool in ipairs(holder and holder:GetChildren() or {}) do
                if tool:IsA("Tool") and Map.FOODS[tool.Name] then
                    local left = tool:GetAttribute("Quantity")
                    if left == nil or left > 0 then return tool end
                end
            end
        end
        return nil
    end

    function Map.eat()
        local remote = Game.remote("Remotes.EatFood")
        if not remote then return false end
        task.spawn(function() pcall(function() remote:FireServer() end) end)
        return true
    end

    function Map.foodStep(now)
        local food = Map.food
        local character, humanoid = localParts()
        if not Util.bindOn("food_auto", "food_auto_key") or not humanoid or humanoid.Health <= 0 then
            food.phase = nil
            return
        end
        if food.phase == "equip" then
            if food.tool.Parent ~= character then
                if now > food.at + 1 then food.phase, food.nextAt = nil, now + 1 end
                return
            end
            if now < food.at then return end
            Map.eat()
            food.phase, food.at, food.nextAt = "back", now + 0.5, now + 3.2
            return
        end
        if food.phase == "back" then
            if now < food.at then return end
            food.phase = nil
            local prev = food.prev
            if prev and prev.Parent and prev.Parent ~= character and food.tool.Parent == character then
                pcall(function() humanoid:EquipTool(prev) end)
            end
            return
        end
        local most = humanoid.MaxHealth > 0 and humanoid.MaxHealth or 100
        if now < food.nextAt or humanoid.Health / most * 100 >= flag("food_health", 50) then return end
        local tool = Map.foodTool()
        if not tool then
            if now >= food.warnAt then
                food.warnAt = now + 15
                say("Auto eat: no food left, use Get food")
            end
            return
        end
        local held = character:FindFirstChildOfClass("Tool")
        food.tool, food.prev, food.phase, food.at = tool, held ~= tool and held or nil, "equip", now + 0.15
        if tool.Parent ~= character then pcall(function() humanoid:EquipTool(tool) end) end
    end

    function Map.itemsStep(dt, now)
        Map.keyStep(now)
        Map.foodStep(now)
    end

    local DOOR_OPEN = { "Exploded", "ScheduledOpen", "PlayerOpened", "LocalPlayerOpened" }

    local function doorOpen(model)
        for _, key in ipairs(DOOR_OPEN) do
            if model:GetAttribute(key) then return true end
        end
        return false
    end

    local function addDoor(found, model, cell)
        if found[model] then return end
        local entry = Map.doorIndex[model]
        local block = cell and model or model:FindFirstChild("block") or (entry and entry.block)
        if not block then return end
        if not entry then
            entry = { model = model, cell = cell, held = false, forced = false, ghost = false, collide = {} }
            Map.doorIndex[model] = entry
        end
        local parts = {}
        for _, object in ipairs(block:GetDescendants()) do
            if object:IsA("BasePart") then parts[#parts + 1] = object end
        end
        local anchor = block:FindFirstChild("hitbox") or parts[1]
        entry.block, entry.parts, entry.ghost = block, parts, nil
        if anchor then entry.pos = anchor.Position end
        if not cell then Map.doorBlocks[block] = true end
        found[model] = entry
    end

    function Map.doorSettle(entry)
        if entry.cell or not entry.block then return end
        local want = not doorOpen(entry.model) and entry.model or nil
        if entry.block.Parent ~= want then pcall(function() entry.block.Parent = want end) end
    end

    function Map.doorHold(entry)
        if entry.cell or not entry.block then return end
        local model = entry.model
        if not entry.held then entry.held, entry.saved = true, model:GetAttribute("LocalPlayerOpened") end
        if model:GetAttribute("LocalPlayerOpened") ~= true then pcall(function() model:SetAttribute("LocalPlayerOpened", true) end) end
        if entry.block.Parent ~= nil then pcall(function() entry.block.Parent = nil end) end
    end

    function Map.doorRelease(entry)
        if not entry.held then return end
        entry.held = false
        pcall(function() entry.model:SetAttribute("LocalPlayerOpened", entry.saved) end)
        entry.saved = nil
        Map.doorSettle(entry)
    end

    function Map.doorClose(entry)
        Map.doorRelease(entry)
        if entry.cell or not entry.block or entry.block.Parent == entry.model then return end
        entry.forced = true
        pcall(function() entry.block.Parent = entry.model end)
    end

    function Map.doorGhost(entry, on)
        if entry.ghost == on then return end
        entry.ghost = on
        if on then
            for _, part in ipairs(entry.parts) do
                if entry.collide[part] == nil then entry.collide[part] = part.CanCollide end
                assign(part, "CanCollide", false)
            end
            return
        end
        for part, collide in pairs(entry.collide) do assign(part, "CanCollide", collide) end
        entry.collide = {}
    end

    function Map.doorRestore(entry)
        Map.doorRelease(entry)
        if entry.forced then
            entry.forced = false
            Map.doorSettle(entry)
        end
        Map.doorGhost(entry, false)
    end

    function Map.scanDoors()
        local found, list = {}, {}
        if CollectionService then
            local ok, tagged = pcall(function() return CollectionService:GetTagged("Door") end)
            for _, model in ipairs(ok and tagged or {}) do addDoor(found, model, false) end
        end
        local folder = Workspace:FindFirstChild("Doors")
        for _, model in ipairs(folder and folder:GetChildren() or {}) do
            if model:IsA("Model") then addDoor(found, model, false) end
        end
        local cells = Workspace:FindFirstChild("CellDoors")
        for _, model in ipairs(cells and cells:GetChildren() or {}) do
            if model:IsA("Model") then addDoor(found, model, true) end
        end
        for model, entry in pairs(Map.doorIndex) do
            if not found[model] then
                Map.doorRestore(entry)
                Map.doorIndex[model] = nil
                Map.doorBlocks[entry.block] = nil
            end
        end
        for _, entry in pairs(found) do list[#list + 1] = entry end
        Map.doors, Map.doorsDirty = list, false
        return list
    end

    function Map.doorStep(dt, now)
        local auto, ghost = flag("door_auto", false), flag("door_nocollide", false)
        if not (Map.doorsAll or auto or ghost or Map.doorsLive) then return end
        if Map.doorsDirty and now >= Map.doorScanAt then
            Map.doorScanAt = now + 0.5
            Map.scanDoors()
        end
        if now < Map.doorTickAt then return end
        Map.doorTickAt = now + 0.1
        local root = Game.rootPart()
        local range = flag("door_range", 12)
        local live = false
        for _, entry in ipairs(Map.doors) do
            if entry.model.Parent then
                if not entry.cell then
                    local near = auto and root and entry.pos and (entry.pos - root.Position).Magnitude <= range
                    if Map.doorsAll or near then Map.doorHold(entry) elseif entry.held then Map.doorRelease(entry) end
                end
                Map.doorGhost(entry, ghost)
                live = live or entry.held or entry.ghost == true
            else
                Map.doorsDirty = true
            end
        end
        Map.doorsLive = live
    end

    function Map.openDoors()
        Map.doorsAll, Map.doorTickAt = true, 0
        Map.doorStep(0, clock())
        say("Opened " .. #Map.doors .. " doors on your screen")
    end

    function Map.closeDoors()
        Map.doorsAll = false
        if Map.doorsDirty then Map.scanDoors() end
        for _, entry in ipairs(Map.doors) do Map.doorClose(entry) end
        Map.doorTickAt = 0
        say("Closed the doors on your screen")
    end

    function Map.restoreDoors()
        Map.doorsAll, Map.doorsLive = false, false
        for _, entry in pairs(Map.doorIndex) do Map.doorRestore(entry) end
    end

    Util.track(Workspace.DescendantAdded:Connect(function(object)
        local name = object.Name
        if (name == "block" and not Map.doorBlocks[object]) or name == "Doors" or name == "CellDoors" then Map.doorsDirty = true end
    end))
    if CollectionService then
        pcall(function()
            Util.track(CollectionService:GetInstanceAddedSignal("Door"):Connect(function() Map.doorsDirty = true end))
        end)
    end

