    local function buildPlayers(page)
        local List, Selected = page["Player list"], page["Selected player"]
        List:Dropdown({ Name = "Player", Flag = "pl_player", Items = {}, Searchable = true, Callback = function() Map.onSelect() end })
        List:Button({ Name = "Refresh", Callback = function() Map.refreshList(true) end })
        Map.info = Selected:Label({ Name = "No player selected" })
