    end

    local teleport = Pages and Pages.Teleport and Pages.Teleport.Main
    if teleport then Util.guard("menu teleport", buildTeleport, teleport) end
    local vehicles = Pages and Pages.Misc and Pages.Misc.Vehicles
    if vehicles then Util.guard("menu vehicles", buildVehicles, vehicles) end
    local players = Pages and Pages.Players and Pages.Players.Main
    if players then Util.guard("menu players", buildPlayers, players) end
    local settings = Pages and Pages.Settings and Pages.Settings.Main
    if settings and settings.Server then Util.guard("menu server", buildServer, settings.Server) end

    Util.map = Map
    local Combat = Util.combat
    if Combat then
        Combat.selectedPlayer, Combat.getWeapon, Combat.gettingWeapon = Map.selectedPlayer, Map.getWeapon, Map.gettingWeapon
