        Map.restoreSeats()
        Map.orbitRestore()
        Map.restoreDoors()
        Map.dropKeycards()
        Map.food.phase = nil
        Map.stopSpectate()
        if Combat and Combat.selectedPlayer == Map.selectedPlayer then
            Combat.selectedPlayer, Combat.getWeapon, Combat.gettingWeapon = nil, nil, nil
        end
        if Util.map == Map then Util.map = nil end
    end)
end
-- pl 80_avatar 1-2417

do
    local HttpService = game:GetService("HttpService")
    local okEditor, AvatarEditorService = pcall(function() return game:GetService("AvatarEditorService") end)
    if not okEditor then AvatarEditorService = nil end

    local Avatar = { busy = false, wornKeys = {}, dynamicHeads = {}, headDynamic = false, Http = {}, store = { recent = {}, favorites = {}, outfits = {} } }
    local Builder = { rig = "R6", desc = nil, stamp = 0, rigSet = false }
    Avatar.Builder = Builder

    local HEADLESS_IDS = { [15093053680] = true, [134082579] = true, [4562128874] = true }
    local KORBLOX_LEFT, KORBLOX_RIGHT = 139607673, 139607718
    local STORE_PATH = "Aster/spoofer.json"

    local function notify(message)
        pcall(function() Library:Notify(message, 4) end)
    end
    Avatar.notify = notify

    local function sender()
        return Compat.request
    end

    function Avatar.Http.get(url, headers)
        local send = sender()
        if send then
            local ok, reply = pcall(send, { Url = url, Method = "GET", Headers = headers })
            if ok and type(reply) == "table" and type(reply.Body) == "string" and reply.Body ~= "" then
                return reply.Body, tonumber(reply.StatusCode)
            end
            if ok and type(reply) == "table" then return nil, tonumber(reply.StatusCode) end
        end
        if headers and headers["Roblox-Place-Id"] then return nil, nil end
        local ok, body = pcall(function() return game:HttpGet(url) end)
        if ok and type(body) == "string" and body ~= "" then return body, nil end
        return nil, tonumber(string.match(tostring(body), "(%d%d%d)")), tostring(body)
    end

    function Avatar.Http.post(url, payload)
        local send = sender()
        if not send then return nil end
        local ok, reply = pcall(send, { Url = url, Method = "POST", Headers = { ["Content-Type"] = "application/json" }, Body = HttpService:JSONEncode(payload) })
        if ok and type(reply) == "table" and type(reply.Body) == "string" then return reply.Body end
        return nil
    end

    local function decode(body)
        if type(body) == "table" then return body end
        if type(body) ~= "string" then return nil end
        local ok, data = pcall(function() return HttpService:JSONDecode(body) end)
        if ok and type(data) == "table" then return data end
        return nil
    end

    local function scaleAccessory(copy, factor)
        if math.abs(factor - 1) < 0.01 then return end
        for _, d in ipairs(copy:GetDescendants()) do
            if d:IsA("BasePart") then
                d.Size = d.Size * factor
            elseif d:IsA("SpecialMesh") then
                d.Scale = d.Scale * factor
            elseif d:IsA("Attachment") then
                d.CFrame = CFrame.new(d.CFrame.Position * factor) * d.CFrame.Rotation
            end
        end
    end

    local function descFactor(isHead)
        local desc = Avatar.currentDesc
        if not desc then return 1 end
        local ok, value = pcall(function()
            if isHead then return desc.HeadScale end
            return (desc.WidthScale + desc.HeightScale + desc.DepthScale) / 3
        end)
        return ok and tonumber(value) or 1
    end

    local function accessoryKey(acc)
        local handle = acc:FindFirstChild("Handle")
        local mesh, texture = "", ""
        if handle then
            pcall(function()
                local special = handle:FindFirstChildWhichIsA("SpecialMesh")
                if special then
                    mesh, texture = tostring(special.MeshId), tostring(special.TextureId)
                elseif handle:IsA("MeshPart") then
                    mesh, texture = tostring(handle.MeshId), tostring(handle.TextureID)
                end
            end)
        end
        return string.lower(acc.Name) .. "|" .. mesh .. "|" .. texture
    end

    local function dedupeAccessories(char)
        local seen, removed = {}, 0
        for _, child in ipairs(char:GetChildren()) do
            if child:IsA("Accessory") then
                local key = accessoryKey(child)
                if seen[key] then
                    pcall(function() child:Destroy() end)
                    removed = removed + 1
                else
                    seen[key] = true
                end
            end
        end
        return removed
    end

    function Avatar.resolveUserId(input)
        if input == nil then return nil end
        local s = tostring(input):gsub("^%s+", ""):gsub("%s+$", "")
        if s == "" then return nil end
        local fromUrl = s:match("users/(%d+)") or s:match("userId=(%d+)")
        if fromUrl then
            local n = tonumber(fromUrl)
            if n and n > 0 then return math.floor(n) end
        end
        local digits = s:gsub(",", ""):match("^(%d+)$")
        if digits then
            local n = tonumber(digits)
            if n and n > 0 then return math.floor(n) end
        end
        local needle = s:gsub("^@", "")
        local lower = needle:lower()
        for _, p in ipairs(Players:GetPlayers()) do
            if p.Name:lower() == lower or p.DisplayName:lower() == lower then return p.UserId end
        end
        for _, p in ipairs(Players:GetPlayers()) do
            if p.Name:lower():sub(1, #lower) == lower or p.DisplayName:lower():sub(1, #lower) == lower then return p.UserId end
        end
        local ok, id = pcall(function() return Players:GetUserIdFromNameAsync(needle) end)
        if ok and type(id) == "number" and id > 0 then return math.floor(id) end
        for _, host in ipairs({ "users.roproxy.com", "users.roblox.com" }) do
            local data = decode(Avatar.Http.post("https://" .. host .. "/v1/usernames/users", { usernames = { needle }, excludeBannedUsers = false }))
            local first = data and type(data.data) == "table" and data.data[1]
            if first and tonumber(first.id) then return math.floor(tonumber(first.id)) end
        end
        for _, host in ipairs({ "users.roproxy.com", "users.roblox.com" }) do
            local data = decode((Avatar.Http.get("https://" .. host .. "/v1/users/search?limit=10&keyword=" .. HttpService:UrlEncode(needle))))
            local list = data and data.data
            if type(list) == "table" and list[1] then
                local pick = list[1]
                for _, entry in ipairs(list) do
                    if type(entry.name) == "string" and entry.name:lower() == lower then pick = entry break end
                end
                if tonumber(pick.id) then return math.floor(tonumber(pick.id)) end
            end
        end
        return nil
    end

    local function stripAppearance(char)
        if not char then return end
        for _, v in ipairs(char:GetChildren()) do
            if v:IsA("Accessory") or v:IsA("Shirt") or v:IsA("Pants") or v:IsA("ShirtGraphic")
                or v:IsA("CharacterMesh") or v:IsA("BodyColors") or v:IsA("Clothing") then
                pcall(function() v:Destroy() end)
            end
        end
        for _, name in ipairs({ "Torso", "Left Arm", "Right Arm", "Left Leg", "Right Leg" }) do
            local limb = char:FindFirstChild(name)
            if limb then
                for _, d in ipairs(limb:GetChildren()) do
                    if d:IsA("SpecialMesh") then pcall(function() d:Destroy() end) end
                end
                limb.Transparency = 0
            end
        end
    end
    Avatar.stripAppearance = stripAppearance

    local function wearAccessory(char, acc, fromAsset)
        if not char or not acc or not acc:IsA("Accessory") then return false end
        local key = accessoryKey(acc)
        if Avatar.wornKeys[key] then return false end
        pcall(function()
            local copy = acc:Clone()
            for _, part in ipairs(copy:GetDescendants()) do
                if part:IsA("BasePart") then
                    part.Anchored = false
                    part.CanCollide = false
                    part.Massless = true
                end
            end
            local handle = copy:FindFirstChild("Handle")
            if not handle then
                copy:Destroy()
                return
            end
            local preset = handle:FindFirstChild("AccessoryWeld")
            if preset and preset:IsA("JointInstance") and not fromAsset then
                local own = preset.Part0 == handle
                local other = own and preset.Part1 or preset.Part0
                local mapped = other and other ~= handle and (char:FindFirstChild(other.Name) or char:FindFirstChild(other.Name, true))
                if mapped then
                    if own then preset.Part1 = mapped else preset.Part0 = mapped end
                    copy.Parent = char
                    Avatar.wornKeys[key] = true
                    return
                end
            end
            local attachment, targetAttachment
            for _, candidate in ipairs(handle:GetChildren()) do
                if candidate:IsA("Attachment") then
                    for _, d in ipairs(char:GetDescendants()) do
                        if d:IsA("Attachment") and d.Name == candidate.Name and not d:IsDescendantOf(copy) then
                            attachment, targetAttachment = candidate, d
                            break
                        end
                    end
                    if attachment then break end
                end
            end
            attachment = attachment or handle:FindFirstChildWhichIsA("Attachment")
            if fromAsset then
                local isHead = targetAttachment ~= nil and targetAttachment.Parent ~= nil and targetAttachment.Parent.Name == "Head"
                scaleAccessory(copy, descFactor(isHead))
            end
            copy.Parent = char
            local weld = Instance.new("Weld")
            weld.Name = "AccessoryWeld"
            weld.Part0 = handle
            if targetAttachment then
                weld.Part1 = targetAttachment.Parent
                weld.C0 = attachment.CFrame
                weld.C1 = targetAttachment.CFrame
            else
                weld.Part1 = char:FindFirstChild("Head") or char:FindFirstChild("Torso")
                    or char:FindFirstChild("UpperTorso") or char:FindFirstChild("HumanoidRootPart")
            end
            weld.Parent = handle
            Avatar.wornKeys[key] = true
        end)
        return Avatar.wornKeys[key] == true
    end

    local function grabAsset(id)
        id = tonumber(id)
        if not id or id <= 0 then return nil end
        local ok, objects = pcall(function() return game:GetObjects("rbxassetid://" .. tostring(id)) end)
        if ok and type(objects) == "table" then return objects end
        return nil
    end

    local function applyCharacterMeshesFromModel(char, model)
        local count = 0
        for _, v in ipairs(char:GetChildren()) do
            if v:IsA("CharacterMesh") then pcall(function() v:Destroy() end) end
        end
        for _, v in ipairs(model:GetChildren()) do
            if v:IsA("CharacterMesh") then
                pcall(function()
                    v:Clone().Parent = char
                    count = count + 1
                end)
            end
        end
        return count
    end

    local function copySpecialMesh(limb, source)
        pcall(function()
            local target = limb:FindFirstChildOfClass("SpecialMesh")
            if not target then
                target = Instance.new("SpecialMesh")
                target.Parent = limb
            end
            target.MeshType = source.MeshType
            target.MeshId = source.MeshId
            target.TextureId = source.TextureId
            target.Scale = source.Scale
        end)
    end

    local function applyR6MeshesFromDescription(char, desc)
        if not desc then return 0 end
        local function wearLimbAsset(assetId, bodyPart, limbName)
            local objects = grabAsset(assetId)
            if not objects then return false end
            local applied = false
            local function meshFrom(source)
                pcall(function()
                    local mesh = source:Clone()
                    pcall(function() mesh.BodyPart = bodyPart end)
                    mesh.Parent = char
                    applied = true
                end)
            end
            local function limbMesh(source)
                local limb = char:FindFirstChild(limbName)
                if limb then
                    copySpecialMesh(limb, source)
                    applied = true
                end
            end
            for _, object in ipairs(objects) do
                if object:IsA("CharacterMesh") then meshFrom(object) end
                if limbName == "Head" and (object:IsA("MeshPart") or object:IsA("FaceControls")) then Avatar.headDynamic = true end
                for _, d in ipairs(object:GetDescendants()) do
                    if limbName == "Head" and (d:IsA("FaceControls") or (d:IsA("MeshPart") and d.Name == "Head")) then Avatar.headDynamic = true end
                    if d:IsA("CharacterMesh") then
                        meshFrom(d)
                    elseif d:IsA("SpecialMesh") then
                        limbMesh(d)
                    elseif d:IsA("Accessory") then
                        if wearAccessory(char, d, true) then applied = true end
                    end
                end
                if object:IsA("SpecialMesh") then limbMesh(object) end
                if object:IsA("Accessory") and wearAccessory(char, object, true) then applied = true end
            end
            return applied
        end
        local limbs = {
            { "Head", "Head", "Head" }, { "Torso", "Torso", "Torso" },
            { "LeftArm", "LeftArm", "Left Arm" }, { "RightArm", "RightArm", "Right Arm" },
            { "LeftLeg", "LeftLeg", "Left Leg" }, { "RightLeg", "RightLeg", "Right Leg" },
        }
        local count = 0
        for _, entry in ipairs(limbs) do
            local assetId = 0
            pcall(function() assetId = tonumber(desc[entry[1]]) or 0 end)
            if assetId > 0 and wearLimbAsset(assetId, Enum.BodyPart[entry[2]], entry[3]) then count = count + 1 end
        end
        local leftId, rightId = 0, 0
        pcall(function() leftId = tonumber(desc.LeftLeg) or 0 end)
        pcall(function() rightId = tonumber(desc.RightLeg) or 0 end)
        if leftId == KORBLOX_LEFT or rightId == KORBLOX_RIGHT then
            if wearLimbAsset(KORBLOX_LEFT, Enum.BodyPart.LeftLeg, "Left Leg") then count = count + 1 end
            if wearLimbAsset(KORBLOX_RIGHT, Enum.BodyPart.RightLeg, "Right Leg") then count = count + 1 end
        end
        return count
    end

    local function copyClothesAndColors(char, model)
        for _, className in ipairs({ "Shirt", "Pants", "ShirtGraphic", "BodyColors" }) do
            local source = model:FindFirstChildOfClass(className)
            if source then pcall(function() source:Clone().Parent = char end) end
        end
        local head, sourceHead = char:FindFirstChild("Head"), model:FindFirstChild("Head")
        if not (head and sourceHead) then return end
        local function clearFaces()
            for _, d in ipairs(head:GetChildren()) do
                if d:IsA("Decal") or d:IsA("Texture") or d:IsA("SurfaceAppearance") then pcall(function() d:Destroy() end) end
            end
        end
        clearFaces()
        if sourceHead:IsA("MeshPart") then
            pcall(function()
                local mesh = head:FindFirstChildOfClass("SpecialMesh")
                if not mesh then
                    mesh = Instance.new("SpecialMesh")
                    mesh.Parent = head
                end
                mesh.MeshType = Enum.MeshType.FileMesh
                mesh.MeshId = sourceHead.MeshId
                local appearance = sourceHead:FindFirstChildOfClass("SurfaceAppearance")
                local texture = appearance and appearance.ColorMap or ""
                mesh.TextureId = texture ~= "" and texture or sourceHead.TextureID
                local native, size = sourceHead.MeshSize, sourceHead.Size
                if native.X > 0 and native.Y > 0 and native.Z > 0 then
                    mesh.Scale = Vector3.new(size.X / native.X, size.Y / native.Y, size.Z / native.Z)
                end
            end)
            task.delay(0.75, clearFaces)
            task.delay(2, clearFaces)
            local watcher = head.ChildAdded:Connect(function(child)
                if child:IsA("Decal") or child:IsA("Texture") then
                    task.defer(function() pcall(function() child:Destroy() end) end)
                end
            end)
            Util.track(watcher)
            task.delay(20, function() watcher:Disconnect() end)
        else
            for _, d in ipairs(sourceHead:GetChildren()) do
                if d:IsA("Decal") then pcall(function() d:Clone().Parent = head end) end
            end
            local sourceMesh = sourceHead:FindFirstChildOfClass("SpecialMesh")
            if sourceMesh then copySpecialMesh(head, sourceMesh) end
        end
    end

    local function copyAccessories(char, model)
        local count = 0
        for _, accessory in ipairs(model:GetChildren()) do
            if accessory:IsA("Accessory") and wearAccessory(char, accessory) then count = count + 1 end
        end
        return count
    end

    local function isHeadlessName(object)
        return string.find(string.lower(object.Name), "headless", 1, true) ~= nil
    end

    local function loadAccessoriesFromDescription(char, desc)
        local count, headless = 0, false
        if not desc then return count, headless end
        local ids = {}
        pcall(function()
            for _, prop in ipairs({ "HatAccessory", "HairAccessory", "FaceAccessory", "NeckAccessory", "ShouldersAccessory", "FrontAccessory", "BackAccessory", "WaistAccessory" }) do
                local value = desc[prop]
                if type(value) == "string" and value ~= "" then
                    for id in string.gmatch(value, "%d+") do table.insert(ids, tonumber(id)) end
                end
            end
            if desc.GetAccessories then
                for _, accessory in ipairs(desc:GetAccessories(true)) do
                    if accessory.AssetId then table.insert(ids, accessory.AssetId) end
                end
            end
        end)
        for _, id in ipairs(ids) do
            if HEADLESS_IDS[id] then headless = true end
            for _, object in ipairs(grabAsset(id) or {}) do
                if object:IsA("Accessory") then
                    if isHeadlessName(object) then headless = true end
                    if wearAccessory(char, object, true) then count = count + 1 end
                else
                    for _, d in ipairs(object:GetDescendants()) do
                        if d:IsA("Accessory") then
                            if isHeadlessName(d) then headless = true end
                            if wearAccessory(char, d, true) then count = count + 1 end
                        elseif d:IsA("CharacterMesh") then
                            pcall(function()
                                d:Clone().Parent = char
                                count = count + 1
                            end)
                        end
                    end
                end
            end
        end
        return count, headless
    end

    local DEFAULT_FACES = { "textures/face.png", "id=144080495", "//144080495", "id=144075659", "//144075659" }

    local function isDefaultFace(decal)
        local ok, texture = pcall(function() return string.lower(tostring(decal.Texture)) end)
        if not ok or texture == "" then return true end
        for _, pattern in ipairs(DEFAULT_FACES) do
            if string.find(texture, pattern, 1, true) then return true end
        end
        return false
    end

    local function headIsTextured(head, model, desc)
        if Avatar.headDynamic then return true end
        local okHead, headId = pcall(function() return tonumber(desc and desc.Head) or 0 end)
        if okHead and headId > 0 and Avatar.dynamicHeads[headId] then return true end
        local sourceHead = model and model:FindFirstChild("Head")
        if sourceHead and (sourceHead:IsA("MeshPart") or sourceHead:FindFirstChildOfClass("FaceControls")) then return true end
        local mesh = head:FindFirstChildOfClass("SpecialMesh")
        local okTexture, texture = pcall(function() return mesh and tostring(mesh.TextureId) or "" end)
        return okTexture and texture ~= ""
    end

    function Avatar.fixFace(char, desc, model)
        local head = char and char:FindFirstChild("Head")
        if not head then return 0 end
        local okFace, faceId = pcall(function() return tonumber(desc and desc.Face) or 0 end)
        faceId = okFace and faceId or 0
        local decals = {}
        for _, d in ipairs(head:GetChildren()) do
            if d:IsA("Decal") and not d:IsA("Texture") then decals[#decals + 1] = d end
        end
        local drop = {}
        if faceId == 0 and headIsTextured(head, model, desc) then
            for _, d in ipairs(decals) do drop[d] = true end
        else
            local real, seen = {}, {}
            for _, d in ipairs(decals) do
                if not isDefaultFace(d) then real[tostring(d.Face)] = true end
            end
            for _, d in ipairs(decals) do
                local side = tostring(d.Face)
                local key = side .. "|" .. tostring(d.Texture)
                if seen[key] or (real[side] and isDefaultFace(d)) then drop[d] = true end
                seen[key] = true
            end
        end
        local removed = 0
        for d in pairs(drop) do
            if pcall(function() d:Destroy() end) then removed = removed + 1 end
        end
        return removed
    end

    local function applyDescription(humanoid, desc)
        local okAsync, async = pcall(function() return humanoid.ApplyDescriptionAsync end)
        if okAsync and type(async) == "function" and pcall(async, humanoid, desc) then return true end
        return (pcall(function() humanoid:ApplyDescription(desc) end))
    end
    Avatar.applyDescription = applyDescription

    local function forceHeadless(char)
        local head = char and char:FindFirstChild("Head")
        if not head then return end
        pcall(function()
            head.Transparency = 1
            for _, d in ipairs(head:GetChildren()) do
                if d:IsA("Decal") or d:IsA("Texture") then d.Transparency = 1 end
            end
        end)
    end

    local modelCache, cacheOrder, inflight = {}, {}, {}
    local fetchTiming
    local function cacheKey(uid, rigType, outfitId)
        return (outfitId and ("o" .. tostring(outfitId)) or ("u" .. tostring(uid))) .. ":" .. tostring(rigType)
    end

    local function rawFetchModel(uid, rigType, outfitId)
        local desc
        local started = os.clock()
        local described, result = pcall(function()
            if outfitId then return Players:GetHumanoidDescriptionFromOutfitId(outfitId) end
            return Players:GetHumanoidDescriptionFromUserIdAsync(uid)
        end)
        if described then desc = result end
        fetchTiming = { description = os.clock() - started }
        if described and desc and Players.CreateHumanoidModelFromDescription then
            local buildStart = os.clock()
            local ok, built = pcall(function() return Players:CreateHumanoidModelFromDescription(desc, rigType) end)
            fetchTiming.model = os.clock() - buildStart
            if ok and built then return built, desc end
        end
        if outfitId then return nil, desc end
        local ok, built = pcall(function() return Players:CreateHumanoidModelFromUserId(uid) end)
        if ok and built then return built, desc end
        ok, built = pcall(function() return Players:CreateHumanoidModelFromUserIdAsync(uid) end)
        if ok and built then return built, desc end
        return nil, desc
    end

    local function fetchModel(uid, rigType, outfitId)
        local key = cacheKey(uid, rigType, outfitId)
        local hit = modelCache[key]
        if not hit and inflight[key] then
            local started = os.clock()
            while inflight[key] and os.clock() - started < 25 do task.wait(0.05) end
            hit = modelCache[key]
        end
        if hit then
            local okClone, copy = pcall(function() return hit.model:Clone() end)
            if okClone and copy then
                fetchTiming = { cached = true }
                return copy, hit.desc
            end
        end
        fetchTiming = nil
        inflight[key] = true
        local okFetch, model, desc = pcall(rawFetchModel, uid, rigType, outfitId)
        inflight[key] = nil
        if not okFetch then return nil, nil end
        if model then
            local okClone, copy = pcall(function() return model:Clone() end)
            if okClone and copy then
                modelCache[key] = { model = copy, desc = desc }
                cacheOrder[#cacheOrder + 1] = key
                while #cacheOrder > 8 do
                    local old = table.remove(cacheOrder, 1)
                    local entry = modelCache[old]
                    modelCache[old] = nil
                    if entry then pcall(function() entry.model:Destroy() end) end
                end
            end
        end
        return model, desc
    end

    local function localHumanoid()
        local char = LocalPlayer.Character
        return char, char and char:FindFirstChildOfClass("Humanoid")
    end

    function Avatar.prefetch(uid, outfitId)
        local _, humanoid = localHumanoid()
        if not humanoid then return end
        local key = cacheKey(uid, humanoid.RigType, outfitId)
        if modelCache[key] or inflight[key] then return end
        local running = 0
        for _ in pairs(inflight) do running = running + 1 end
        if running >= 2 then return end
        task.spawn(function()
            local ok, model = pcall(fetchModel, uid, humanoid.RigType, outfitId)
            if ok and model then pcall(function() model:Destroy() end) end
        end)
    end

    local function isR6(humanoid)
        return humanoid.RigType == Enum.HumanoidRigType.R6
    end

    local function finishApply(char, humanoid, model, desc)
        stripAppearance(char)
        Avatar.wornKeys, Avatar.headDynamic = {}, false
        copyClothesAndColors(char, model)
        local meshCount = applyCharacterMeshesFromModel(char, model)
        if desc and isR6(humanoid) then meshCount = meshCount + applyR6MeshesFromDescription(char, desc) end
        Avatar.fixFace(char, desc, model)
        copyAccessories(char, model)
        local headless = false
        if desc then
            local _, isHeadless = loadAccessoriesFromDescription(char, desc)
            headless = isHeadless
        end
        if not headless then
            for _, child in ipairs(char:GetChildren()) do
                if child:IsA("Accessory") and isHeadlessName(child) then
                    headless = true
                    break
                end
            end
        end
        if headless then forceHeadless(char) end
        dedupeAccessories(char)
        local accessoryCount = 0
        for _, child in ipairs(char:GetChildren()) do
            if child:IsA("Accessory") then accessoryCount = accessoryCount + 1 end
        end
        pcall(function() model:Destroy() end)
        Avatar.applied = { meshes = meshCount, accessories = accessoryCount, headless = headless }
        notify(string.format("Avatar applied (meshes %d, accessories %d%s)", meshCount, accessoryCount, headless and ", headless" or ""))
        return true
    end

    local function applyAvatar(rawInput, outfitId)
        local char, humanoid = localHumanoid()
        if not humanoid then
            notify("Avatar changer: no character yet")
            return false
        end
        local raw = outfitId and "outfit" or tostring(rawInput or ""):gsub("^%s+", ""):gsub("%s+$", "")
        if raw == "" then
            notify("Avatar changer: type a UserId, username or profile URL first")
            return false
        end
        local uid = outfitId and 0 or Avatar.resolveUserId(raw)
        if not uid then
            notify("Avatar changer: could not find user " .. raw)
            return false
        end
        stripAppearance(char)
        Avatar.wornKeys = {}
        notify("Avatar changer: fetching " .. tostring(uid) .. "...")
        Avatar.lastUid, Avatar.lastOutfit, Avatar.lastBuilt = (not outfitId) and uid or nil, outfitId, nil
        local fetchStart = os.clock()
        local model, desc = fetchModel(uid, humanoid.RigType, outfitId)
        Avatar.currentDesc = desc
        if fetchTiming and fetchTiming.cached then
            notify("Avatar changer: loaded from cache")
        elseif fetchTiming then
            notify(string.format("Avatar changer: fetched in %.1fs (description %.1fs, model %.1fs)", os.clock() - fetchStart, fetchTiming.description or 0, fetchTiming.model or 0))
        end
        if not model then
            if desc then
                Avatar.headDynamic = false
                applyDescription(humanoid, desc)
                if isR6(humanoid) then applyR6MeshesFromDescription(char, desc) end
                Avatar.fixFace(char, desc, nil)
                dedupeAccessories(char)
                notify("Avatar changer: applied the description only (no model)")
                return true
            end
            notify("Avatar changer: could not fetch that avatar")
            return false
        end
        return finishApply(char, humanoid, model, desc)
    end

    local function locked(label, fn, ...)
        if Avatar.busy then
            notify(label .. ": still working on the last one")
            return false
        end
        Avatar.busy = true
        local ok, result = pcall(fn, ...)
        Avatar.busy = false
        if not ok then
            warn("[Aster] " .. label .. " failed:", result)
            notify(label .. " failed, see the console")
            return false
        end
        return result
    end

    function Avatar.applyUser(raw) return locked("Avatar changer", applyAvatar, raw) end
    function Avatar.applyOutfit(outfitId) return locked("Avatar changer", applyAvatar, nil, outfitId) end
    function Avatar.reset()
        if Avatar.applyUser(tostring(LocalPlayer.UserId)) then Avatar.lastUid, Avatar.lastOutfit, Avatar.lastBuilt = nil, nil, nil end
    end

    local function applyBuiltDescription(desc)
        local char, humanoid = localHumanoid()
        if not humanoid then
            notify("Avatar builder: no character yet")
            return false
        end
        local okModel, model = pcall(function() return Players:CreateHumanoidModelFromDescription(desc, humanoid.RigType) end)
        if not okModel or not model then
            notify("Avatar builder: could not build that avatar")
            return false
        end
        local okClone, copy = pcall(function() return desc:Clone() end)
        Avatar.lastUid, Avatar.lastOutfit, Avatar.lastBuilt = nil, nil, okClone and copy or desc
        Avatar.currentDesc = desc
        stripAppearance(char)
        Avatar.wornKeys = {}
        return finishApply(char, humanoid, model, desc)
    end

    function Avatar.applyBuilt(desc) return locked("Avatar builder", applyBuiltDescription, desc) end

    local store = Avatar.store
    do
        local ok, data = pcall(function()
            if isfile and readfile and isfile(STORE_PATH) then return HttpService:JSONDecode(readfile(STORE_PATH)) end
        end)
        if ok and type(data) == "table" then
            if type(data.recent) == "table" then store.recent = data.recent end
            if type(data.favorites) == "table" then store.favorites = data.favorites end
            if type(data.outfits) == "table" then store.outfits = data.outfits end
            if data.reapply ~= nil then store.reapply = data.reapply end
            if type(data.proxy) == "string" then store.proxy = data.proxy end
        end
    end

    function Avatar.save()
        if not writefile then return end
        pcall(function()
            if makefolder and isfolder and not isfolder("Aster") then makefolder("Aster") end
            writefile(STORE_PATH, HttpService:JSONEncode(store))
        end)
    end

    function Avatar.favoriteIndex(info)
        for index, entry in ipairs(store.favorites) do
            if entry.kind == info.kind and ((info.kind == "outfit" and entry.id == info.id) or (info.kind ~= "outfit" and entry.uid == info.uid)) then
                return index
            end
        end
        return nil
    end

    function Avatar.toggleFavorite(info)
        local index = Avatar.favoriteIndex(info)
        if index then
            table.remove(store.favorites, index)
        else
            table.insert(store.favorites, { kind = info.kind, id = info.id, uid = info.uid, name = info.name })
        end
        Avatar.save()
        return index == nil
    end

    function Avatar.recordRecent(uid, name)
        for index = #store.recent, 1, -1 do
            if store.recent[index].uid == uid then table.remove(store.recent, index) end
        end
        table.insert(store.recent, 1, { uid = uid, name = name })
        while #store.recent > 15 do table.remove(store.recent) end
        Avatar.save()
    end

    function Avatar.removeRecent(uid)
        for index = #store.recent, 1, -1 do
            if store.recent[index].uid == uid then table.remove(store.recent, index) end
        end
        Avatar.save()
    end

    local PROXY_HOSTS = { "roproxy.com", "rprxy.xyz" }
    local BROWSER_UA = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36"
    local workingKey

    local function candidatesFor(url)
        local list, seen, hosts = {}, {}, {}
        local custom = string.gsub(string.gsub(tostring(store.proxy or ""), "^%s*https?://", ""), "[/%s]+$", "")
        if custom ~= "" then hosts[#hosts + 1] = custom end
        for _, host in ipairs(PROXY_HOSTS) do hosts[#hosts + 1] = host end
        for _, host in ipairs(hosts) do
            if not seen[host] then
                seen[host] = true
                list[#list + 1] = { key = host, url = (string.gsub(url, "roblox%.com", host)) }
            end
        end
        list[#list + 1] = { key = "roblox.com (no game headers)", url = url, override = true }
        list[#list + 1] = { key = "roblox.com", url = url }
        if workingKey then
            for index, entry in ipairs(list) do
                if entry.key == workingKey then
                    table.remove(list, index)
                    table.insert(list, 1, entry)
                    break
                end
            end
        end
        return list
    end

    function Avatar.httpJson(url)
        local lastStatus, lastMessage
        local attempts = {}
        for _, candidate in ipairs(candidatesFor(url)) do
            local headers = { ["User-Agent"] = BROWSER_UA, ["Accept"] = "application/json" }
            if candidate.override then
                headers["Roblox-Place-Id"] = "0"
                headers["Roblox-Game-Id"] = "0"
                headers["Roblox-Session-Id"] = ""
            end
            local body, status, note = Avatar.Http.get(candidate.url, headers)
            local data = decode(body)
            if data then
                if data.errors then
                    local first = data.errors[1]
                    local text = first and first.message or "error"
                    note, lastStatus, lastMessage = text, status or 400, text
                    local denied = string.find(string.lower(tostring(text)), "denied", 1, true) ~= nil
                    if lastStatus == 429 then
                        return nil, 429, text
                    elseif lastStatus >= 400 and lastStatus < 500 and lastStatus ~= 403 and lastStatus ~= 401 and not denied then
                        return nil, lastStatus, text
                    end
                else
                    workingKey = candidate.key
                    return data, status
                end
            end
            attempts[#attempts + 1] = candidate.key .. ":" .. tostring(status or "no reply") .. (note and (" (" .. string.sub(tostring(note), 1, 60) .. ")") or "")
            lastStatus = status or lastStatus
        end
        return nil, lastStatus, (lastMessage and (lastMessage .. " ") or "") .. "[" .. table.concat(attempts, "; ") .. "]"
    end

    local function httpJsonRetry(url, onWait, alive)
        local data, status, message
        for attempt = 1, 8 do
            data, status, message = Avatar.httpJson(url)
            if data then return data, status end
            local limit = (status == 429) and 4 or 2
            local retryable = status == nil or status == 429 or status >= 500
            if not retryable or attempt >= limit or (alive and not alive()) then break end
            local seconds = (status == 429) and ({ 3, 6, 10 })[attempt] or 1.5
            if onWait then onWait(attempt, seconds) end
            task.wait(seconds)
            if alive and not alive() then break end
        end
        return nil, status, message
    end

    function Avatar.fetchOutfits(uid, onChunk, onWait, alive)
        local seen, list = {}, {}
        local function take(entries)
            local fresh = {}
            for _, entry in ipairs(entries or {}) do
                if entry.id and not seen[entry.id] then
                    seen[entry.id] = true
                    local outfit = { id = entry.id, name = tostring(entry.name or entry.id) }
                    list[#list + 1] = outfit
                    fresh[#fresh + 1] = outfit
                end
            end
            if #fresh > 0 and onChunk then onChunk(fresh, #list) end
            return #fresh
        end
        local plainStopped
        for page = 1, 40 do
            if page > 1 then task.wait(1) end
            local data, status = httpJsonRetry(string.format("https://avatar.roblox.com/v1/users/%d/outfits?page=%d&itemsPerPage=50", uid, page), onWait, alive)
            if not data then
                if page > 1 then plainStopped = (status == 429) and "limited" or "error" end
                break
            end
            local added = take(data.data)
            if #(data.data or {}) < 50 or added == 0 then break end
        end
        if #list > 0 then return list, { kind = "public", source = "v1", stopped = plainStopped } end
        local failed, firstStatus, firstMessage, token, stopped = false, nil, nil, nil, nil
        for page = 1, 100 do
            local url = string.format("https://avatar.roblox.com/v2/avatar/users/%d/outfits?outfitType=1&page=1&itemsPerPage=50&isEditable=true", uid)
            if token then url = url .. "&paginationToken=" .. token end
            if page > 1 then task.wait(2) end
            local data, status, message = httpJsonRetry(url, onWait, alive)
            if not data then
                if page == 1 then failed, firstStatus, firstMessage = true, status, message else stopped = (status == 429) and "limited" or "error" end
                break
            end
            local added = take(data.data)
            token = data.paginationToken or data.nextPageCursor or data.nextPageToken
            if type(token) ~= "string" or token == "" or added == 0 then break end
        end
        local source = "v2"
        if (failed and firstStatus ~= 429) or (not failed and #list == 0) then
            source = "v1"
            for page = 1, 40 do
                if page > 1 then task.wait(2) end
                local data, status, message = httpJsonRetry(string.format("https://avatar.roblox.com/v1/users/%d/outfits?page=%d&itemsPerPage=50&isEditable=true", uid, page), onWait, alive)
                if not data then
                    if page == 1 and failed then firstStatus, firstMessage = firstStatus or status, firstMessage or message end
                    break
                end
                failed = false
                local added = take(data.data)
                if #(data.data or {}) < 50 or added == 0 then break end
            end
        end
        if failed and #list == 0 then
            local kind = "unreachable"
            if firstStatus == 401 or firstStatus == 403 or firstStatus == 400 or firstStatus == 404 then kind = "private" end
            if firstStatus == 429 then kind = "limited" end
            return nil, { kind = kind, status = firstStatus, message = firstMessage }
        end
        return list, { kind = #list > 0 and "public" or "empty", source = source, stopped = stopped }
    end

    function Avatar.inventoryVisible(uid, alive)
        local data = httpJsonRetry(string.format("https://inventory.roblox.com/v1/users/%d/can-view-inventory", uid), nil, alive)
        if data and type(data.canView) == "boolean" then return data.canView end
        return nil
    end

    local ACC_SLOTS = {
        Hat = { acc = "Hat" }, HairAccessory = { acc = "Hair" }, FaceAccessory = { acc = "Face" }, NeckAccessory = { acc = "Neck" },
        ShoulderAccessory = { acc = "Shoulder" }, FrontAccessory = { acc = "Front" }, BackAccessory = { acc = "Back" }, WaistAccessory = { acc = "Waist" },
        EyebrowAccessory = { acc = "Eyebrow" }, EyelashAccessory = { acc = "Eyelash" },
        Shirt = { prop = "Shirt" }, Pants = { prop = "Pants" }, TShirt = { prop = "GraphicTShirt" },
        Head = { prop = "Head" }, DynamicHead = { prop = "Head" }, Face = { prop = "Face" }, Torso = { prop = "Torso" },
        RightArm = { prop = "RightArm" }, LeftArm = { prop = "LeftArm" }, LeftLeg = { prop = "LeftLeg" }, RightLeg = { prop = "RightLeg" },
        ClimbAnimation = { prop = "ClimbAnimation" }, FallAnimation = { prop = "FallAnimation" }, IdleAnimation = { prop = "IdleAnimation" },
        JumpAnimation = { prop = "JumpAnimation" }, MoodAnimation = { prop = "MoodAnimation" }, RunAnimation = { prop = "RunAnimation" },
        SwimAnimation = { prop = "SwimAnimation" }, WalkAnimation = { prop = "WalkAnimation" },
    }
    local PROP_ORDER = { "Head", "Face", "Torso", "LeftArm", "RightArm", "LeftLeg", "RightLeg", "Shirt", "Pants", "GraphicTShirt", "IdleAnimation", "WalkAnimation", "RunAnimation", "JumpAnimation", "FallAnimation", "ClimbAnimation", "SwimAnimation", "MoodAnimation" }
    local COLOR_PROPS = { "HeadColor", "TorsoColor", "LeftArmColor", "RightArmColor", "LeftLegColor", "RightLegColor" }
    local SCALE_PROPS = { "HeightScale", "WidthScale", "DepthScale", "HeadScale", "BodyTypeScale", "ProportionScale" }
    Avatar.ACC_SLOTS, Avatar.COLOR_PROPS = ACC_SLOTS, COLOR_PROPS

    local ASSET_BY_VALUE = {}
    pcall(function()
        for _, item in ipairs(Enum.AvatarAssetType:GetEnumItems()) do ASSET_BY_VALUE[item.Value] = item.Name end
    end)
    local function assetTypeName(value)
        if typeof(value) == "EnumItem" then return value.Name end
        if type(value) == "number" then return ASSET_BY_VALUE[value] end
        if type(value) == "string" then return value end
        return nil
    end

    function Avatar.thumbAsset(id)
        return string.format("rbxthumb://type=Asset&id=%d&w=150&h=150", id)
    end

    local function accessoryTypeName(entry)
        local kind = entry.AccessoryType
        if typeof(kind) == "EnumItem" or type(kind) == "table" then return tostring(kind.Name) end
        return tostring(kind)
    end

    function Avatar.wearAsset(id, typeName, onlyAdd)
        local desc = Builder.desc
        local slot = typeName and ACC_SLOTS[typeName]
        if not (desc and slot) then return nil end
        if slot.acc then
            local list = desc:GetAccessories(true)
            for index, entry in ipairs(list) do
                if entry.AssetId == id then
                    if onlyAdd then return true end
                    table.remove(list, index)
                    desc:SetAccessories(list, true)
                    return false
                end
            end
            table.insert(list, { AssetId = id, AccessoryType = Enum.AccessoryType[slot.acc], IsLayered = false })
            desc:SetAccessories(list, true)
            return true
        end
        if typeName == "DynamicHead" then Avatar.dynamicHeads[id] = true end
        if desc[slot.prop] == id then
            if onlyAdd then return true end
            desc[slot.prop] = 0
            return false
        end
        desc[slot.prop] = id
        return true
    end

    function Avatar.wornItems()
        local out = {}
        local desc = Builder.desc
        if not desc then return out end
        local ok, list = pcall(function() return desc:GetAccessories(true) end)
        if ok and type(list) == "table" then
            for _, accessory in ipairs(list) do out[#out + 1] = { id = accessory.AssetId, label = accessoryTypeName(accessory) } end
        end
        for _, prop in ipairs(PROP_ORDER) do
            local okProp, id = pcall(function() return desc[prop] end)
            if okProp and type(id) == "number" and id ~= 0 then out[#out + 1] = { id = id, label = prop, prop = prop } end
        end
        return out
    end

    function Avatar.isWorn(id)
        for _, item in ipairs(Avatar.wornItems()) do
            if item.id == id then return true end
        end
        return false
    end

    function Avatar.removeItem(item)
        local desc = Builder.desc
        if not desc then return end
        if item.prop then
            desc[item.prop] = 0
            return
        end
        local list = desc:GetAccessories(true)
        for index, accessory in ipairs(list) do
            if accessory.AssetId == item.id then
                table.remove(list, index)
                break
            end
        end
        desc:SetAccessories(list, true)
    end

    function Avatar.serialize(desc)
        local out = { acc = {}, props = {}, colors = {}, scales = {} }
        local okAcc, list = pcall(function() return desc:GetAccessories(true) end)
        if okAcc and type(list) == "table" then
            for _, entry in ipairs(list) do
                out.acc[#out.acc + 1] = { id = entry.AssetId, kind = accessoryTypeName(entry), layered = entry.IsLayered == true, order = entry.Order, puff = entry.Puffiness }
            end
        end
        for _, prop in ipairs(PROP_ORDER) do
            local okProp, value = pcall(function() return desc[prop] end)
            if okProp and type(value) == "number" and value ~= 0 then out.props[prop] = value end
        end
        for _, prop in ipairs(COLOR_PROPS) do
            local okColor, color = pcall(function() return desc[prop] end)
            if okColor and typeof(color) == "Color3" then out.colors[prop] = { color.R, color.G, color.B } end
        end
        for _, prop in ipairs(SCALE_PROPS) do
            local okScale, value = pcall(function() return desc[prop] end)
            if okScale and type(value) == "number" then out.scales[prop] = value end
        end
        return out
    end

    function Avatar.deserialize(data)
        local desc = Instance.new("HumanoidDescription")
        for prop, value in pairs(data.props or {}) do pcall(function() desc[prop] = value end) end
        for prop, rgb in pairs(data.colors or {}) do
            if type(rgb) == "table" then pcall(function() desc[prop] = Color3.new(rgb[1], rgb[2], rgb[3]) end) end
        end
        for prop, value in pairs(data.scales or {}) do pcall(function() desc[prop] = value end) end
        local list = {}
        for _, entry in ipairs(data.acc or {}) do
            local okType, accType = pcall(function() return Enum.AccessoryType[entry.kind] end)
            if okType and accType then
                local item = { AssetId = entry.id, AccessoryType = accType, IsLayered = entry.layered == true }
                if entry.layered then item.Order, item.Puffiness = entry.order or 1, entry.puff or 1 end
                list[#list + 1] = item
            end
        end
        pcall(function() desc:SetAccessories(list, true) end)
        return desc
    end

    local CATEGORIES = {
        { "All", {}, nil, false, false }, { "Hats", { "Hat" }, nil, false, true }, { "Hair", { "HairAccessory" }, nil, false, true },
        { "Face acc.", { "FaceAccessory" }, nil, false, true }, { "Neck", { "NeckAccessory" }, nil, false, true },
        { "Shoulder", { "ShoulderAccessory" }, nil, false, true }, { "Front", { "FrontAccessory" }, nil, false, true },
        { "Back", { "BackAccessory" }, nil, false, true }, { "Waist", { "WaistAccessory" }, nil, false, true },
        { "Shirts", { "Shirt" }, nil, false, true }, { "T-Shirts", { "TShirt" }, nil, false, true }, { "Pants", { "Pants" }, nil, false, true },
        { "Heads", { "DynamicHead" }, nil, false, true }, { "Bodies", {}, "BodyParts", true, false },
        { "Animations", {}, "Animations", false, false }, { "Emotes", { "EmoteAnimation" }, nil, true, false },
    }
    do
        local everything = {}
        for _, entry in ipairs(CATEGORIES) do
            if entry[5] then
                for _, name in ipairs(entry[2]) do everything[#everything + 1] = name end
            end
        end
        CATEGORIES[1][2] = everything
    end
    local CATEGORY_NAMES, CATEGORY_BY_NAME = {}, {}
    for index, entry in ipairs(CATEGORIES) do
        CATEGORY_NAMES[index] = entry[1]
        CATEGORY_BY_NAME[entry[1]] = entry
    end
    local KIND_NAMES = { "Any", "Limited", "Roblox", "UGC", "Premium", "Free" }
    local SORTS = {
        { "Relevance", "Relevance", 0 }, { "Most favorited", "MostFavorited", 1 }, { "Best selling", "Bestselling", 2 },
        { "Newest", "RecentlyCreated", 3 }, { "Price low", "PriceLowToHigh", 4 }, { "Price high", "PriceHighToLow", 5 },
    }
    Avatar.CATEGORY_NAMES, Avatar.KIND_NAMES, Avatar.SORTS = CATEGORY_NAMES, KIND_NAMES, SORTS

    local Catalog = { gen = 0, entries = {}, count = 0, F = { keyword = "", types = CATEGORIES[1][2], kind = "Any", sort = "Relevance", sortLabel = "Relevance", catName = "All", onSale = false } }
    Avatar.Catalog = Catalog

    function Avatar.setCategory(name)
        local entry = CATEGORY_BY_NAME[name] or CATEGORIES[1]
        local F = Catalog.F
        F.catName, F.types, F.bundleType, F.robloxOnly = entry[1], entry[2], entry[3], entry[4]
    end

    function Avatar.setSort(label)
        for _, entry in ipairs(SORTS) do
            if entry[1] == label then Catalog.F.sort, Catalog.F.sortLabel = entry[2], entry[1] end
        end
    end

    function Avatar.setPrice(low, high)
        local F = Catalog.F
        low, high = tonumber(low), tonumber(high)
        F.minPrice = low and math.max(0, math.floor(low)) or nil
        F.maxPrice = high and math.max(0, math.floor(high)) or nil
        if F.minPrice and F.maxPrice and F.minPrice > F.maxPrice then F.minPrice, F.maxPrice = F.maxPrice, F.minPrice end
    end

    function Avatar.resetFilters()
        local F = Catalog.F
        Avatar.setCategory("All")
        F.kind, F.sort, F.sortLabel, F.onSale, F.minPrice, F.maxPrice = "Any", "Relevance", "Relevance", false, nil, nil
    end

    function Avatar.filterParts()
        local F, parts = Catalog.F, {}
        if F.catName ~= "All" then parts[#parts + 1] = F.catName end
        if F.kind ~= "Any" then parts[#parts + 1] = F.kind == "Limited" and "Limited (Roblox)" or F.kind end
        if F.minPrice or F.maxPrice then
            parts[#parts + 1] = (F.minPrice and tostring(F.minPrice) or "0") .. "-" .. (F.maxPrice and tostring(F.maxPrice) or "any") .. " R$"
        end
        if F.onSale then parts[#parts + 1] = "on sale" end
        if F.sortLabel ~= "Relevance" then parts[#parts + 1] = F.sortLabel end
        return parts
    end

    local function gameIsR6()
        local _, humanoid = localHumanoid()
        return humanoid ~= nil and isR6(humanoid)
    end
    local function onlyRoblox(F)
        return F.robloxOnly == true or (F.bundleType ~= nil and gameIsR6())
    end

    local function buildParams(F)
        local params = CatalogSearchParams.new()
        params.SearchKeyword = F.keyword or ""
        params.IncludeOffSale = not F.onSale
        pcall(function() params.Limit = 30 end)
        pcall(function() params.SortType = Enum.CatalogSortType[F.sort] end)
        local types = {}
        for _, name in ipairs(F.types) do
            local ok, item = pcall(function() return Enum.AvatarAssetType[name] end)
            if ok and item then types[#types + 1] = item end
        end
        if #types > 0 then params.AssetTypes = types end
        if F.bundleType then pcall(function() params.BundleTypes = { Enum.BundleType[F.bundleType] } end) end
        if onlyRoblox(F) or F.kind == "Roblox" or F.kind == "Limited" then pcall(function() params.CreatorName = "Roblox" end) end
        if F.kind == "Free" then
            pcall(function() params.MaxPrice = 0 end)
        else
            if F.minPrice then pcall(function() params.MinPrice = F.minPrice end) end
            if F.maxPrice then pcall(function() params.MaxPrice = F.maxPrice end) end
        end
        return params
    end

    local function relaxedParams(F)
        local params = CatalogSearchParams.new()
        params.SearchKeyword = F.keyword or ""
        pcall(function() params.SortType = Enum.CatalogSortType[F.sort] end)
        pcall(function() if F.bundleType then params.BundleTypes = { Enum.BundleType[F.bundleType] } end end)
        pcall(function()
            local types = {}
            for _, name in ipairs(F.types) do
                local ok, item = pcall(function() return Enum.AvatarAssetType[name] end)
                if ok and item then types[#types + 1] = item end
            end
            if #types > 0 then params.AssetTypes = types end
        end)
        return params
    end

    function Avatar.normItem(item)
        local id = item.Id or item.id
        if type(id) ~= "number" then return nil end
        local itemType = item.ItemType or item.itemType
        local isBundle = (typeof(itemType) == "EnumItem" and itemType.Name == "Bundle") or itemType == "Bundle"
        local restrictions = item.itemRestrictions or item.ItemRestrictions
        local limited = item.IsLimited == true or item.IsLimitedUnique == true
        if type(restrictions) == "table" then
            for _, restriction in pairs(restrictions) do
                local text = string.lower(tostring(restriction))
                if text == "limited" or text == "limitedunique" then limited = true end
            end
        end
        local creatorRaw = item.CreatorName or item.creatorName or item.Creator or item.creator
        local creator
        if type(creatorRaw) == "table" then creator = creatorRaw.Name or creatorRaw.name else creator = creatorRaw end
        creator = creator ~= nil and tostring(creator) or nil
        local roblox = creator == "Roblox" or creator == "Roblox Corporation" or item.CreatorTargetId == 1 or item.creatorTargetId == 1
        local premium = type(item.PremiumPricing or item.premiumPricing) == "table" or item.IsPremium == true
        if type(restrictions) == "table" then
            for _, restriction in pairs(restrictions) do
                if string.find(string.lower(tostring(restriction)), "premium", 1, true) then premium = true end
            end
        end
        return {
            id = id, name = tostring(item.Name or item.name or id), price = item.Price or item.price or item.lowestPrice,
            assetName = assetTypeName(item.AssetType or item.assetType), creator = creator, limited = limited, roblox = roblox,
            premium = premium, isBundle = isBundle, priceStatus = tostring(item.PriceStatus or item.priceStatus or ""),
        }
    end

    local function passesKind(F, entry)
        if onlyRoblox(F) and not entry.roblox then return false end
        if F.kind == "Limited" then return entry.limited == true and entry.roblox == true end
        if F.kind == "Roblox" then return entry.roblox == true end
        if F.kind == "UGC" then return entry.roblox ~= true end
        if F.kind == "Premium" then return entry.premium == true end
        if F.kind == "Free" then return entry.price == 0 end
        if type(entry.price) == "number" then
            if F.minPrice and entry.price < F.minPrice then return false end
            if F.maxPrice and entry.price > F.maxPrice then return false end
        elseif F.minPrice or F.maxPrice then
            return false
        end
        return true
    end

    local function httpSearch(F, cursor)
        local sort = 0
        for _, entry in ipairs(SORTS) do if entry[2] == F.sort then sort = entry[3] end end
        local url = "https://catalog.roblox.com/v1/search/items/details?Keyword=" .. HttpService:UrlEncode(F.keyword or "") .. "&Limit=30&SortType=" .. sort
        if cursor then url = url .. "&cursor=" .. HttpService:UrlEncode(cursor) end
        if F.kind == "Roblox" or F.kind == "Limited" or onlyRoblox(F) then url = url .. "&CreatorName=Roblox" end
        if F.kind ~= "Free" and F.minPrice then url = url .. "&MinPrice=" .. F.minPrice end
        if F.kind ~= "Free" and F.maxPrice then url = url .. "&MaxPrice=" .. F.maxPrice end
        local data, status, message = Avatar.httpJson(url)
        if not data then
            local alt = string.gsub(url, "^https://catalog%.roblox%.com/v1/", "https://apis.roblox.com/catalog/v1/")
            local firstMessage = message
            data, status, message = Avatar.httpJson(alt)
            message = tostring(firstMessage) .. " || " .. tostring(message)
        end
        if not data then error("catalog request failed (" .. tostring(status) .. ") " .. tostring(message or ""), 0) end
        local wanted
        if #F.types > 0 then
            wanted = {}
            for _, name in ipairs(F.types) do wanted[name] = true end
        end
        local out = {}
        for _, raw in ipairs(data.data or {}) do
            local entry = Avatar.normItem(raw)
            if entry and (not wanted or not entry.assetName or wanted[entry.assetName]) and passesKind(F, entry) and not (F.onSale and entry.price == nil) then
                out[#out + 1] = entry
            end
        end
        return out, data.nextPageCursor
    end

    local function engineSearch(append)
        local F = Catalog.F
        if not AvatarEditorService then error("no AvatarEditorService", 0) end
        if not append then
            local params = buildParams(F)
            local ok, res = pcall(function() return AvatarEditorService:SearchCatalogAsync(params) end)
            if not ok then
                local first = res
                ok, res = pcall(function() return AvatarEditorService:SearchCatalogAsync(relaxedParams(F)) end)
                if not ok then
                    local plain = CatalogSearchParams.new()
                    plain.SearchKeyword = F.keyword or ""
                    local okPlain, resPlain = pcall(function() return AvatarEditorService:SearchCatalogAsync(plain) end)
                    if not okPlain then error(tostring(first) .. " / " .. tostring(res) .. " / " .. tostring(resPlain), 0) end
                    res = resPlain
                end
            end
            Catalog.pages = res
        elseif Catalog.pages then
            Catalog.pages:AdvanceToNextPageAsync()
        end
        if not Catalog.pages then error("no pages", 0) end
        local items = {}
        for _, raw in ipairs(Catalog.pages:GetCurrentPage()) do
            local entry = Avatar.normItem(raw)
            if entry and passesKind(F, entry) then items[#items + 1] = entry end
        end
        Catalog.finished = Catalog.pages.IsFinished == true
        return items
    end

    function Avatar.search(append, onDone)
        if append and (Catalog.busy or Catalog.finished) then return false end
        if not append then
            Catalog.gen = Catalog.gen + 1
            Catalog.pages, Catalog.cursor, Catalog.finished, Catalog.count, Catalog.useWeb = nil, nil, false, 0, false
            Catalog.entries = {}
        end
        local gen = Catalog.gen
        Catalog.busy = true
        task.spawn(function()
            local items
            local okAll, err = pcall(function()
                local okEngine, result = false, nil
                if not Catalog.useWeb then okEngine, result = pcall(engineSearch, append) end
                if okEngine then
                    items = result
                    return
                end
                if not Catalog.useWeb then
                    Catalog.useWeb = true
                    Catalog.engineErr = tostring(result)
                end
                if Catalog.webBlockedUntil and os.clock() < Catalog.webBlockedUntil then error(Catalog.webBlocked .. "  |  in-game search: " .. tostring(Catalog.engineErr), 0) end
                local okWeb, list, nextCursor = pcall(httpSearch, Catalog.F, append and Catalog.cursor or nil)
                if not okWeb then
                    if string.find(string.lower(tostring(list)), "denied", 1, true) then
                        Catalog.webBlockedUntil = os.clock() + 60
                        Catalog.webBlocked = "In-experience search is denied for this place"
                    end
                    error(tostring(list), 0)
                end
                items, Catalog.cursor = list, nextCursor
                Catalog.finished = nextCursor == nil
            end)
            if gen ~= Catalog.gen then return end
            Catalog.busy = false
            if not okAll then
                Catalog.error = tostring(err)
                warn("[Aster] Avatar builder: catalog search failed:", err)
                if onDone then onDone(nil, tostring(err)) end
                return
            end
            Catalog.error = nil
            for _, entry in ipairs(items) do
                Catalog.count = Catalog.count + 1
                Catalog.entries[#Catalog.entries + 1] = entry
            end
            if onDone then onDone(items) end
        end)
        return true
    end

    function Avatar.entryStyle(entry)
        local offSale = string.find(string.lower(entry.priceStatus or ""), "off", 1, true) ~= nil or (entry.price == nil and not entry.limited and not entry.isBundle)
        if entry.isBundle then return Color3.fromRGB(150, 90, 230), "bundle" end
        if offSale then return Color3.fromRGB(226, 70, 70), "off sale" end
        if entry.limited and entry.roblox then return Color3.fromRGB(70, 200, 110), "limited" end
        if entry.roblox then return Color3.fromRGB(70, 110, 235), "roblox" end
        return Color3.fromRGB(170, 170, 170), "ugc"
    end

    local function itemDetails(id, kind)
        if not AvatarEditorService then return nil end
        local ok, info = pcall(function() return AvatarEditorService:GetItemDetails(id, Enum.AvatarItemType[kind]) end)
        if ok and type(info) == "table" then return info end
        return nil
    end

    function Avatar.bundlePieces(bundleId)
        local out = {}
        local details = itemDetails(bundleId, "Bundle")
        if not details then return out end
        for _, piece in ipairs(details.BundledItems or details.bundledItems or {}) do
            local kind = piece.Type or piece.type
            local pieceId = piece.Id or piece.id
            local isAsset = kind == "Asset" or (typeof(kind) == "EnumItem" and kind.Name == "Asset")
            if isAsset and type(pieceId) == "number" then
                local info = itemDetails(pieceId, "Asset")
                local typeName = info and assetTypeName(info.AssetType) or nil
                out[#out + 1] = { id = pieceId, name = tostring(piece.Name or piece.name or (info and info.Name) or pieceId), typeName = typeName, supported = typeName ~= nil and ACC_SLOTS[typeName] ~= nil }
            end
        end
        return out
    end

    Avatar.listeners = {}
    function Avatar.changed()
        for _, fn in ipairs(Avatar.listeners) do Util.guard("avatar ui", fn) end
    end

    function Avatar.typeOf(entry)
        if entry.assetName then return entry.assetName end
        local info = itemDetails(entry.id, "Asset")
        if info then entry.assetName = assetTypeName(info.AssetType) end
        return entry.assetName
    end

    function Avatar.wearPieces(pieces, label)
        local worn = 0
        for _, piece in ipairs(pieces) do
            if piece.supported and pcall(Avatar.wearAsset, piece.id, piece.typeName, true) then worn = worn + 1 end
        end
        notify(worn > 0 and string.format("Avatar builder: wearing %d part(s) of %s", worn, label) or "Avatar builder: nothing selected")
        if worn > 0 then Avatar.changed() end
        return worn
    end

    function Avatar.playEmote(entry)
        local _, humanoid = localHumanoid()
        if not humanoid then return notify("Emotes: no character yet") end
        if Avatar.emoteTrack then
            pcall(function() Avatar.emoteTrack:Stop() end)
            Avatar.emoteTrack = nil
            if Avatar.emoteId == entry.id then
                Avatar.emoteId = nil
                return notify("Emote stopped")
            end
        end
        local ok, success, track = pcall(function() return humanoid:PlayEmoteAndGetAnimTrackById(entry.id) end)
        if ok and success and track then
            Avatar.emoteTrack, Avatar.emoteId = track, entry.id
            notify("Playing " .. entry.name)
            return true
        end
        notify("Emotes: could not play " .. entry.name)
        return false
    end

    function Avatar.equipEmote(entry, slot)
        local desc = Builder.desc
        if not desc then return notify("Avatar builder: still loading your avatar") end
        local function withSlot(target)
            pcall(function() target:AddEmote(entry.name, entry.id) end)
            local list = {}
            local okGet, equipped = pcall(function() return target:GetEquippedEmotes() end)
            if okGet and type(equipped) == "table" then
                for _, item in ipairs(equipped) do
                    if item.Slot ~= slot and item.Name ~= entry.name then list[#list + 1] = { Slot = item.Slot, Name = item.Name } end
                end
            end
            list[#list + 1] = { Slot = slot, Name = entry.name }
            return pcall(function() target:SetEquippedEmotes(list) end)
        end
        withSlot(desc)
        local _, humanoid = localHumanoid()
        if not humanoid then return false end
        local okApplied, applied = pcall(function() return humanoid:GetAppliedDescription() end)
        if not (okApplied and applied) then
            notify("Avatar builder: emote saved in the builder, could not reach the emote wheel")
            return false
        end
        if not withSlot(applied) then
            notify("Avatar builder: emote saved in the builder, the wheel refused it")
            return false
        end
        local okApply = applyDescription(humanoid, applied)
        notify(okApply and string.format("Emote wheel: %s is now in slot %d", entry.name, slot) or "Avatar builder: the wheel refused the emote")
        if okApply and Avatar.lastBuilt then
            task.delay(1.2, function()
                if Avatar.lastBuilt and not Library.Unloaded then
                    local okCopy, copy = pcall(function() return Avatar.lastBuilt:Clone() end)
                    Avatar.applyBuilt(okCopy and copy or Avatar.lastBuilt)
                end
            end)
        end
        return okApply
    end

    function Avatar.activate(entry)
        if not Builder.desc then return notify("Avatar builder: still loading your avatar") end
        local ui = Avatar.ui
        if entry.isBundle and ui and ui.openBundle then return ui.openBundle(entry) end
        if entry.assetName == "EmoteAnimation" then
            if ui and ui.openEmote then return ui.openEmote(entry) end
            return Avatar.playEmote(entry)
        end
        if entry.isBundle then
            local worn = 0
            for _, piece in ipairs(Avatar.bundlePieces(entry.id)) do
                if piece.supported and pcall(Avatar.wearAsset, piece.id, piece.typeName, true) then worn = worn + 1 end
            end
            notify(string.format("Avatar builder: wore %d parts of %s", worn, entry.name))
            if worn > 0 then Avatar.changed() end
            return
        end
        local typeName = Avatar.typeOf(entry)
        if not typeName or not ACC_SLOTS[typeName] then return notify("Avatar builder: " .. entry.name .. " is a type the builder can't wear yet") end
        local ok, result = pcall(Avatar.wearAsset, entry.id, typeName)
        if not ok then
            warn("[Aster] Avatar builder: wearing failed:", result)
            return notify("Avatar builder: could not add that item")
        end
        Avatar.changed()
    end

    function Avatar.defaultRig()
        if Builder.rigSet then return Builder.rig end
        local _, humanoid = localHumanoid()
        if humanoid then
            Builder.rig = isR6(humanoid) and "R6" or "R15"
            Builder.rigSet = true
        end
        return Builder.rig
    end

    function Avatar.setDescription(desc)
        Builder.desc = desc
        Builder.baseColors = {}
        for _, prop in ipairs(COLOR_PROPS) do
            local okColor, color = pcall(function() return desc[prop] end)
            if okColor and typeof(color) == "Color3" then Builder.baseColors[prop] = color end
        end
        Avatar.changed()
    end

    function Avatar.loadMine()
        local desc
        if Avatar.currentDesc then
            local ok, copy = pcall(function() return Avatar.currentDesc:Clone() end)
            if ok then desc = copy end
        end
        if not desc then
            local ok, fetched = pcall(function() return Players:GetHumanoidDescriptionFromUserIdAsync(LocalPlayer.UserId) end)
            if ok and fetched then desc = fetched end
        end
        if not desc then
            local _, humanoid = localHumanoid()
            if humanoid then
                local ok, applied = pcall(function() return humanoid:GetAppliedDescription() end)
                if ok and applied then desc = applied end
            end
        end
        if not desc then
            notify("Avatar builder: could not read your avatar, starting from an empty one")
            desc = Instance.new("HumanoidDescription")
        end
        Avatar.setDescription(desc)
    end

    function Avatar.setColor(prop, color)
        if not Builder.desc then return notify("Avatar builder: still loading your avatar") end
        for _, name in ipairs(prop and { prop } or COLOR_PROPS) do pcall(function() Builder.desc[name] = color end) end
        Avatar.changed()
    end

    function Avatar.resetColors()
        if not (Builder.desc and Builder.baseColors) then return end
        for prop, color in pairs(Builder.baseColors) do pcall(function() Builder.desc[prop] = color end) end
        Avatar.changed()
    end

    function Avatar.saveOutfit(name)
        if not Builder.desc then return notify("Avatar builder: nothing to save yet") end
        local data = Avatar.serialize(Builder.desc)
        if next(data.props) == nil and #data.acc == 0 then return notify("Avatar builder: the builder is empty, wear something first") end
        name = (name and name ~= "") and name or ("Outfit " .. (#store.outfits + 1))
        table.insert(store.outfits, 1, { name = name, rig = Builder.rig, data = data })
        while #store.outfits > 40 do table.remove(store.outfits) end
        Avatar.save()
        notify("Avatar builder: saved " .. name)
        return true
    end

    local function assembleModel(model)
        local root = model:FindFirstChild("HumanoidRootPart") or model.PrimaryPart
        if not root then return end
        local done = { [root] = true }
        local joints = {}
        for _, inst in ipairs(model:GetDescendants()) do
            if inst:IsA("JointInstance") then joints[#joints + 1] = inst end
        end
        local progress, rounds = true, 0
        while progress and rounds < 40 do
            progress, rounds = false, rounds + 1
            for _, joint in ipairs(joints) do
                local p0, p1 = joint.Part0, joint.Part1
                if p0 and p1 then
                    if done[p0] and not done[p1] then
                        p1.CFrame = p0.CFrame * joint.C0 * joint.C1:Inverse()
                        done[p1], progress = true, true
                    elseif done[p1] and not done[p0] then
                        p0.CFrame = p1.CFrame * joint.C1 * joint.C0:Inverse()
                        done[p0], progress = true, true
                    end
                end
            end
        end
    end

    local PALETTE = {
        { 255, 255, 255 }, { 229, 228, 223 }, { 163, 162, 165 }, { 99, 95, 98 }, { 27, 42, 53 }, { 17, 17, 17 },
        { 245, 205, 48 }, { 253, 234, 141 }, { 218, 134, 122 }, { 196, 40, 28 }, { 123, 46, 47 }, { 105, 64, 40 },
        { 205, 164, 120 }, { 234, 184, 146 }, { 204, 142, 105 }, { 240, 213, 160 }, { 124, 92, 70 }, { 91, 64, 45 },
        { 218, 133, 65 }, { 226, 155, 64 }, { 255, 152, 220 }, { 233, 118, 193 }, { 170, 85, 255 }, { 98, 37, 209 },
        { 13, 105, 172 }, { 33, 84, 185 }, { 116, 134, 157 }, { 4, 175, 236 }, { 128, 187, 219 }, { 61, 21, 133 },
        { 40, 127, 71 }, { 75, 151, 75 }, { 161, 196, 140 }, { 52, 142, 64 }, { 0, 143, 156 }, { 18, 238, 212 },
        { 124, 156, 107 }, { 99, 125, 104 }, { 215, 197, 154 }, { 159, 131, 95 }, { 180, 128, 255 }, { 255, 89, 89 },
    }
    local BODY_PARTS = { { "All parts", nil }, { "Head", "HeadColor" }, { "Torso", "TorsoColor" }, { "Left arm", "LeftArmColor" }, { "Right arm", "RightArmColor" }, { "Left leg", "LeftLegColor" }, { "Right leg", "RightLegColor" } }
    local INDICATOR = {
        public = Color3.fromRGB(90, 200, 110), empty = Color3.fromRGB(230, 190, 70), private = Color3.fromRGB(225, 85, 85),
        limited = Color3.fromRGB(230, 150, 60), unreachable = Color3.fromRGB(150, 150, 150), checking = Color3.fromRGB(150, 150, 150),
    }

    local function frameOf(parent)
        if typeof(parent) ~= "Instance" and type(parent) == "table" and parent.Frame then return parent.Frame end
        return parent
    end

    local function area(parent, top, height, bottom)
        local size = height and UDim2.new(1, 0, 0, height) or UDim2.new(1, 0, 1, -(top + (bottom or 0)))
        local position = top >= 0 and UDim2.fromOffset(0, top) or UDim2.new(0, 0, 1, top)
        return Library:Create("Frame", { BackgroundTransparency = 1, BorderSizePixel = 0, Position = position, Size = size, ZIndex = 3, Parent = frameOf(parent) })
    end

    local function text(parent, value, props)
        props = props or {}
        props.Text, props.Parent = value, frameOf(parent)
        props.BackgroundTransparency = 1
        props.TextXAlignment = props.TextXAlignment or Enum.TextXAlignment.Left
        props.TextTruncate = props.TextTruncate or Enum.TextTruncate.AtEnd
        props.TextSize = props.TextSize or Library.FontSize
        props.Size = props.Size or UDim2.new(1, 0, 1, 0)
        props.ZIndex = props.ZIndex or 4
        return Library:CreateLabel(props)
    end

    local function hidePlaceholder(section)
        local raw = section and section.raw
        if not (raw and raw.Container) then return end
        for _, child in ipairs(raw.Container:GetChildren()) do
            if child:IsA("TextLabel") and child.Text == "Not built yet" then child.Visible = false end
        end
        pcall(function() raw:Resize() end)
    end
    Avatar.hidePlaceholder = hidePlaceholder

    local function idsIn(textValue)
        local ids = {}
        for number in string.gmatch(tostring(textValue or ""), "%d+") do
            local value = tonumber(number)
            if value and value > 0 then ids[#ids + 1] = value end
        end
        return ids
    end

    local function pillRow(parent, top, list, height)
        height = height or 26
        local frame = area(parent, top, height)
        local total, gap = #list, 6
        local made = {}
        for index, spec in ipairs(list) do
            local holder = Library:Create("Frame", {
                BackgroundTransparency = 1, ZIndex = 3, Parent = frame,
                Position = UDim2.new((index - 1) / total, math.floor(gap * (index - 1) / total), 0, 0),
                Size = UDim2.new(1 / total, -math.floor(gap * (total - 1) / total), 1, 0),
            })
            made[index] = Library:CreatePill(holder, spec[1], spec[2], { Height = height, Width = "Fill" })
        end
        return table.unpack(made)
    end

    local function caption(parent, top, value)
        return text(area(parent, top, 14), string.upper(value), { Dim = true, TextSize = Library.FontSize - 2 })
    end

    local function thumb(kind, id) return string.format("rbxthumb://type=%s&id=%d&w=150&h=150", kind, id) end

    local ui
    local function buildCanvas(out)
        ui = { token = 0, view = nil }
        Avatar.ui = ui
        local right, pages = out.right, out.pages
        if right.Scroll then right.Scroll.Visible = false end
        for _, name in ipairs({ "Catalog", "Body", "By ID", "Outfits", "Players", "Favorites" }) do
            local page = pages:GetPage(name)
            if page and page.Scroll then page.Scroll.Visible = false end
        end
        Avatar.defaultRig()

        local headRow = area(right, 0, 26)
        ui.mine = Library:CreatePill(headRow, "My avatar", function() task.spawn(Avatar.loadMine) end, { Height = 26 })
        ui.rig = Library:CreateSegmented(headRow, { Items = { "R6", "R15" }, Default = Builder.rig, Style = "Pill", Fill = true, Height = 26, Position = UDim2.new(1, -104, 0, 0), Size = UDim2.fromOffset(104, 26), Callback = function(rig)
            Builder.rig, Builder.rigSet = rig, true
            if ui.rebuildPreview then ui.rebuildPreview() end
        end })
        ui.view = Library:CreateViewport(area(right, 34, nil, 162), { Height = "Fill", FOV = 35, AutoRotate = true, Hint = "drag to rotate, wheel to zoom", Fallback = "rbxthumb://type=Avatar&id=%d&w=420&h=420" })
        ui.wearTitle = text(area(right, -156, 16), "Wearing", { Dim = true, TextSize = Library.FontSize - 1 })
        ui.strip = Library:CreateStrip(right, { Height = 70, TileSize = 54, Remove = true, EmptyText = "Nothing worn", Position = UDim2.new(0, 0, 1, -136), Callback = function(item)
            if item and item.worn then
                pcall(Avatar.removeItem, item.worn)
                Avatar.changed()
            end
        end })
        local respawnText = function() return store.reapply == false and "Respawn: off" or "Respawn: on" end
        ui.apply = pillRow(right, -58, { { "Apply to me", function()
            if not Builder.desc then return notify("Avatar builder: still loading your avatar") end
            task.spawn(Avatar.applyBuilt, Builder.desc)
        end } })
        ui.reset, ui.respawn = pillRow(right, -26, {
            { "Reset to mine", function() task.spawn(Avatar.reset) end },
            { respawnText(), function(pill)
                store.reapply = store.reapply == false
                pill:SetText(respawnText())
                pill:SetActive(store.reapply ~= false)
                Avatar.save()
            end },
        })
        ui.respawn:SetActive(store.reapply ~= false)

        local previewModel
        function ui.rebuildPreview()
            Builder.stamp = Builder.stamp + 1
            local stamp = Builder.stamp
            ui.view:SetStatus("building preview...")
            task.delay(0.25, function()
                if stamp ~= Builder.stamp or not Builder.desc or Library.Unloaded then return end
                local rig = Builder.rig == "R6" and Enum.HumanoidRigType.R6 or Enum.HumanoidRigType.R15
                local ok, model = pcall(function() return Players:CreateHumanoidModelFromDescription(Builder.desc:Clone(), rig) end)
                if not ok or not model then
                    ui.view:SetStatus("preview unavailable (" .. Builder.rig .. "), items still apply")
                    return
                end
                pcall(assembleModel, model)
                for _, part in ipairs(model:GetDescendants()) do
                    if part:IsA("BasePart") then
                        part.Anchored = true
                    elseif part:IsA("LuaSourceContainer") or part:IsA("Sound") then
                        pcall(function() part:Destroy() end)
                    end
                end
                ui.view:SetModel(model, previewModel ~= nil)
                previewModel = true
                pcall(function() model:Destroy() end)
                ui.view:SetStatus(Builder.rig .. " preview, Apply to me uses your game rig")
            end)
        end

        local function refreshWorn()
            local items = {}
            for _, worn in ipairs(Avatar.wornItems()) do
                items[#items + 1] = { Id = worn.label .. worn.id, Name = worn.label, Image = Avatar.thumbAsset(worn.id), worn = worn }
            end
            ui.strip:SetItems(items)
            ui.wearTitle.Text = string.format("WEARING (%d)  |  click a tile to take it off", #items)
        end
