    fallbackRows(Shoot, shootRows)

    function Preview.animate(now)
        local lanes = Preview.lanes
        if not lanes or not Preview.shown[Preview.shootPane] or Preview.view ~= "Tracers" then return end
        for _, strip in ipairs(lanes) do tickStrip(strip, now) end
        if Preview.decorate() then Preview.flush() end
        local step = math.floor(now * 15)
        if step == Preview.tileStep or not Preview.tiles then return end
        Preview.tileStep = step
        for _, strip in ipairs(Preview.tiles) do tickStrip(strip, now) end
        count("ticks")
    end

    local FACES = { { 1, 0, "Up" }, { 1, 2, "Down" }, { 1, 1, "Front" }, { 3, 1, "Back" }, { 0, 1, "Left" }, { 2, 1, "Right" } }
    previewPane(Effects.Ambience, function(pane)
        local views = {}
        local bar = Library:CreateSegmented(area(pane, 0, 26), { Items = { "Skyboxes", "Atmosphere" }, Default = "Skyboxes", Style = "Pill", Fill = true, Height = 26, Callback = function(name)
            for viewName, frame in pairs(views) do frame.Visible = viewName == name end
        end })
        Preview.skyBar = bar
        local skyView = area(pane, 34)
        local atmosView = area(pane, 34)
        atmosView.Visible = false
        views.Skyboxes, views.Atmosphere = skyView, atmosView

        local CELL = 44
        local net = Library:Create("Frame", { BackgroundTransparency = 1, Position = UDim2.new(0.5, -2 * CELL, 0, 0), Size = UDim2.fromOffset(4 * CELL, 3 * CELL), ZIndex = 4, Parent = skyView })
        local images = {}
        for index, face in ipairs(FACES) do
            local cell = Library:CreateBevel(net, { Color = "InputColor", Radius = 3, Position = UDim2.fromOffset(face[1] * CELL + 1, face[2] * CELL + 1), Size = UDim2.fromOffset(CELL - 2, CELL - 2), ZIndex = 5 })
            text(cell, face[3], { Dim = true, TextSize = Library.FontSize - 3, TextXAlignment = Enum.TextXAlignment.Center })
            images[index] = Library:Create("ImageLabel", { BackgroundTransparency = 1, Image = "", ScaleType = Enum.ScaleType.Crop, Size = UDim2.new(1, 0, 1, 0), ZIndex = 8, Parent = cell })
        end
        Preview.netImages = images
        local status = text(area(skyView, 3 * CELL + 6, 16), "", { Dim = true, TextSize = Library.FontSize - 1, TextXAlignment = Enum.TextXAlignment.Center })

        local skyList
        skyList = Library:CreateGallery(area(skyView, 3 * CELL + 28), { Height = "Fill", View = "List", Virtual = true, RowHeight = 32, Search = true, Title = "Skyboxes", Callback = function(item, _, selected)
            if selected and item then setOption("world_sky_box", item.Name) end
            Preview.dirty[Preview.refreshSky] = true
        end })
        local function refreshNet()
            local ok, ids = pcall(World.skyIds)
            ids = ok and type(ids) == "table" and ids or nil
            for index, image in ipairs(images) do image.Image = ids and ids[index] or "" end
            local choice = tostring(flag("world_sky_box", "?"))
            if not ids then
                status.Text = choice .. ": no faces to show yet"
            else
                status.Text = choice .. (flag("world_skybox", false) and "  |  applied" or "  |  turn on Custom skybox to apply")
            end
            pcall(function() skyList:SetValue(flag("world_sky_box", nil)) end)
            count("sky")
        end
        Preview.refreshSky = refreshNet

        local items = {}
        local control = Options.world_sky_box
        for _, name in ipairs(control and control.Values or {}) do
            items[#items + 1] = { Id = name, Name = name, Actions = { { Text = "Apply", Callback = function(item)
                setOption("world_sky_box", item.Name)
                setOption("world_skybox", true)
                Preview.dirty[refreshNet] = true
            end } } }
        end
        skyList:SetItems(items)

        local atmosList
        atmosList = Library:CreateGallery(atmosView, { Height = "Fill", View = "List", RowHeight = 36, Title = "Atmosphere presets", Callback = function(item, _, selected)
            if selected and item then setOption("world_atmos_preset", item.Name) end
            pcall(function() atmosList:SetValue(flag("world_atmos_preset", nil)) end)
        end })
        local atmosItems = {}
        local atmosControl = Options.world_atmos_preset
        for _, name in ipairs(atmosControl and atmosControl.Values or {}) do
            atmosItems[#atmosItems + 1] = { Id = name, Name = name, Subtitle = "copies into World > Post > Atmosphere", Actions = { { Text = "Apply", Callback = function(item)
                setOption("world_atmos_preset", item.Name)
                Util.guard("atmos-preset", World.atmosPreset)
            end } } }
        end
        atmosList:SetItems(atmosItems)
        pcall(function() atmosList:SetValue(flag("world_atmos_preset", nil)) end)

        watch({ "world_sky_box", "world_skybox", "world_sky_custom", "world_sky_single", "world_sky_saved_pick" }, refreshNet)
        Preview.flush()
    end)

    function Preview.step(_, now)
        Preview.flush()
        Preview.animate(now)
    end

    Util.onUnload(function()
        Preview.dirty, Preview.lanes, Preview.tiles, Preview.tileSource, Preview.shootPane, Preview.shown = {}, nil, nil, nil, nil, {}
    end)

    Util.effectsPreview = Preview
    Util.systems = Util.systems or {}
    table.insert(Util.systems, { name = "fx_preview", fn = Preview.step, priority = 150 })
end
-- pl 99_loop 2-74: Loop
do
    Loop = { last = os.clock(), frames = 0, fpsAt = os.clock(), fps = 60, systems = {}, records = {} }

    function Loop.register(name, fn, priority)
        Loop.unregister(name)
        table.insert(Loop.systems, { name = name, fn = fn, priority = priority or 100 })
        table.sort(Loop.systems, function(a, b) return a.priority < b.priority end)
    end

    function Loop.unregister(name)
        for index, entry in ipairs(Loop.systems) do
            if entry.name == name then table.remove(Loop.systems, index) return true end
        end
        return false
    end

    Loop.synced = 0
    function Loop.sync()
        local list = Util.systems
        if type(list) ~= "table" then return end
        for index = Loop.synced + 1, #list do
            local entry = list[index]
            if type(entry) == "table" and type(entry.name) == "string" and type(entry.fn) == "function" then
                Loop.register(entry.name, entry.fn, entry.priority)
            end
        end
        Loop.synced = #list
    end

    function Loop.step()
        Loop.sync()
        Game.frame = Game.frame + 1
        local now = os.clock()
        local dt = math.clamp(now - Loop.last, 1 / 240, 0.1)
        Loop.last = now
        Loop.frames = Loop.frames + 1
        if now - Loop.fpsAt >= 0.5 then
            Loop.fps = math.floor(Loop.frames / (now - Loop.fpsAt))
            Loop.frames, Loop.fpsAt = 0, now
        end
        Util.guard("visible", Visible.refresh, now)
        local ok, records = pcall(Entities.update)
        if not ok then
            Util.note("entities" .. tostring(records), "entities:", records)
            records = {}
        end
        Loop.records = records
        local snapshot = table.move(Loop.systems, 1, #Loop.systems, 1, {})
        for _, entry in ipairs(snapshot) do Util.guard(entry.name, entry.fn, dt, now, records) end
    end

    local function loopFrame()
        if Library.Unloaded then return end
        local ok, problem = pcall(Loop.step)
        if not ok then Util.note("loop" .. tostring(problem), "frame:", problem) end
    end

    local LOOP_BIND = Util.randomName()
    local okCameraPriority, cameraPriority = pcall(function() return Enum.RenderPriority.Camera.Value end)
    if okCameraPriority and type(cameraPriority) == "number" and pcall(function() RunService:BindToRenderStep(LOOP_BIND, cameraPriority + 2, loopFrame) end) then
        Util.onUnload(function() pcall(function() RunService:UnbindFromRenderStep(LOOP_BIND) end) end)
    else
        Util.track(RunService.RenderStepped:Connect(loopFrame))
    end

    Loop.sync()

    Util.onUnload(function()
        Loop.systems, Loop.records = {}, {}
        Util.systems, Loop.synced = {}, 0
        if getgenv().Library == Library then getgenv().Library = nil end
    end)
end
